/* Ghi chú học từ AWL (tự biên soạn) – Vocaband, CC BY-SA 4.0 */
(function (g) { const N = g.WORD_NOTES = g.WORD_NOTES || {}; Object.assign(N, {
  "analyse": { m: "ana- (tách ra) + lyse (tháo, gỡ) → tháo rời từng phần để xem xét kỹ.", e: "Sai: analyse about the data → Đúng: analyse the data (không dùng about). Chính tả: analyse (Anh) / analyze (Mỹ).", u: "Rất hay dùng trong IELTS Writing Task 1: analyse data/results/trends; carefully analyse. Trang trọng hơn 'look at'.", f: "analysis (n), analyst (n), analytical (adj), analytically (adv)" },
  "approach": { m: "ap- (hướng tới) + proach (gần, như 'proximity') → tiến lại gần một vấn đề → cách tiếp cận.", e: "Sai: approach to the problem (khi là động từ) → Đúng: approach the problem. Danh từ mới đi với to: an approach to learning.", u: "Collocations: take/adopt an approach, a new/different approach to sth, a practical approach. Dùng khi bàn giải pháp trong IELTS Task 2.", f: "approach (v), approachable (adj), unapproachable (adj)" },
  "area": { m: "Liên tưởng 'arena' (đấu trường) → một vùng không gian; mở rộng nghĩa thành lĩnh vực.", e: "Phát âm sai: /a-ri-a/ → Đúng: /ˈeə.ri.ə/ (E-ri-a), nhấn âm 1.", u: "Nghĩa địa lý: urban/rural area, residential area. Nghĩa trừu tượng: an area of research/expertise, key areas. Rất phổ biến trong Task 1 bản đồ.", f: "areas (n, số nhiều)" },
  "assess": { m: "as- (bên cạnh) + sess (ngồi, như 'session') → ngồi cạnh để xem xét, định giá → đánh giá.", e: "Sai: assess about the risk → Đúng: assess the risk. Chính tả: hai cặp s (a-ss-e-ss).", u: "Collocations: assess the impact/risk/damage, assess students, accurately assess. Trang trọng hơn 'judge', hợp văn học thuật và báo cáo công việc.", f: "assessment (n), assessor (n), assessable (adj)" },
  "assume": { m: "as- (về phía) + sume (lấy, như 'consume') → tự lấy một điều làm đúng → giả định.", e: "Sai: I assume that he will comes → Đúng: I assume that he will come. Nhầm danh từ: assume (v) ≠ assumption (n).", u: "Collocations: it is widely assumed that, assume responsibility (đảm nhận trách nhiệm). Dùng để nêu giả định trong bài luận; tránh khẳng định quá mạnh.", f: "assumption (n), assumed (adj), assuming (conj)" },
  "authority": { m: "Gốc author (tác giả, người tạo ra) → người có quyền quyết định → thẩm quyền, chính quyền.", e: "Nhầm: authority (thẩm quyền) ≠ author (tác giả). Sai: the authority (chỉ chính quyền) → thường dùng: the authorities. Nhấn âm 2: au-THO-ri-ty.", u: "Collocations: local authorities, have the authority to do sth, abuse of authority, an authority on (chuyên gia về). Trang trọng.", f: "authorise/authorize (v), authoritative (adj), authoritarian (adj), authorisation (n)" },
  "available": { m: "a- + vail (giá trị, sức mạnh, như 'value') + -able → có thể dùng được ngay → có sẵn.", e: "Sai: The room is available for to use → Đúng: The room is available for use / available to use. Nhấn âm 2: a-VAI-la-ble.", u: "Collocations: readily/widely available, available to the public, make sth available. Thường đứng sau danh từ: the best option available.", f: "availability (n), unavailable (adj)" },
  "benefit": { m: "bene- (tốt, như 'benevolent') + fit (làm, từ facere) → điều làm ra tốt lành → lợi ích.", e: "Sai: benefit for the society → Đúng: benefit to society / benefit society (động từ). Society chung chung không cần 'the'.", u: "Collocations: the benefits of sth, bring/provide benefits, benefit from sth, mutual benefit. Dùng nhiều trong bài advantages/disadvantages của IELTS.", f: "benefit (v), beneficial (adj), beneficiary (n)" },
  "concept": { m: "con- (cùng) + cept (lấy, nắm, như 'accept') → nắm bắt ý tưởng trong đầu → khái niệm.", e: "Nhấn sai: con-CEPT → Đúng: CON-cept (nhấn âm 1). Đừng nhầm concept (khái niệm) với conception (sự thụ thai, sự hình thành).", u: "Collocations: a basic/key concept, the concept of freedom, grasp a concept, a difficult concept to understand. Dùng trong bài luận học thuật.", f: "conceptual (adj), conceptualise/conceptualize (v), conception (n)" },
  "consist": { m: "con- (cùng nhau) + sist (đứng, như 'assist') → các phần đứng cùng nhau tạo thành → bao gồm.", e: "Sai: The team is consisted of five people → Đúng: The team consists of five people (không dùng bị động).", u: "Cấu trúc: consist of (gồm có), consist in (nằm ở, trang trọng). Hữu ích khi mô tả cấu trúc trong IELTS Task 1 dạng process/map.", f: "consistent (adj), consistency (n), consistently (adv)" },
  "constitute": { m: "con- (cùng) + stitute (đặt, dựng, như 'institute') → dựng các phần lại với nhau → cấu thành.", e: "Sai: Women are constituted 40% of workers → Đúng: Women constitute 40% of workers (dùng chủ động khi nói tỉ lệ).", u: "Rất trang trọng. Collocations: constitute a threat/problem, constitute the majority. Thay 'make up' trong IELTS Task 1 khi nói phần trăm.", f: "constitution (n), constitutional (adj), constituent (n, adj), constituency (n)" },
  "context": { m: "con- (cùng) + text (văn bản, dệt) → phần dệt quanh văn bản → bối cảnh.", e: "Sai: on this context → Đúng: in this context. Nhấn âm 1: CON-text.", u: "Collocations: in the context of, historical/social context, put sth into context, out of context. Phổ biến trong bài viết học thuật.", f: "contextual (adj), contextualise/contextualize (v)" },
  "contract": { m: "con- (cùng nhau) + tract (kéo, như 'tractor') → hai bên kéo về một thỏa thuận → hợp đồng.", e: "Trọng âm: CON-tract (n, hợp đồng) nhưng con-TRACT (v, co lại; mắc bệnh). Sai: make a contract with → nên: sign a contract with.", u: "TOEIC rất hay gặp: sign/renew/terminate a contract, under contract, breach of contract, a two-year contract.", f: "contractor (n), contractual (adj), contraction (n), contract (v)" },
  "create": { m: "Gốc Latin creare (sinh ra), liên quan 'crescent' (lớn dần) → làm cho xuất hiện → tạo ra.", e: "Nhầm từ loại: Sai: She is very create → Đúng: She is very creative. create (v), creative (adj), creation (n).", u: "Collocations: create jobs/opportunities/problems, create a sense of. Trong IELTS dùng thay 'make' để tăng tính học thuật.", f: "creation (n), creative (adj), creativity (n), creator (n), creatively (adv)" },
  "data": { m: "Gốc Latin datum (điều được cho) → những điều được cung cấp → dữ liệu.", e: "Sai: a data, datas → Đúng: data (không đếm được hoặc số nhiều): The data show/shows... ; a piece of data.", u: "IELTS Task 1: the data shows/indicates, collect/analyse data, data on sth. Văn học thuật trang trọng dùng 'the data are'.", f: "datum (n, số ít, hiếm), database (n)" },
  "define": { m: "de- (hoàn toàn) + fine (ranh giới, như 'finish') → vạch rõ ranh giới → định nghĩa, xác định.", e: "Sai: define about success → Đúng: define success. Nhầm: definite (chắc chắn) ≠ definition (định nghĩa).", u: "Collocations: clearly define, define sth as sth, be defined by. Mở bài IELTS: Success can be defined as...", f: "definition (n), definite (adj), definitely (adv), definitive (adj), undefined (adj)" },
  "derive": { m: "de- (từ) + rive (dòng sông, như 'river') → nước chảy ra từ nguồn → bắt nguồn, thu được.", e: "Sai: This word derives in Latin → Đúng: This word derives from Latin / is derived from Latin.", u: "Collocations: derive pleasure/benefit from, be derived from. Trang trọng, hợp văn học thuật thay cho 'get from'.", f: "derivation (n), derivative (n, adj), derived (adj)" },
  "distribute": { m: "dis- (ra nhiều phía) + tribute (trao, như 'contribute') → trao ra khắp nơi → phân phối.", e: "Sai: distribute leaflets for people → Đúng: distribute leaflets to people. Nhấn âm 2: dis-TRI-bute.", u: "Collocations: distribute goods/products, evenly/widely distributed, distribute among. TOEIC: distribution centre, distributor.", f: "distribution (n), distributor (n), distributive (adj)" },
  "economy": { m: "eco- (nhà, như 'ecology') + nomy (quản lý) → quản lý việc nhà → quản lý của cải quốc gia.", e: "Nhầm từ loại: economic (thuộc kinh tế) ≠ economical (tiết kiệm). Sai: an economic car → Đúng: an economical car. Nhấn: e-CO-no-my.", u: "Collocations: the global/national economy, boost/stimulate the economy, a growing economy. Rất hay gặp trong IELTS Task 2.", f: "economic (adj), economical (adj), economics (n), economist (n), economise/economize (v)" },
  "environment": { m: "en- (trong) + viron (vòng quanh) + -ment → những gì bao quanh ta → môi trường.", e: "Chính tả hay sai: enviroment → Đúng: environment (có n trước m). Nói chung về tự nhiên dùng 'the environment'.", u: "Collocations: protect/harm the environment, environmental damage/protection, a working environment. Chủ đề phổ biến IELTS Task 2.", f: "environmental (adj), environmentally (adv), environmentalist (n)" },
  "establish": { m: "Gốc stabilis (vững, như 'stable') → làm cho đứng vững → thành lập, xác lập.", e: "Sai: The company was established since 1990 → Đúng: The company was established in 1990.", u: "Collocations: establish a company/relationship, establish that (chứng minh rằng), well-established. Trang trọng hơn 'set up'.", f: "establishment (n), established (adj), re-establish (v)" },
  "estimate": { m: "Gốc Latin aestimare (định giá), cùng gốc 'esteem' → định giá trị → ước tính.", e: "Phát âm: động từ /ˈes.tɪ.meɪt/ (-mây), danh từ /ˈes.tɪ.mət/ (-mợt). Sai: estimate about 50 → Đúng: estimate at 50.", u: "Collocations: it is estimated that, an estimated 2 million, a rough estimate. Rất hữu ích trong IELTS Task 1 khi nói số liệu dự đoán.", f: "estimation (n), estimated (adj), underestimate (v), overestimate (v)" },
  "evident": { m: "e- (ra ngoài) + vid (nhìn thấy, như 'video') → hiện ra để nhìn thấy → rõ ràng.", e: "Nhầm từ loại: Sai: There is no evident for this → Đúng: There is no evidence for this. evident (adj), evidence (n).", u: "Collocations: it is evident that, become evident, clearly evident. Trang trọng hơn 'clear'; hợp khi rút kết luận từ dữ liệu.", f: "evidence (n), evidently (adv)" },
  "export": { m: "ex- (ra ngoài) + port (mang, như 'portable') → mang hàng ra ngoài → xuất khẩu.", e: "Trọng âm: EX-port (n) nhưng ex-PORT (v). Sai: export goods for Japan → Đúng: export goods to Japan.", u: "Collocations: export earnings, the main exports, export market, ban exports. Hay xuất hiện trong biểu đồ IELTS Task 1 và TOEIC.", f: "export (v), exporter (n), exportation (n)" },
  "factor": { m: "Gốc facere (làm), như 'factory' → thứ làm nên kết quả → yếu tố.", e: "Sai: a factor affects to health → Đúng: a factor affecting health / a factor in health problems (không dùng affect to).", u: "Collocations: a key/major factor, a contributing factor, a factor in sth, risk factors. Dùng nhiều khi phân tích nguyên nhân trong Task 2.", f: "factor (v), factorial (adj)" },
  "finance": { m: "Gốc Pháp finer (thanh toán xong), như 'finish' → kết thúc nợ nần → tiền bạc, tài chính.", e: "Nhầm từ loại: Sai: finance problems → Đúng: financial problems. Nhấn âm: FI-nance hoặc fi-NANCE đều được.", u: "Collocations: personal finances, finance a project (v), the finance department, public finance. Hay gặp trong TOEIC.", f: "financial (adj), financially (adv), financier (n), finance (v)" },
  "formula": { m: "form (hình dạng) + -ula (nhỏ) → khuôn mẫu nhỏ để làm theo → công thức.", e: "Số nhiều: formulas (thông dụng) hoặc formulae (khoa học). Sai: formulars → Đúng: formulas.", u: "Collocations: a formula for success, a mathematical formula, baby formula (sữa công thức), there is no magic formula.", f: "formulate (v), formulation (n), formulaic (adj)" },
  "function": { m: "Gốc Latin fungi (thực hiện) → việc được thực hiện → chức năng.", e: "Nhầm từ loại: Sai: The machine functional well → Đúng: The machine functions well. function (v, n), functional (adj).", u: "Collocations: perform a function, the main function of, function as. Dùng mô tả bộ phận trong IELTS Task 1 dạng process/diagram.", f: "functional (adj), functionally (adv), functionality (n), dysfunctional (adj)" },
  "identify": { m: "Gốc idem (giống, như 'identical') + -fy (làm) → xác nhận là cùng một → nhận diện.", e: "Sai: identify about the cause → Đúng: identify the cause. Nhấn âm 2: i-DEN-ti-fy.", u: "Collocations: identify problems/causes, identify sb as, clearly identified. Trang trọng hơn 'find out', hợp văn học thuật.", f: "identification (n), identity (n), identifiable (adj), identical (adj)" },
  "income": { m: "in (vào) + come (đến) → tiền đi vào túi → thu nhập.", e: "Sai: a big/small income → Đúng: a high/low income. Cũng tránh: income of month → nên: monthly income.", u: "Collocations: high/low income, income tax, a source of income, household income, low-income families. Phổ biến trong biểu đồ IELTS.", f: "incomes (n, số nhiều)" },
  "indicate": { m: "in- (vào) + dic (chỉ, nói, như 'dictionary') → chỉ vào điều gì → cho thấy.", e: "Sai: The data indicate about a rise → Đúng: The data indicate a rise / indicate that prices rose.", u: "IELTS Task 1: the graph indicates that, as indicated in the chart. Collocations: clearly indicate, research indicates. Trang trọng hơn 'show'.", f: "indication (n), indicator (n), indicative (adj)" },
  "individual": { m: "in- (không) + divid (chia, như 'divide') + -ual → không thể chia nhỏ hơn → cá nhân.", e: "Sai: Each individuals has rights → Đúng: Each individual has rights (each + danh từ số ít). Nhấn âm 3: in-di-VI-du-al.", u: "Collocations: individual needs, the rights of the individual, on an individual basis. Trang trọng hơn 'person' trong văn học thuật.", f: "individually (adv), individuality (n), individualism (n), individualistic (adj)" },
  "interpret": { m: "inter- (giữa) + pret (giá trị, trao đổi) → đứng giữa hai bên để giải nghĩa → diễn giải.", e: "Nhầm: interpret (phiên dịch nói) ≠ translate (dịch viết). Sai: interpret this book → Đúng: translate this book. Nhấn âm 2.", u: "Collocations: interpret data/results, interpret sth as, be open to interpretation. Hay dùng khi bàn về số liệu, nghệ thuật.", f: "interpretation (n), interpreter (n), misinterpret (v), interpretive (adj)" },
  "involve": { m: "in- (vào trong) + volve (cuộn, như 'revolve') → cuộn vào bên trong → liên quan, bao gồm.", e: "Sai: The job involves to travel → Đúng: The job involves travelling (involve + V-ing). Sai: involve into → Đúng: be involved in.", u: "Collocations: be involved in, get involved, involve risk, directly involved. Dùng khi mô tả nhiệm vụ công việc trong TOEIC.", f: "involvement (n), involved (adj), uninvolved (adj)" },
  "issue": { m: "Gốc Pháp issir (đi ra), liên quan 'exit' → điều nổi lên cần giải quyết → vấn đề.", e: "Nhầm: issue (vấn đề cần bàn) ≠ problem (sự cố). Sai: discuss about the issue → Đúng: discuss the issue.", u: "Collocations: a key/controversial issue, raise/address/tackle an issue, environmental issues. Trung tính, lịch sự hơn 'problem'.", f: "issue (v), issuer (n)" },
  "labour": { m: "Gốc Latin labor (vất vả), như 'laboratory' (nơi làm việc) → sức lao động.", e: "Chính tả: labour (Anh) / labor (Mỹ). Sai: a cheap labour → Đúng: cheap labour (không đếm được).", u: "Collocations: labour force, manual labour, labour costs, the labour market, skilled labour. Hay gặp trong chủ đề kinh tế IELTS.", f: "laborious (adj), labourer/laborer (n), labour (v)" },
  "legal": { m: "Gốc Latin lex, legis (luật), như 'legislation' → thuộc về luật → hợp pháp.", e: "Nhầm: legal (hợp pháp) ≠ legitimate (chính đáng). Sai: unlegal → Đúng: illegal (dạng phủ định dùng il-).", u: "Collocations: legal advice/action/system, take legal action against, the legal age, legally binding. Trang trọng, dùng nhiều trong TOEIC.", f: "illegal (adj), legally (adv), legality (n), legalise/legalize (v)" },
  "legislate": { m: "legis (luật) + late (mang, đưa ra) → đưa ra luật → ban hành luật.", e: "Sai: legislate a law about smoking → Đúng: legislate against smoking / pass legislation on smoking.", u: "Collocations: legislate against/for/on sth. Danh từ legislation (không đếm được): introduce/pass legislation. Rất trang trọng.", f: "legislation (n), legislative (adj), legislator (n), legislature (n)" },
  "major": { m: "Gốc Latin magnus, so sánh hơn major (lớn hơn), như 'majority' → chính, quan trọng hơn.", e: "Sai: a very major problem → Đúng: a major problem (major không đi với very). Không có dạng so sánh more major.", u: "Collocations: a major role/problem/change, major cities. Động từ Mỹ: major in (học chuyên ngành). Hữu ích trong Task 2.", f: "majority (n), major (n, v)" },
  "method": { m: "meta- (theo sau) + hodos (con đường) → con đường đi theo → phương pháp.", e: "Sai: a method to learning → Đúng: a method of learning / a method for learning. Nhấn âm 1: ME-thod.", u: "Collocations: teaching methods, an effective method, adopt/use a method, method of payment (TOEIC). Trang trọng hơn 'way'.", f: "methodical (adj), methodology (n), methodological (adj)" },
  "occur": { m: "oc- (về phía) + cur (chạy, như 'current') → chạy tới trước mặt → xảy ra.", e: "Chính tả: occurred, occurring, occurrence (gấp đôi r). Sai: The accident was occurred → Đúng: The accident occurred (không bị động).", u: "Trang trọng hơn 'happen'. Collocations: occur naturally, occur frequently, it occurred to me that (chợt nghĩ ra).", f: "occurrence (n)" },
  "percent": { m: "per (trên mỗi) + cent (một trăm, như 'century') → trên mỗi trăm → phần trăm.", e: "Nhầm: percent (sau số) ≠ percentage (không có số). Sai: a high percent → Đúng: a high percentage; 20 percent.", u: "IELTS Task 1: 20 percent of, rose by 5 percent. Viết Anh: per cent; Mỹ: percent. Dùng percentage với high/low/large.", f: "percentage (n), percentile (n)" },
  "period": { m: "peri- (vòng quanh, như 'perimeter') + hodos (đường) → một vòng đi trọn → khoảng thời gian.", e: "Sai: in the period of 1990 to 2000 → Đúng: over the period from 1990 to 2000 / in the period 1990-2000.", u: "IELTS Task 1: over the period shown, during the same period, a ten-year period. Mỹ còn dùng period = dấu chấm.", f: "periodic (adj), periodical (n, adj), periodically (adv)" },
  "policy": { m: "Gốc Hy Lạp polis (thành phố), như 'police', 'politics' → quy định quản lý thành phố → chính sách.", e: "Nhầm: policy (chính sách) ≠ politics (chính trị) ≠ police (cảnh sát). Sai: government's politic → Đúng: government policy.", u: "Collocations: implement/introduce a policy, government/company policy, policy on sth, policymakers. Hay gặp IELTS Task 2 và TOEIC.", f: "policies (n, số nhiều), policymaker (n)" },
  "principle": { m: "prin- (đầu tiên, như 'prince', 'primary') → điều đứng đầu, nền tảng → nguyên tắc.", e: "Nhầm chính tả: principle (nguyên tắc) ≠ principal (hiệu trưởng; chính). Sai: in principal → Đúng: in principle.", u: "Collocations: basic principles, in principle (về nguyên tắc), on principle, a matter of principle. Dùng trong lập luận đạo đức.", f: "principled (adj), unprincipled (adj)" },
  "proceed": { m: "pro- (về phía trước) + ceed (đi, như 'exceed') → đi tiếp về phía trước → tiến hành.", e: "Sai: proceed the meeting → Đúng: proceed with the meeting. Chính tả: proceed (-eed) nhưng procedure (-ed-).", u: "Collocations: proceed with sth, proceed to do sth, proceed to gate 5 (sân bay). Trang trọng, hay gặp trong TOEIC thông báo.", f: "procedure (n), proceedings (n), proceeds (n), procedural (adj)" },
  "process": { m: "pro- (về phía trước) + cess (đi, như 'proceed') → chuỗi bước tiến dần về phía trước → quá trình.", e: "Sai: process of make paper → Đúng: process of making paper (of + V-ing). Nhấn âm 1: PRO-cess.", u: "IELTS Task 1 dạng process: the process begins with, in the process of, a multi-stage process, process data (v).", f: "procession (n), processor (n), process (v), processing (n)" },
  "require": { m: "re- (lại) + quire (tìm, hỏi, như 'inquire') → hỏi lại đòi cho có → yêu cầu.", e: "Sai: require him do it → Đúng: require him to do it / it is required that he do it.", u: "Collocations: be required to, require attention/skills, as required. Trang trọng hơn 'need'; hay gặp trong tin tuyển dụng TOEIC.", f: "requirement (n), required (adj), requisite (adj)" },
  "research": { m: "re- (lại) + search (tìm kiếm) → tìm đi tìm lại kỹ lưỡng → nghiên cứu.", e: "Sai: a research, researches → Đúng: research (không đếm được) / a piece of research / studies. Sai: research about → Đúng: research into/on.", u: "Collocations: carry out/conduct research, research into sth, research shows that. Rất phổ biến trong IELTS Task 2.", f: "researcher (n), research (v)" },
  "respond": { m: "re- (lại) + spond (hứa, cam kết, như 'sponsor') → hứa đáp lại → phản hồi.", e: "Sai: respond my email → Đúng: respond to my email (respond phải có to).", u: "Collocations: respond to sth, respond quickly/positively, respond by doing sth. Trang trọng hơn 'reply'; hay gặp trong email TOEIC.", f: "response (n), responsive (adj), respondent (n), responsiveness (n)" },
  "role": { m: "Gốc Pháp rôle (cuộn giấy ghi lời diễn viên), như 'roll' → phần diễn → vai trò.", e: "Sai: play an important role on → Đúng: play an important role in. Chính tả: role (vai trò) ≠ roll (cuộn).", u: "Collocations: play a key/vital role in, take on a role, role model, gender roles. Cực kỳ phổ biến trong IELTS Task 2.", f: "roles (n, số nhiều), role-play (n, v)" },
  "section": { m: "sect (cắt, như 'insect', 'intersection') + -ion → phần được cắt ra → phần, mục.", e: "Nhầm: section (phần, mục) ≠ sector (ngành, khu vực kinh tế). Sai: the service section → Đúng: the service sector.", u: "Collocations: in section 2, a section of the population, the sports section (báo). TOEIC hay gặp trong hướng dẫn tài liệu.", f: "sectional (adj), section (v), subsection (n)" },
  "sector": { m: "sect (cắt) + -or → phần được cắt ra từ toàn bộ nền kinh tế → khu vực, ngành.", e: "Sai: private section → Đúng: private sector. Nói 'ngành' kinh tế dùng sector, không dùng section.", u: "Collocations: the public/private sector, the service/manufacturing sector, across all sectors. Phổ biến trong biểu đồ kinh tế IELTS.", f: "sectors (n, số nhiều), sectoral (adj)" },
  "significant": { m: "sign (dấu hiệu) + -ficant (làm) → để lại dấu hiệu rõ → đáng kể, quan trọng.", e: "Nhấn âm 2: sig-NI-fi-cant. Sai: a significant amount of people → Đúng: a significant number of people (people đếm được).", u: "IELTS Task 1: a significant rise/drop, significantly higher. Collocations: statistically significant, play a significant role.", f: "significance (n), significantly (adv), signify (v), insignificant (adj)" },
  "similar": { m: "Gốc Latin similis (giống), như 'simulate' → giống nhau → tương tự.", e: "Sai: similar with → Đúng: similar to. Sai: the similar → Đúng: the same / similar (không dùng the trước similar).", u: "Collocations: similar to, broadly/very similar, in a similar way. IELTS Task 1: a similar pattern/trend was seen in.", f: "similarity (n), similarly (adv), dissimilar (adj)" },
  "source": { m: "Gốc Pháp sourdre (vọt lên), liên quan 'surge' → nơi nước vọt lên → nguồn.", e: "Phát âm: /sɔːs/ dễ nhầm với sauce (nước sốt) trong tiếng Anh Anh. Sai: source of energies → Đúng: sources of energy.", u: "Collocations: a source of income/energy, a reliable source, renewable energy sources, sources say. Hay gặp IELTS chủ đề môi trường.", f: "source (v), sourcing (n), outsource (v)" },
  "specific": { m: "species (loại) + -fic (làm) → chỉ rõ một loại riêng → cụ thể.", e: "Sai: speak more specific → Đúng: speak more specifically (cần trạng từ). Nhấn âm 2: spe-CI-fic.", u: "Collocations: specific examples, specific to sth, be more specific. Dùng trong IELTS Task 2 khi đưa ví dụ: To be specific,...", f: "specifically (adv), specify (v), specification (n), specificity (n)" },
  "structure": { m: "struct (xây dựng, như 'construct') + -ure → cách được xây dựng → cấu trúc.", e: "Nhầm từ loại: Sai: The essay is well structure → Đúng: The essay is well structured. structure (n, v), structural (adj).", u: "Collocations: social/family structure, the structure of an essay, sentence structure. IELTS chấm phần cohesion dựa trên bố cục rõ ràng.", f: "structural (adj), structurally (adv), structured (adj), restructure (v)" },
  "theory": { m: "Gốc Hy Lạp theoria (ngắm nhìn), như 'theatre' → nhìn và suy ngẫm → lý thuyết.", e: "Sai: on theory → Đúng: in theory (trên lý thuyết). Nhấn âm 1: THEO-ry; theoretical nhấn âm 3.", u: "Collocations: in theory, a theory of sth, develop/test a theory, theory and practice. Dùng để đối lập lý thuyết với thực tế.", f: "theoretical (adj), theoretically (adv), theorist (n), theorise/theorize (v)" },
  "vary": { m: "Gốc Latin varius (khác nhau), như 'various', 'variety' → khác nhau, thay đổi.", e: "Nhầm: vary (thay đổi) ≠ very (rất). Sai: Prices vary with country → Đúng: Prices vary from country to country.", u: "Collocations: vary widely/considerably, vary from A to B, vary in size. IELTS Task 1: figures varied between 10% and 20%.", f: "variation (n), variety (n), various (adj), variable (adj, n), varied (adj)" },
  "achieve": { m: "a- (đến) + chief (đầu, đỉnh, như 'chief' = người đứng đầu) → đưa đến đỉnh, đạt tới mục tiêu.", e: "Sai: achieve to success → Đúng: achieve success (achieve đi thẳng với tân ngữ, không có to). Chú ý chính tả: ie, không phải ei.", u: "Collocations: achieve a goal/target, achieve success, achieve results. Thường dùng với mục tiêu cần nỗ lực; trang trọng hơn 'get'. Hay gặp trong IELTS Writing Task 2.", f: "achievement (n), achievable (adj), achiever (n), underachieve (v)" },
  "acquire": { m: "ad- (thêm vào) + quaerere (tìm kiếm, như 'query') → tìm và thêm về cho mình, thu nhận.", e: "Sai: acquire knowledges → Đúng: acquire knowledge (knowledge không đếm được). Nhấn âm 2: ac-QUIRE.", u: "Collocations: acquire skills/knowledge, acquire a language, acquire a company (mua lại). Trang trọng hơn 'get'; trong kinh doanh nghĩa là thâu tóm, mua lại công ty.", f: "acquisition (n), acquired (adj), acquisitive (adj)" },
  "administrate": { m: "ad- (hướng tới) + minister (người phục vụ) → phục vụ, lo việc điều hành cho một tổ chức.", e: "Sai: administrate the company (nghe gượng) → Đúng: administer/manage the company. Administrate ít dùng; administer phổ biến hơn.", u: "Hiếm và hơi cứng; nên dùng administer hoặc manage. Collocations: administer a programme, administer a test, administer medicine (cho uống thuốc).", f: "administer (v), administration (n), administrative (adj), administrator (n)" },
  "affect": { m: "ad- (tới) + facere (làm, như 'factory') → tác động tới. Mẹo: Affect là Action (động từ), Effect là kết quả (danh từ).", e: "Sai: affect to the economy → Đúng: affect the economy. Sai: have a big affect → Đúng: have a big effect (danh từ là effect).", u: "Collocations: directly/seriously/adversely affect, be affected by. Trang trọng hơn 'change'; thường dùng trong IELTS khi bàn về tác động tiêu cực.", f: "affected (adj), unaffected (adj), effect (n), affection (n - tình cảm, khác nghĩa)" },
  "appropriate": { m: "ad- (tới) + proprius (riêng, như 'property') → hợp với riêng nó, đúng chỗ, phù hợp.", e: "Sai: appropriate with the situation → Đúng: appropriate for/to the situation. Phát âm tính từ: a-PRO-pri-ət (âm cuối nhẹ, không đọc 'rate').", u: "Collocations: appropriate for/to, take appropriate action/measures, it is appropriate to do sth. Trang trọng hơn 'suitable'; hay gặp trong email TOEIC.", f: "appropriately (adv), inappropriate (adj), appropriateness (n), appropriate (v - chiếm dụng)" },
  "aspect": { m: "ad- (tới) + specere (nhìn, như 'spectator') → góc nhìn vào một vấn đề, tức là khía cạnh.", e: "Sai: in this aspect → Đúng: in this respect, hoặc in every aspect of life (aspect thường đi với of).", u: "Collocations: an important/key aspect of, every aspect of life, the financial/social aspects. Rất hữu ích để chia ý trong IELTS Writing.", f: "aspects (n, số nhiều), aspectual (adj, ngôn ngữ học)" },
  "assist": { m: "ad- (bên cạnh) + sistere (đứng, như 'insist') → đứng bên cạnh để giúp đỡ.", e: "Sai: assist me to do → Đúng: assist me in/with doing, hoặc help me (to) do. Assist dùng in/with + V-ing.", u: "Collocations: assist sb with sth, assist in doing sth, assist customers. Trang trọng hơn 'help'; rất phổ biến trong TOEIC (dịch vụ khách hàng).", f: "assistance (n), assistant (n), assisted (adj)" },
  "category": { m: "Gốc Hy Lạp kategoria (sự phân loại) → nhóm, loại. Liên tưởng: 'cat' trong danh mục loài vật.", e: "Sai: nhấn âm 2 ca-TE-go-ry → Đúng: nhấn âm 1 CAT-e-go-ry. Số nhiều: categories (đổi y thành ies).", u: "Collocations: fall into a category, a broad/wide category, belong to a category. Dùng để phân loại ý trong bài viết, mang sắc thái học thuật.", f: "categorize/categorise (v), categorical (adj), categorization (n)" },
  "chapter": { m: "Từ Latin caput (đầu, như 'capital') → phần mở đầu bằng một tiêu đề, tức là chương sách.", e: "Sai: in the chapter 3 → Đúng: in Chapter 3 (không dùng the trước Chapter + số).", u: "Collocations: the opening/final chapter, a new chapter in one's life (giai đoạn mới). Nghĩa bóng hay dùng trong IELTS Speaking.", f: "chapters (n, số nhiều)" },
  "commission": { m: "com- (cùng) + mittere (gửi, như 'mission') → nhóm người được cùng giao nhiệm vụ; hoặc phần tiền giao kèm.", e: "Sai: commision (thiếu s) → Đúng: commission (hai m, hai s). Sai: commission of sales → Đúng: commission on sales.", u: "Collocations: earn/receive commission, on commission, set up a commission. TOEIC: tiền hoa hồng bán hàng. Học thuật: ủy ban điều tra.", f: "commission (v), commissioner (n), commissioned (adj)" },
  "community": { m: "com- (cùng) + munis (nghĩa vụ, như 'common') → nhóm người cùng chia sẻ điều chung, tức là cộng đồng.", e: "Sai: the community have a problem (khi nói chung) → Đúng: the community has a problem. Nhấn âm 2: com-MU-ni-ty.", u: "Collocations: local community, the international community, community service, a sense of community. Rất phổ biến trong IELTS Writing về xã hội.", f: "communities (n), communal (adj), commune (n)" },
  "complex": { m: "com- (cùng) + plectere (đan, bện) → nhiều thứ đan vào nhau, nên phức tạp.", e: "Nhầm complex (phức tạp về cấu trúc) với complicated (rắc rối, khó hiểu). Nhấn âm: COM-plex (adj) hoặc com-PLEX đều chấp nhận.", u: "Collocations: a complex issue/problem, highly complex, complex relationship. Nghe học thuật hơn 'difficult'; dùng tốt trong IELTS. Danh từ complex: khu phức hợp.", f: "complexity (n), complex (n - khu phức hợp), complexly (adv)" },
  "compute": { m: "com- (cùng) + putare (tính, nghĩ) → gộp các con số lại để tính. Liên tưởng: computer = máy tính.", e: "Nhầm dạng: compute (v) với computation (n). Sai: the compute of data → Đúng: the computation of data.", u: "Collocations: compute the cost/average, computed value. Mang tính kỹ thuật, trang trọng; giao tiếp thường dùng 'calculate' hoặc 'work out'.", f: "computer (n), computation (n), computational (adj), computing (n)" },
  "conclude": { m: "con- (hoàn toàn) + claudere (đóng, như 'close') → đóng lại hoàn toàn: kết thúc hoặc đưa ra kết luận.", e: "Sai: In conclude, ... → Đúng: In conclusion, ... (dùng danh từ). Sai: conclude about → Đúng: conclude that...", u: "Collocations: conclude that, conclude with, conclude a deal/agreement. 'In conclusion' mở đoạn kết IELTS, nhưng đừng lạm dụng.", f: "conclusion (n), conclusive (adj), conclusively (adv), inconclusive (adj)" },
  "conduct": { m: "con- (cùng) + ducere (dẫn, như 'duct', 'lead') → dẫn dắt mọi thứ cùng diễn ra, tức là tiến hành.", e: "Nhấn âm: động từ con-DUCT, danh từ CON-duct (hạnh kiểm). Sai: conduct a research → Đúng: conduct research (research không đếm được).", u: "Collocations: conduct research/a survey/an experiment/an interview. Trang trọng hơn 'do'; rất tốt cho IELTS Writing Task 1 và 2.", f: "conduct (n), conductor (n), conductive (adj), misconduct (n)" },
  "consequent": { m: "con- (cùng) + sequi (theo sau, như 'sequence') → đi theo sau như một hệ quả.", e: "Nhầm consequent (hệ quả của) với consequential (quan trọng, hệ trọng). Sai: consequent of → Đúng: consequent on/upon.", u: "Rất trang trọng, thường đứng trước danh từ: the consequent rise in prices. Dạng hay dùng hơn: consequently (adv) để nối câu trong IELTS.", f: "consequence (n), consequently (adv), consequential (adj)" },
  "construct": { m: "con- (cùng) + struere (xếp, như 'structure') → xếp các phần với nhau để dựng lên.", e: "Nhấn âm: động từ con-STRUCT, danh từ CON-struct (khái niệm). Sai: the construct of the bridge → Đúng: the construction of the bridge.", u: "Collocations: construct a building/bridge, construct an argument/a theory. Trang trọng hơn 'build'; dùng được cả nghĩa trừu tượng.", f: "construction (n), constructive (adj), constructively (adv), reconstruct (v)" },
  "consume": { m: "con- (hoàn toàn) + sumere (lấy) → lấy dùng hết sạch, tức là tiêu thụ.", e: "Sai: consumption of energies → Đúng: energy consumption. Nhầm consumer (người tiêu dùng) với customer (khách hàng của một cửa hàng).", u: "Collocations: consume energy/resources/time, be consumed by (bị chi phối). Hay gặp trong IELTS Task 1 về mức tiêu thụ năng lượng, nước.", f: "consumption (n), consumer (n), consumerism (n), time-consuming (adj)" },
  "credit": { m: "Latin credere (tin, như 'credible') → được người khác tin: cho vay tín dụng, hoặc ghi nhận công lao.", e: "Sai: give credit for him → Đúng: give him credit for sth. Sai: buy by credit → Đúng: buy on credit.", u: "Collocations: credit card, on credit, take credit for, deserve credit, course credits (tín chỉ). TOEIC hay gặp nghĩa tài chính, ngân hàng.", f: "credit (v), creditor (n), creditable (adj), discredit (v)" },
  "culture": { m: "Latin colere (trồng trọt, như 'agriculture') → vun trồng lối sống, tư tưởng của một cộng đồng.", e: "Sai: Vietnam's culture is very diversity → Đúng: very diverse (dùng tính từ). Nhầm cultural (adj) và culture (n).", u: "Collocations: traditional/local culture, culture shock, popular culture, company culture. Đếm được khi nói nhiều nền văn hóa: different cultures.", f: "cultural (adj), culturally (adv), cultured (adj), multicultural (adj)" },
  "design": { m: "de- (ra) + signare (đánh dấu, như 'sign') → vạch ra dấu hiệu, phác thảo trước khi làm.", e: "Phát âm: g câm, đọc /dɪˈzaɪn/ với âm z. Sai: designer of the house is beautiful → Đúng: the design of the house is beautiful.", u: "Collocations: design a product/building, be designed to do sth, by design (cố ý). Dùng nhiều trong IELTS Task 1 dạng bản đồ, quy trình.", f: "design (n), designer (n), designed (adj)" },
  "distinct": { m: "dis- (tách) + stinguere (chích, đánh dấu) → được đánh dấu tách riêng, nên khác biệt rõ ràng.", e: "Nhầm distinct (rõ ràng, riêng biệt) với distinctive (đặc trưng, dễ nhận ra). Sai: distinct with → Đúng: distinct from.", u: "Collocations: distinct from, a distinct possibility, two distinct groups, clearly distinct. Học thuật; dùng để so sánh trong IELTS Writing.", f: "distinction (n), distinctive (adj), distinctly (adv), distinguish (v)" },
  "element": { m: "Từ Latin elementum (nguyên tố, thành phần cơ bản). Liên tưởng: elementary school dạy những điều cơ bản.", e: "Sai: nhấn âm 2 e-LE-ment → Đúng: nhấn âm 1 EL-e-ment. Chú ý chính tả: element, không phải elemant.", u: "Collocations: a key/essential element, an element of risk/truth (một chút). Học thuật; dùng tốt khi phân tích các thành phần của vấn đề.", f: "elemental (adj), elementary (adj)" },
  "equate": { m: "Latin aequus (bằng nhau, như 'equal') → coi hai thứ là bằng nhau.", e: "Sai: equate money and happiness → Đúng: equate money with happiness (equate A with B).", u: "Collocations: equate A with B, money does not equate to happiness. Thường mang ý phê phán sự đánh đồng sai; hữu ích trong IELTS Task 2.", f: "equation (n), equal (adj), equality (n), equivalent (adj)" },
  "evaluate": { m: "e- (ra) + value (giá trị) → rút ra giá trị của cái gì, tức là đánh giá.", e: "Sai: evaluate about the plan → Đúng: evaluate the plan. Nhấn âm 2: e-VAL-u-ate.", u: "Collocations: evaluate the effectiveness/impact/performance, carefully evaluate. Học thuật, khách quan hơn 'judge'; phổ biến trong báo cáo, TOEIC.", f: "evaluation (n), evaluative (adj), evaluator (n)" },
  "feature": { m: "Latin factura (sự tạo hình, như 'factory') → nét tạo nên hình dáng riêng, tức là đặc điểm.", e: "Sai: the main features is → Đúng: the main features are. Chính tả: feature, không phải feture.", u: "Collocations: a key/distinctive feature, safety features, feature in (xuất hiện). IELTS Task 1: 'summarise the main features' – chọn nét nổi bật.", f: "feature (v), featured (adj), featureless (adj)" },
  "final": { m: "Latin finis (kết thúc, như 'finish') → ở phần cuối cùng.", e: "Nhầm final (adj) với finally (adv). Sai: Final, I think... → Đúng: Finally, I think... Không viết finaly.", u: "Collocations: final decision/exam/stage/result, the final say. Dùng 'finally' để liệt kê ý cuối trong bài viết, khác 'in the end' (rốt cuộc).", f: "finally (adv), finalize/finalise (v), finality (n), finalist (n)" },
  "focus": { m: "Latin focus (lò sưởi, tâm điểm của căn nhà) → điểm trung tâm mà mọi thứ hướng vào.", e: "Sai: focus in/to studying → Đúng: focus on studying. Số nhiều danh từ: foci hoặc focuses.", u: "Collocations: focus on, shift the focus, the main focus, keep focused. Phổ biến trong cả IELTS Speaking và Writing.", f: "focus (n), focused (adj), refocus (v)" },
  "impact": { m: "im- (vào) + pangere (đóng chặt) → va mạnh vào, gây tác động lớn.", e: "Sai: impact to the environment → Đúng: impact on the environment. Nhấn âm danh từ: IM-pact.", u: "Collocations: have an impact on, a significant/negative/positive impact, environmental impact. Mạnh hơn 'effect'; đừng lặp quá nhiều trong IELTS.", f: "impact (v), impactful (adj)" },
  "injure": { m: "in- (không) + jus (đúng, quyền, như 'justice') → làm điều không đúng, gây tổn thương cho ai.", e: "Sai: He was injury in the accident → Đúng: He was injured. Nhầm injure (tai nạn) với wound (vũ khí) và hurt (chung).", u: "Collocations: be seriously/badly injured, injure one's back/leg. Thường dùng bị động; hay gặp trong tin tức về tai nạn.", f: "injury (n), injured (adj), injurious (adj)" },
  "institute": { m: "in- (vào) + statuere (đặt, dựng lên, như 'statue') → nơi được dựng lên lâu dài: viện, học viện.", e: "Nhầm institute (viện cụ thể) với institution (tổ chức, thể chế nói chung). Nhấn âm 1: IN-sti-tute.", u: "Collocations: research institute, institute of technology. Động từ institute (trang trọng): bắt đầu áp dụng, như institute a policy.", f: "institution (n), institutional (adj), institute (v)" },
  "invest": { m: "in- (vào) + vestis (áo, như 'vest') → khoác áo cho, đổ tiền hoặc công sức vào cái gì.", e: "Sai: invest to stocks → Đúng: invest in stocks. Sai: invest money for → Đúng: invest money in.", u: "Collocations: invest in, invest heavily, invest time/effort. Dùng tốt trong IELTS về giáo dục, hạ tầng: governments should invest in...", f: "investment (n), investor (n), reinvest (v)" },
  "item": { m: "Từ Latin item (cũng thế, như thế) dùng khi liệt kê từng mục trong danh sách.", e: "Phát âm: /ˈaɪtəm/ (ai-tờm), không đọc 'i-tem'. Sai: an item of furnitures → Đúng: an item of furniture.", u: "Collocations: an item of clothing/news, agenda items, luxury items. TOEIC: hóa đơn, kho hàng. Dùng để biến danh từ không đếm được thành đếm được.", f: "itemize/itemise (v), itemized (adj)" },
  "journal": { m: "Pháp jour (ngày) → ghi chép theo từng ngày; nay là tạp chí xuất bản định kỳ. Liên tưởng: journalist (nhà báo).", e: "Nhầm journal (tạp chí học thuật) với magazine (tạp chí giải trí). Sai: write journal every day → Đúng: keep a journal.", u: "Collocations: academic/scientific journal, publish in a journal, keep a journal (viết nhật ký). Mang tính học thuật, chuyên ngành.", f: "journalist (n), journalism (n), journalistic (adj)" },
  "maintain": { m: "Pháp main (tay) + tenir (giữ, như 'tenant') → giữ trong tay, duy trì.", e: "Chính tả danh từ: Sai: maintainance → Đúng: maintenance. Nhấn âm 2: main-TAIN, nhưng danh từ nhấn âm 1: MAIN-te-nance.", u: "Collocations: maintain a balance/relationship/standards, maintain that (khẳng định). TOEIC: maintenance team, bảo trì thiết bị.", f: "maintenance (n), maintainable (adj)" },
  "normal": { m: "Latin norma (thước vuông của thợ mộc) → đúng chuẩn, bình thường. Liên tưởng: norm (chuẩn mực).", e: "Sai: It is normal that students is... → Đúng: It is normal for students to... Không dùng 'normal' như trạng từ (dùng normally).", u: "Collocations: back to normal, above/below normal, the new normal, normal procedure. Trung tính; viết học thuật có thể thay bằng 'typical', 'standard'.", f: "normally (adv), normality (n), normalize (v), abnormal (adj)" },
  "obtain": { m: "ob- (hướng tới) + tenere (giữ) → nắm giữ được thứ mình hướng tới, thu được.", e: "Sai: obtain to a degree → Đúng: obtain a degree. Obtain cần tân ngữ trực tiếp, không đi với to.", u: "Collocations: obtain information/permission/a visa/data. Trang trọng hơn 'get'; rất hay gặp trong TOEIC và văn bản hành chính.", f: "obtainable (adj), unobtainable (adj)" },
  "participate": { m: "pars (phần, như 'part') + capere (lấy) → lấy một phần, tức là tham gia vào.", e: "Sai: participate the event → Đúng: participate in the event (luôn có in). Nhấn âm 2: par-TI-ci-pate.", u: "Collocations: participate in, actively participate, participate fully. Trang trọng hơn 'take part in'; dùng nhiều trong IELTS về giáo dục.", f: "participation (n), participant (n), participatory (adj)" },
  "perceive": { m: "per- (hoàn toàn) + capere (nắm bắt) → nắm bắt trọn vẹn bằng giác quan hoặc trí óc.", e: "Chính tả: perceive (ei sau c), không phải percieve. Sai: perceive him like a hero → Đúng: perceive him as a hero.", u: "Collocations: perceive as, be widely perceived as, perceived risk/value. Học thuật; nói về cách mọi người nhìn nhận vấn đề.", f: "perception (n), perceptive (adj), perceptible (adj), perceived (adj)" },
  "positive": { m: "Latin ponere (đặt, như 'position') → được đặt chắc chắn, khẳng định, nên mang nghĩa tích cực.", e: "Sai: I'm positive with the plan → Đúng: I'm positive about the plan. Nhầm positive (chắc chắn) với possible.", u: "Collocations: positive effect/impact/attitude, have a positive influence on, test positive. Dùng cặp positive/negative để cân bằng hai mặt trong IELTS.", f: "positively (adv), positivity (n), positivism (n)" },
  "potential": { m: "Latin potens (có sức mạnh, như 'potent', 'power') → có sức mạnh tiềm ẩn chưa bộc lộ.", e: "Sai: potential of success → Đúng: potential for success. Chính tả: potential với -tial, không phải -cial.", u: "Collocations: potential customers/risks/benefits, reach one's full potential, have potential. TOEIC: potential clients; IELTS: potential drawbacks.", f: "potential (n), potentially (adv), potentiality (n)" },
  "previous": { m: "pre- (trước) + via (con đường, như 'via') → đi trên con đường trước, nên là trước đó.", e: "Nhầm previous (trước đó) với precious (quý giá). Sai: the previous week of the trip → Đúng: the week before the trip.", u: "Collocations: previous year/experience/job, the previous day. TOEIC: 'previous experience required'. Trang trọng hơn 'last' hoặc 'earlier'.", f: "previously (adv)" },
  "primary": { m: "Latin primus (thứ nhất, như 'prime', 'premier') → đứng hàng đầu, chính yếu.", e: "Nhầm primary (chủ yếu) với primitive (nguyên thủy). Nhấn âm 1: PRI-ma-ry. Anh: primary school; Mỹ: elementary school.", u: "Collocations: primary reason/goal/concern, primary school, primary source. Học thuật, thay 'main' để đa dạng từ vựng trong IELTS.", f: "primarily (adv), prime (adj), primacy (n)" },
  "purchase": { m: "Pháp pour (để) + chasser (đuổi bắt, như 'chase') → đuổi theo để có được, tức là mua.", e: "Phát âm: /ˈpɜːtʃəs/ (PUR-chəs), không đọc 'pơ-chây'. Sai: purchase for a car → Đúng: purchase a car.", u: "Collocations: make a purchase, purchase order, proof of purchase, online purchases. Trang trọng hơn 'buy'; cực kỳ phổ biến trong TOEIC.", f: "purchase (n), purchaser (n), purchasing (n)" },
  "range": { m: "Pháp ranger (xếp hàng, như 'arrange') → các thứ xếp thành dãy từ thấp đến cao, tạo thành phạm vi.", e: "Sai: a range of product → Đúng: a range of products (danh từ số nhiều). Sai: range from 10 until 20 → Đúng: range from 10 to 20.", u: "Collocations: a wide range of, range from A to B, price range, age range. IELTS Task 1 rất hay dùng để mô tả số liệu.", f: "range (v), ranging (adj), ranger (n)" },
  "region": { m: "Latin regere (cai trị, như 'regime') → vùng đất dưới sự cai quản, tức là khu vực.", e: "Phát âm: /ˈriːdʒən/ (RI-giần), g đọc như j. Sai: in the region about 50 → Đúng: in the region of 50 (khoảng).", u: "Collocations: rural/coastal/remote region, in the region of (khoảng chừng). Trang trọng hơn 'area'; hay dùng trong IELTS Task 1 bản đồ.", f: "regional (adj), regionally (adv)" },
  "regulate": { m: "Latin regula (cái thước, quy tắc, như 'rule') → dùng quy tắc để điều chỉnh.", e: "Nhầm regulate (v) với regulation (n). Sai: strict regulate → Đúng: strict regulations. Nhấn âm 1: REG-u-late.", u: "Collocations: regulate the market/industry, tightly regulated, government regulation. Hay dùng trong IELTS về chính phủ và luật lệ.", f: "regulation (n), regulator (n), regulatory (adj), deregulate (v)" },
  "relevant": { m: "Latin relevare (nâng lên, như 'relieve') → được nâng lên đúng chỗ, có liên quan đến vấn đề.", e: "Sai: relevant with the topic → Đúng: relevant to the topic. Chính tả: relevant, không phải revelant.", u: "Collocations: relevant to, highly relevant, relevant information/experience. IELTS: đưa ví dụ relevant giúp tăng điểm Task Response.", f: "relevance (n), irrelevant (adj), relevantly (adv)" },
  "reside": { m: "re- (lại) + sedere (ngồi, như 'sedentary') → ngồi lại lâu ở một nơi, tức là cư trú.", e: "Sai: reside at Vietnam → Đúng: reside in Vietnam. Nhầm resident (cư dân, n) với residence (nơi ở, n).", u: "Collocations: reside in, permanently reside, reside abroad. Rất trang trọng, dùng trong văn bản pháp lý, hành chính; giao tiếp dùng 'live'.", f: "resident (n), residence (n), residential (adj), residency (n)" },
  "resource": { m: "re- (lại) + surgere (dâng lên, như 'surge') → thứ có thể dâng lên trở lại khi cần, tức là nguồn lực.", e: "Sai: natural resource is limited → Đúng: natural resources are limited (thường dùng số nhiều). Chính tả: resource, không phải resourse.", u: "Collocations: natural/human/financial resources, allocate resources, a waste of resources. Chủ đề môi trường IELTS rất hay gặp.", f: "resourceful (adj), resourcing (n), resource (v)" },
  "restrict": { m: "re- (lại) + stringere (thắt chặt, như 'strict') → thắt chặt lại, hạn chế.", e: "Sai: restrict children play games → Đúng: restrict children from playing games, hoặc restrict sth to sth.", u: "Collocations: restrict access, restrict to, strictly restricted, impose restrictions on. Trang trọng hơn 'limit'; dùng tốt trong IELTS về luật lệ.", f: "restriction (n), restrictive (adj), restricted (adj), unrestricted (adj)" },
  "secure": { m: "se- (không có) + cura (lo lắng, như 'cure') → không còn lo lắng, nên an toàn, ổn định.", e: "Nhầm secure (adj) với security (n). Sai: a job security → Đúng: job security. Nhấn âm 2: se-CURE.", u: "Collocations: feel secure, a secure job/future, secure a deal/funding (v - giành được). Động từ secure rất hay gặp trong TOEIC.", f: "security (n), securely (adv), insecure (adj), insecurity (n)" },
  "seek": { m: "Gốc tiếng Anh cổ secan (tìm). Liên tưởng trò chơi hide-and-seek (trốn tìm).", e: "Sai: seeked → Đúng: sought (quá khứ bất quy tắc: seek – sought – sought). Sai: seek for help → Đúng: seek help.", u: "Collocations: seek advice/help/employment, seek to do sth (cố gắng). Trang trọng hơn 'look for'; dùng nhiều trong TOEIC tuyển dụng.", f: "seeker (n), sought-after (adj)" },
  "select": { m: "se- (tách riêng) + legere (chọn, như 'elect') → tách riêng ra để chọn.", e: "Sai: select among them the best → Đúng: select the best one from them. Nhầm select (v) với selection (n).", u: "Collocations: carefully selected, select from, randomly selected, a select group (nhóm chọn lọc). Trang trọng hơn 'choose'.", f: "selection (n), selective (adj), selectively (adv), selector (n)" },
  "site": { m: "Latin situs (vị trí, như 'situation') → vị trí, địa điểm cụ thể. Website là 'địa điểm' trên mạng.", e: "Nhầm site (địa điểm) với sight (cảnh) và cite (trích dẫn), cả ba đều đọc /saɪt/. Sai: tourist sites see → Đúng: sightseeing.", u: "Collocations: building/construction site, historic site, on site, website. TOEIC: on-site training, site visit.", f: "site (v), website (n), on-site (adj)" },
  "strategy": { m: "Hy Lạp strategos (vị tướng) → nghệ thuật của vị tướng chỉ huy, tức là chiến lược.", e: "Sai: nhấn âm 2 stra-TE-gy → Đúng: nhấn âm 1 STRAT-e-gy. Tính từ strategic lại nhấn âm 2: stra-TE-gic.", u: "Collocations: develop/adopt/implement a strategy, marketing strategy, long-term strategy. Phổ biến trong TOEIC kinh doanh.", f: "strategic (adj), strategically (adv), strategist (n)" },
  "survey": { m: "sur- (trên) + videre (nhìn, như 'video') → nhìn bao quát từ trên cao, tức là khảo sát.", e: "Nhấn âm: danh từ SUR-vey, động từ sur-VEY. Sai: make a survey about → Đúng: conduct/carry out a survey on/of.", u: "Collocations: conduct/carry out a survey, survey results, according to a survey. IELTS Task 1 thường mô tả kết quả khảo sát.", f: "survey (v), surveyor (n)" },
  "text": { m: "Latin textus (vải dệt, như 'textile') → chữ được dệt thành văn bản.", e: "Sai: I'll text to you → Đúng: I'll text you (động từ text không cần to). Nhầm text (văn bản) với context (ngữ cảnh).", u: "Collocations: read the text, text message, the full text, text sb (nhắn tin). Trong IELTS Reading: 'according to the text'.", f: "textual (adj), textbook (n), text (v), texting (n)" },
  "tradition": { m: "trans- (qua) + dare (trao, như 'data') → trao qua từ thế hệ này sang thế hệ khác.", e: "Nhầm tradition (n) với traditional (adj). Sai: tradition food → Đúng: traditional food.", u: "Collocations: keep/break with tradition, a long tradition of, follow a tradition, cultural traditions. Chủ đề văn hóa IELTS rất hay gặp.", f: "traditional (adj), traditionally (adv), traditionalist (n)" },
  "transfer": { m: "trans- (qua) + ferre (mang, như 'ferry') → mang từ chỗ này qua chỗ khác.", e: "Sai: transfered → Đúng: transferred (gấp đôi r). Nhấn âm: động từ trans-FER, danh từ TRANS-fer.", u: "Collocations: transfer money/funds, transfer to another department, bank transfer, technology transfer. Rất phổ biến trong TOEIC.", f: "transfer (n), transferable (adj), transference (n)" },
  "alternative": { m: "alter (khác, như alter ego) + -native → một thứ khác để chọn thay.", e: "Sai: an alternative of coal → Đúng: an alternative to coal (dùng giới từ to).", u: "IELTS: a viable/realistic alternative to, there is no alternative but to + V. Tính từ: alternative energy, alternative sources.", f: "alternative (n, adj), alternatively (adv), alternate (v, adj)" },
  "circumstance": { m: "circum- (vòng quanh, như circle) + stance (đứng) → những gì đứng quanh sự việc = hoàn cảnh.", e: "Sai: on these circumstances → Đúng: in/under these circumstances (không dùng on).", u: "Thường số nhiều: in certain circumstances, under no circumstances (đảo ngữ: Under no circumstances should you...), financial circumstances. Trang trọng.", f: "circumstance (n), circumstantial (adj), circumstantially (adv)" },
  "comment": { m: "com- (cùng) + ment (tâm trí, như mental) → nói ra điều mình nghĩ về việc gì = bình luận.", e: "Sai: comment the article → Đúng: comment on the article (comment đi với on).", u: "comment on/upon sth, decline to comment (văn báo chí), make a comment about. Danh từ: critical comments, a brief comment.", f: "comment (v, n), commentary (n), commentator (n), commentate (v)" },
  "compensate": { m: "com- (cùng) + pens (cân, như pension) → cân lại cho bằng = bù đắp, bồi thường.", e: "Sai: compensate the loss → Đúng: compensate for the loss; compensate someone for something. Nhấn âm 1: COM-pen-sate.", u: "compensate for a shortage/weakness; be compensated for injury. Danh từ compensation hay gặp trong TOEIC: claim/receive compensation.", f: "compensate (v), compensation (n), compensatory (adj)" },
  "component": { m: "com- (cùng) + pon (đặt, như position) → các phần được đặt cùng nhau = thành phần.", e: "Sai: nhấn âm 1 COM-po-nent → Đúng: nhấn âm 2 com-PO-nent. Đừng nhầm với opponent (đối thủ).", u: "a key/essential/major component of; electronic components (TOEIC sản xuất). Trang trọng hơn part.", f: "component (n, adj), compose (v), composition (n)" },
  "consent": { m: "con- (cùng) + sent (cảm nhận, như sense) → cùng cảm nhận một ý = đồng ý.", e: "Sai: consent with the plan → Đúng: consent to the plan. Đừng nhầm với content hay concept.", u: "give/obtain/withhold consent; written consent, parental consent, without (someone's) consent. Trang trọng, dùng trong pháp lý, y tế.", f: "consent (n, v), consensual (adj), consensus (n)" },
  "considerable": { m: "consider (cân nhắc) + -able → lớn đến mức đáng để cân nhắc = đáng kể.", e: "Sai: considerable student (chu đáo) → Đúng: considerate student. Considerable = đáng kể, considerate = chu đáo, ân cần.", u: "a considerable amount/number of, considerable effort/time/attention, to a considerable extent. Trang trọng hơn big, lý tưởng cho Writing.", f: "consider (v), considerable (adj), considerably (adv), consideration (n)" },
  "constant": { m: "con- (hoàn toàn) + stant (đứng, như stand) → đứng yên mãi = không đổi, liên tục.", e: "Sai: The price kept constantly. → Đúng: The price remained constant. Sau remain/stay dùng tính từ, không dùng trạng từ.", u: "constant pressure/noise/temperature, remain constant (mô tả biểu đồ Task 1). Trạng từ constantly = liên tục, hay diễn tả sự khó chịu.", f: "constant (adj, n), constantly (adv), constancy (n)" },
  "constrain": { m: "con- (cùng) + strain (siết, kéo căng) → siết chặt lại = hạn chế, ràng buộc.", e: "Sai: constrain someone doing → Đúng: be constrained to do / constrained by something. Đừng nhầm constrain với restrain (kiềm chế).", u: "be constrained by budget/time/lack of resources; financial constraints, time constraints. Danh từ constraint dùng rất nhiều trong Writing.", f: "constrain (v), constraint (n), constrained (adj)" },
  "contribute": { m: "con- (cùng) + tribute (trao, nộp) → cùng góp phần vào = đóng góp.", e: "Sai: contribute into → Đúng: contribute to (theo sau to là danh từ hoặc V-ing). Nhấn âm 2: con-TRI-bute.", u: "contribute to climate change/success, a major contributing factor, contribute money/ideas. Trung tính, rất phổ biến khi nêu nguyên nhân.", f: "contribute (v), contribution (n), contributor (n), contributory (adj)" },
  "convene": { m: "con- (cùng) + vene (đến, như event, venue) → cùng đến một nơi = triệu tập, nhóm họp.", e: "Sai: convene with the committee → Đúng: convene the committee / the committee convened. Đừng nhầm với convenient.", u: "convene a meeting/conference/panel; rất trang trọng, dùng trong văn bản chính thức, TOEIC. Thông thường dùng hold/call a meeting.", f: "convene (v), convention (n), convener/convenor (n)" },
  "coordinate": { m: "co- (cùng) + ordin (trật tự, như order) → sắp xếp các bên vào cùng một trật tự = phối hợp.", e: "Sai: coordinate together with → Đúng: coordinate with someone / coordinate efforts. Nhấn âm 2: co-OR-di-nate.", u: "coordinate efforts/activities/a response; well-coordinated. TOEIC: event coordinator, project coordination.", f: "coordinate (v, n), coordination (n), coordinator (n), coordinated (adj)" },
  "core": { m: "Core giống lõi quả táo (apple core) → phần trung tâm, cốt lõi.", e: "Sai: the core of problem → Đúng: the core of the problem. Phát âm /kɔː/, đừng nhầm với corps hay course.", u: "core values/subjects/business/issue, at the core of. Tính từ đứng trước danh từ. Lịch sự, phù hợp Writing và TOEIC.", f: "core (adj, n)" },
  "corporate": { m: "corpor (thân thể, như corpse) → một 'cơ thể' tập thể = doanh nghiệp, tập đoàn.", e: "Sai: a big corporate → Đúng: a big corporation. Corporate là tính từ, corporation mới là danh từ.", u: "corporate culture/image/social responsibility/sector. Rất thường gặp trong TOEIC và đề Writing về doanh nghiệp.", f: "corporate (adj), corporation (n), incorporate (v)" },
  "correspond": { m: "cor- (cùng) + respond (đáp lại) → hai bên đáp lại nhau = tương ứng, trao đổi thư từ.", e: "Sai: correspond to my friend (viết thư) → Đúng: correspond with my friend. Correspond to = tương ứng với.", u: "correspond to/with (khớp với), the corresponding period last year (Task 1). TOEIC: business correspondence (thư từ công việc).", f: "correspond (v), correspondence (n), correspondent (n), corresponding (adj), correspondingly (adv)" },
  "criteria": { m: "Gốc Hy Lạp kritēs (người phán xét, như critic) → chuẩn mực để phán xét = tiêu chí.", e: "Sai: this criteria is → Đúng: these criteria are. Criteria là số nhiều; số ít là criterion.", u: "meet/satisfy the criteria, selection/eligibility criteria, based on strict criteria. Trang trọng, thường gặp trong TOEIC tuyển dụng.", f: "criterion (n, số ít), criteria (n, số nhiều)" },
  "deduce": { m: "de- (từ, xuống) + duce (dẫn, như introduce) → dẫn từ dữ kiện xuống kết luận = suy ra.", e: "Sai: deduce that from → Đúng: deduce something from something. Đừng nhầm deduce (suy ra) với deduct (khấu trừ).", u: "deduce from evidence/data, it can be deduced that... Trang trọng, hợp với văn học thuật. Danh từ deduction dùng cho cả suy luận và khấu trừ.", f: "deduce (v), deduction (n), deductive (adj)" },
  "demonstrate": { m: "de- (hoàn toàn) + monstr (chỉ ra, cùng gốc với monitor) → chỉ ra rõ ràng = chứng minh, thể hiện.", e: "Sai: de-MON-strate → Đúng: nhấn âm 1: DEM-on-strate; danh từ nhấn âm 3: dem-on-STRA-tion.", u: "demonstrate that/how, demonstrate the ability/skills; clearly demonstrate. Nghĩa khác: biểu tình (demonstrate against). Trang trọng hơn show.", f: "demonstrate (v), demonstration (n), demonstrator (n), demonstrable (adj), demonstrative (adj)" },
  "document": { m: "doc (dạy, như doctor, doctrine) + -ment → văn bản dùng để cho biết thông tin = tài liệu.", e: "Sai: many documents về kiến thức chung (tài liệu học) → Đúng: study materials. Document thường là giấy tờ, văn bản chính thức.", u: "official/legal documents, sign/submit a document; động từ document = ghi chép lại. TOEIC hay gặp: supporting documents, documentation.", f: "document (n, v), documentation (n), documentary (n, adj)" },
  "dominate": { m: "domin (chủ nhân, như domain) → làm chủ, đứng trên người khác = thống trị, chi phối.", e: "Sai: dominate over the market → Đúng: dominate the market (ngoại động từ, không cần over).", u: "dominate the market/industry/conversation; male-dominated profession; dominant position. Dùng nhiều khi mô tả thứ chiếm ưu thế trong biểu đồ.", f: "dominate (v), domination (n), dominance (n), dominant (adj)" },
  "emphasis": { m: "em- (vào) + phasis (thể hiện, như phase) → làm nổi bật vào trong = sự nhấn mạnh.", e: "Sai: emphasis on (động từ) → Đúng: emphasize the point (động từ không có on); put emphasis on (danh từ dùng on).", u: "place/put/lay emphasis on, a strong/particular emphasis on. Trang trọng; hay dùng mở đoạn trong Writing.", f: "emphasis (n), emphasize/emphasise (v), emphatic (adj), emphatically (adv)" },
  "ensure": { m: "en- (làm cho) + sure (chắc chắn) → làm cho chắc chắn = đảm bảo.", e: "Sai: ensure someone that → Đúng: assure someone that / ensure that something happens. Ensure không đi trực tiếp với người.", u: "ensure that..., ensure safety/quality/compliance. Trang trọng hơn make sure; khác insure (bảo hiểm).", f: "ensure (v), sure (adj), surely (adv)" },
  "exclude": { m: "ex- (ra ngoài) + clude (đóng, như close) → đóng cửa để ở bên ngoài = loại trừ.", e: "Sai: exclude out of → Đúng: exclude someone from something (đi với from).", u: "be excluded from school/the list, excluding tax (TOEIC). Tính từ exclusive = độc quyền, sang trọng.", f: "exclude (v), exclusion (n), exclusive (adj), exclusively (adv), excluding (prep)" },
  "framework": { m: "frame (khung) + work → bộ khung để công việc dựa vào = khuôn khổ.", e: "Sai: in framework of → Đúng: within the framework of (cần mạo từ the, hay dùng within).", u: "a legal/theoretical/regulatory framework, provide a framework for. Học thuật, trang trọng.", f: "framework (n), frame (n, v)" },
  "fund": { m: "Gốc Latin fundus (đáy, nền) → khoản tiền làm nền tảng = quỹ (gần với fundamental).", e: "Sai: a fund for buy books → Đúng: funds to buy books; government funding (funding không đếm được).", u: "raise/allocate funds, a pension/relief fund, lack of funding. Động từ fund: be funded by the government. Thường gặp trong Writing và TOEIC.", f: "fund (n, v), funding (n), fundraising (n), fundraiser (n)" },
  "illustrate": { m: "il- (vào) + lustr (chiếu sáng, như luster) → chiếu sáng vào ý tưởng = minh họa, làm rõ.", e: "Sai: il-LUS-trate → Đúng: nhấn âm 1: IL-lus-trate. Tránh 'illustrate about'; dùng illustrate something.", u: "IELTS Task 1: The chart illustrates... ; to illustrate this point. Danh từ illustration = hình vẽ hoặc ví dụ minh họa.", f: "illustrate (v), illustration (n), illustrator (n), illustrative (adj)" },
  "immigrate": { m: "im- (vào trong) + migrate (di cư) → di cư vào một nước = nhập cư; e- (ra) → emigrate = xuất cư.", e: "Sai: immigrate from Vietnam to Canada khi nhấn rời đi → Đúng: emigrate from Vietnam; immigrate to Canada.", u: "immigrate to/into a country; immigration policy/law; illegal immigrants. Chủ đề quen thuộc trong IELTS Writing.", f: "immigrate (v), immigration (n), immigrant (n), migrate (v), emigrate (v)" },
  "imply": { m: "im- (vào trong) + ply (gấp lại, như apply) → ý gấp gọn bên trong = ngụ ý.", e: "Sai: imply (suy ra) → Đúng: infer. Người nói imply (ngụ ý), người nghe infer (suy ra).", u: "imply that..., as the name implies; danh từ implication = hệ quả, ẩn ý: have serious implications for.", f: "imply (v), implication (n), implicit (adj), implicitly (adv)" },
  "initial": { m: "init (bắt đầu, như initiative) → thuộc giai đoạn khởi đầu = ban đầu.", e: "Sai: in-NI-tial đọc thành 'i-ni-ti-an' → Đúng: /ɪˈnɪʃl/, nhấn âm 2, -tial đọc /ʃl/.", u: "initial stage/phase/response/cost; initially = at first. Danh từ initials = chữ cái đầu tên (ký tắt).", f: "initial (adj, n), initially (adv), initiate (v), initiative (n), initiation (n)" },
  "instance": { m: "in- + stance (đứng) → trường hợp đứng ra làm ví dụ = trường hợp.", e: "Sai: for an instance → Đúng: for instance (không có mạo từ). Đừng nhầm với instant (tức thì).", u: "for instance = for example; in this instance, in the first instance (trang trọng); numerous instances of. Giúp đa dạng từ nối Writing.", f: "instance (n)" },
  "interact": { m: "inter- (giữa, như internet) + act (hành động) → hành động qua lại giữa nhau = tương tác.", e: "Sai: interact each other → Đúng: interact with each other (cần with).", u: "interact with peers/customers, social interaction, interactive learning. Thường dùng trong đề về công nghệ, giáo dục.", f: "interact (v), interaction (n), interactive (adj), interactively (adv)" },
  "justify": { m: "just (đúng, công bằng) + -ify (làm cho) → làm cho có vẻ đúng = biện minh.", e: "Sai: justify for his action → Đúng: justify his action (không cần for).", u: "justify a decision/the cost; be fully justified in doing. Danh từ: there is no justification for. Trang trọng.", f: "justify (v), justification (n), justifiable (adj), justified (adj), unjustified (adj)" },
  "layer": { m: "lay (đặt, đặt xuống) + -er → thứ được đặt chồng lên nhau = lớp, tầng.", e: "Sai: đọc như 'lai-ơ' /ˈlaɪə/ → Đúng: /ˈleɪə(r)/ như 'lây-ơ'. Đừng nhầm với lawyer (luật sư).", u: "the ozone layer, a thin layer of dust, layers of meaning/management. Hay gặp trong đề môi trường.", f: "layer (n, v), layered (adj)" },
  "link": { m: "Link như đường dẫn web: nối hai thứ với nhau = mối liên hệ.", e: "Sai: the link of smoking and cancer → Đúng: the link between smoking and cancer (hai thứ dùng between).", u: "a strong/direct/clear link between; establish a link; be closely linked to. Trung tính, hữu ích khi nêu quan hệ nhân quả.", f: "link (n, v), linked (adj), linkage (n)" },
  "locate": { m: "loc (nơi chốn, như local, location) → tìm hoặc đặt vào một nơi = xác định vị trí.", e: "Sai: The hotel locates near the beach. → Đúng: The hotel is located near the beach (dùng bị động).", u: "be located in/at/near; locate the source/problem. TOEIC: conveniently located, relocate the office. Trang trọng hơn find.", f: "locate (v), location (n), local (adj), relocate (v)" },
  "maximise": { m: "maxim (lớn nhất, như maximum) + -ise (làm cho) → làm cho lớn nhất = tối đa hóa.", e: "Chính tả: maximise (Anh) / maximize (Mỹ); giữ thống nhất một kiểu trong cả bài viết.", u: "maximise profits/efficiency/potential/the use of. Trái nghĩa minimise. Phổ biến trong TOEIC kinh doanh.", f: "maximise/maximize (v), maximum (n, adj), maximal (adj), maximisation (n)" },
  "minor": { m: "Latin minor (nhỏ hơn), như minus, minimum → nhỏ, không quan trọng.", e: "Sai: a minor of people (một số ít) → Đúng: a minority of people. Minor (n) = trẻ vị thành niên.", u: "minor changes/problems/injuries, play a minor role. Trái nghĩa major. Dùng khi giảm nhẹ mức độ trong Writing.", f: "minor (adj, n), minority (n)" },
  "negate": { m: "neg (không, như negative) + -ate → nói 'không' với điều gì = phủ nhận, vô hiệu hóa.", e: "Sai: He negated going there (chối) → Đúng: He denied going there. Negate = làm mất tác dụng: negate the benefits.", u: "negate the effect/benefits/advantages of. Rất trang trọng, chủ yếu văn học thuật.", f: "negate (v), negation (n), negative (adj), negatively (adv)" },
  "outcome": { m: "out (ra) + come (đến) → điều cuối cùng xuất hiện = kết quả.", e: "Sai: the outcome for the match → Đúng: the outcome of the match. Đừng nhầm outcome với income (thu nhập).", u: "a positive/successful/likely outcome; the outcome of the election/negotiations. Trang trọng hơn result.", f: "outcome (n)" },
  "partner": { m: "part (phần) + -ner → người cùng chia phần = đối tác, bạn đồng hành.", e: "Sai: cooperate partner → Đúng: business partner. Động từ: partner with a company, không dùng 'partner together with'.", u: "business/trading partner; enter into a partnership; partner with a company (TOEIC). Cũng chỉ vợ, chồng, người yêu.", f: "partner (n, v), partnership (n)" },
  "philosophy": { m: "philo- (yêu, như philanthropy) + sophy (trí tuệ) → tình yêu trí tuệ = triết học.", e: "Sai: phi-lo-SO-phy → Đúng: nhấn âm 2: phi-LOS-o-phy.", u: "a philosophy of life, the company's business philosophy, study philosophy. Dùng để nói quan điểm sống, nguyên tắc làm việc.", f: "philosophy (n), philosopher (n), philosophical (adj), philosophically (adv)" },
  "physical": { m: "physi (tự nhiên, như physics) → thuộc về vật chất, thân thể = thể chất, vật lý.", e: "Sai: do physical (tập thể dục) → Đúng: do physical exercise / do physical activity. Physical là tính từ.", u: "physical activity/health/appearance, physical and mental health. Rất hay dùng trong chủ đề sức khỏe.", f: "physical (adj), physically (adv), physics (n), physicist (n), physician (n)" },
  "proportion": { m: "pro- (theo) + portion (phần) → phần theo tỉ lệ của toàn thể = tỉ lệ.", e: "Sai: a large proportion of people is → Đúng: a large proportion of people are (động từ theo danh từ sau of).", u: "Task 1: a small/significant proportion of, in proportion to, out of proportion. Trang trọng hơn part.", f: "proportion (n), proportional (adj), proportionate (adj), disproportionate (adj)" },
  "publish": { m: "publ (công chúng, như public) + -ish → đưa ra công chúng = xuất bản.", e: "Sai: The book was publish in 2020. → Đúng: The book was published in 2020 (bị động cần V3).", u: "publish a book/report/findings/results; be published in a journal. Danh từ publication; publisher là nhà xuất bản.", f: "publish (v), publication (n), publisher (n), publishing (n)" },
  "react": { m: "re- (lại) + act (hành động) → hành động đáp lại = phản ứng.", e: "Sai: react with the news → Đúng: react to the news. React with chỉ dùng cho phản ứng hóa học.", u: "react to criticism/changes; react quickly/badly; react against (phản đối). Danh từ reaction: a mixed/positive reaction.", f: "react (v), reaction (n), reactive (adj), reactor (n)" },
  "register": { m: "re- (lại) + gest (mang, ghi) → ghi lại vào sổ = đăng ký.", e: "Sai: register the course → Đúng: register for the course (đăng ký tham gia dùng for).", u: "register for a course/event, register a company/vehicle (TOEIC), registered mail. Danh từ register = văn phong (formal register).", f: "register (v, n), registration (n), registered (adj), registrar (n)" },
  "rely": { m: "re- (lại) + ly (buộc, như ligament) → buộc chặt vào người khác = dựa vào.", e: "Sai: rely in/to someone → Đúng: rely on someone / rely on someone to do something.", u: "rely heavily on, rely on public transport/imports. Tính từ reliable = đáng tin cậy, reliance (n) = sự phụ thuộc.", f: "rely (v), reliance (n), reliable (adj), reliability (n), reliant (adj)" },
  "remove": { m: "re- (đi, ra) + move (di chuyển) → di chuyển đi chỗ khác = loại bỏ.", e: "Sai: remove out of the list → Đúng: remove something from the list (dùng from).", u: "remove barriers/obstacles/restrictions; be removed from office. Trang trọng hơn take away.", f: "remove (v), removal (n), removable (adj)" },
  "scheme": { m: "Cùng gốc Hy Lạp với schema, schematic (sơ đồ) → một kế hoạch được vạch ra có hệ thống.", e: "Sai: phát âm 'sơ-kim' với âm ch → Đúng: /skiːm/, ch đọc như k. Lưu ý ở Mỹ scheme hay mang nghĩa mưu đồ.", u: "Anh-Anh: a government scheme, pension scheme, scheme to reduce traffic. Mỹ dùng program hơn; tránh nghĩa tiêu cực khi viết.", f: "scheme (n, v), schematic (adj), schemer (n)" },
  "sequence": { m: "sequ (theo sau, như sequel, consequence) → cái này theo sau cái kia = trình tự, chuỗi.", e: "Sai: in sequence order (lặp nghĩa) → Đúng: in sequence / in chronological sequence.", u: "a sequence of events/steps, in the correct sequence. Dùng tốt khi mô tả quy trình (process) trong Task 1.", f: "sequence (n, v), sequential (adj), sequentially (adv), consequence (n)" },
  "sex": { m: "Gốc Latin sexus (phân chia) → sự chia thành nam và nữ = giới tính.", e: "Sai: dùng sex trong 'sex equality' khi bàn vai trò xã hội → Đúng: gender equality. Sex nghiêng về sinh học, gender về xã hội.", u: "the opposite sex, sex discrimination, single-sex schools (đề giáo dục). Tính từ sexual chủ yếu dùng trong ngữ cảnh khác.", f: "sex (n), sexual (adj), sexually (adv), sexism (n), sexist (adj)" },
  "shift": { m: "Như ca làm việc (night shift): chuyển từ ca này sang ca khác = sự chuyển dịch.", e: "Sai: a shift of public opinion → Đúng: a shift in public opinion (dùng in cho sự thay đổi).", u: "a major/dramatic shift in attitudes/policy, a shift from A to B, work night shifts (TOEIC). Trang trọng hơn change.", f: "shift (n, v), shifting (adj)" },
  "specify": { m: "speci (loại, như special, species) + -fy → nói rõ loại nào = nêu rõ, chỉ định.", e: "Sai: specify about the details → Đúng: specify the details (không cần about).", u: "unless otherwise specified, specify the requirements/date. Tính từ specific; danh từ specifications (thông số kỹ thuật, TOEIC).", f: "specify (v), specific (adj), specifically (adv), specification (n)" },
  "sufficient": { m: "suf- (dưới) + fic (làm, như factory) → làm đủ để chống đỡ = đủ.", e: "Sai: sufficient for do → Đúng: sufficient to do / sufficient for something. Phát âm: su-FI-cient, nhấn âm 2.", u: "sufficient evidence/funds/time; self-sufficient. Trang trọng hơn enough, thích hợp Writing.", f: "sufficient (adj), sufficiently (adv), sufficiency (n), insufficient (adj)" },
  "task": { m: "Gốc tax (thuế) → phần việc được giao phải nộp = nhiệm vụ.", e: "Sai: do a task about writing → Đúng: complete/carry out a writing task.", u: "perform/carry out/complete a task; a challenging/daunting task; task force. IELTS chia thành Task 1 và Task 2.", f: "task (n, v)" },
  "technical": { m: "techn (kỹ năng, nghề, như technology) + -ical → thuộc về chuyên môn, kỹ thuật.", e: "Sai: technical (danh từ) → Đúng: technique (kỹ thuật, phương pháp) là danh từ; technical là tính từ.", u: "technical skills/support/problems/terms. TOEIC: technical support team, technical difficulties.", f: "technical (adj), technically (adv), technician (n), technicality (n)" },
  "technique": { m: "Gốc Hy Lạp tekhnē (nghề, kỹ năng) → cách làm có kỹ năng = kỹ thuật, phương pháp.", e: "Sai: TECH-nique → Đúng: nhấn âm 2: tech-NIQUE /tekˈniːk/. Không nhầm với technology.", u: "develop/use/apply a technique; teaching/marketing techniques. Đếm được, thường dùng số nhiều.", f: "technique (n), technical (adj), technician (n)" },
  "technology": { m: "techno (kỹ năng) + -logy (môn học, như biology) → môn học về kỹ năng = công nghệ.", e: "Sai: the technologies is developing → Đúng: technology is developing (nói chung dùng không đếm được, không cần the).", u: "advances in technology, modern/information technology, technological development. Chủ đề rất phổ biến trong IELTS Writing Task 2.", f: "technology (n), technological (adj), technologically (adv), technologist (n)" },
  "valid": { m: "val (mạnh, giá trị, như value) → có giá trị, có hiệu lực = hợp lệ, có cơ sở.", e: "Sai: The ticket is valid to use until May. → Đúng: The ticket is valid until May. Đừng nhầm valid (hợp lệ) với available (có sẵn).", u: "a valid point/argument/reason, valid passport/ticket (TOEIC), remain valid. Trái nghĩa invalid.", f: "valid (adj), validity (n), validate (v), validation (n), invalid (adj)" },
  "volume": { m: "Gốc Latin volumen (cuộn giấy) → một cuộn sách dày = khối lượng, thể tích, tập sách.", e: "Sai: a big volume of people → Đúng: a large number of people; volume dùng cho lượng, khối (traffic volume).", u: "the volume of traffic/sales/trade, turn up the volume, high-volume. Hay gặp khi mô tả biểu đồ.", f: "volume (n), voluminous (adj)" },
  "access": { m: "ac- (đến) + cess (đi, như trong process) → đi đến được nơi nào đó, tức là tiếp cận.", e: "Sai: have access into the internet → Đúng: have access to the internet (access đi với to).", u: "Dùng nhiều trong IELTS: access to education/healthcare, gain/provide access, limited access. Động từ access a website thường không cần giới từ.", f: "access (n, v), accessible (adj), accessibility (n), inaccessible (adj)" },
  "adequate": { m: "ad- (đến) + equ (bằng, như equal) → đạt đến mức ngang bằng nhu cầu, tức là đủ.", e: "Sai nhấn âm: a-de-QUATE → Đúng: AD-e-quate /ˈædɪkwət/, đuôi -quate đọc nhẹ /kwət/.", u: "Trang trọng hơn enough: adequate funding/housing/supply, adequate for sth. Hay dùng khi viết Task 2 về chính sách, dịch vụ công.", f: "adequate (adj), adequately (adv), adequacy (n), inadequate (adj), inadequacy (n)" },
  "annual": { m: "ann (năm, như anniversary) + -ual (tính từ) → thuộc về mỗi năm.", e: "Sai: the annually report → Đúng: the annual report (trước danh từ dùng tính từ annual; annually là trạng từ).", u: "Gặp nhiều trong biểu đồ IELTS và TOEIC: annual income/revenue/growth rate, annual meeting, on an annual basis.", f: "annual (adj), annually (adv), annual (n: ấn phẩm hằng năm)" },
  "apparent": { m: "Liên hệ appear (xuất hiện) → điều đã hiện ra trước mắt nên rõ ràng, hoặc chỉ là vẻ bề ngoài.", e: "Sai: apparently = rõ ràng chắc chắn → Đúng: apparently thường nghĩa 'nghe nói, có vẻ như', không khẳng định chắc chắn.", u: "It is apparent that... (trang trọng, rõ ràng là); for no apparent reason; apparent success (thành công bề ngoài). Phân biệt hai nghĩa theo ngữ cảnh.", f: "apparent (adj), apparently (adv), appear (v), appearance (n)" },
  "approximate": { m: "ap- (đến) + proxim (gần, như proximity) → tiến đến gần con số thật, tức là xấp xỉ.", e: "Sai: approximate 50 people → Đúng: approximately 50 people (đứng trước số dùng trạng từ approximately).", u: "Rất hữu ích khi mô tả số liệu IELTS Task 1: approximately 30%, an approximate figure/cost. Trang trọng hơn about, around.", f: "approximate (adj, v), approximately (adv), approximation (n)" },
  "attitude": { m: "Gần với aptitude nhưng attitude là thái độ, cách nhìn; nhớ 'att' như attention: chú ý đến cách mình nghĩ.", e: "Sai: attitude with work → Đúng: attitude to/towards work (attitude đi với to hoặc towards).", u: "Collocation: a positive/negative attitude towards sth, change attitudes, public attitudes. Hữu ích trong Task 2 về xã hội, giáo dục.", f: "attitude (n), attitudinal (adj)" },
  "attribute": { m: "at- (đến) + tribute (trao, như contribute) → trao nguyên nhân cho ai/cái gì, tức là quy cho.", e: "Nhấn âm: động từ at-TRIB-ute, danh từ AT-tri-bute. Sai: attribute it for luck → Đúng: attribute it to luck.", u: "Cấu trúc học thuật: attribute A to B, be attributed to (được cho là do). Danh từ attribute nghĩa là phẩm chất, đặc điểm.", f: "attribute (v, n), attribution (n), attributable (adj)" },
  "civil": { m: "civ (công dân, như city, citizen) → thuộc về người dân, dân sự, khác với quân sự.", e: "Nhầm civil với civic: civil war, civil rights → Đúng; civic duty, civic pride (nghĩa vụ, niềm tự hào công dân) dùng civic.", u: "Collocation: civil rights, civil war, civil servant (công chức), civil society, civil engineering. Ngoài ra civil còn nghĩa là lịch sự.", f: "civil (adj), civilian (n, adj), civility (n), civilization (n), civilize (v)" },
  "code": { m: "Như mã code trong lập trình: một hệ thống quy tắc hay ký hiệu được sắp xếp có trật tự.", e: "Sai: dress rule → Đúng: dress code (quy định trang phục). Code of conduct là bộ quy tắc ứng xử, không nói rule of conduct.", u: "TOEIC hay gặp: dress code, code of conduct, discount/promo code, postal code. Trong học thuật: legal code, genetic code.", f: "code (n, v), coding (n), encode (v), decode (v), codify (v)" },
  "commit": { m: "com- (cùng, hết) + mit (gửi, như transmit) → gửi trọn bản thân vào việc gì, tức là cam kết.", e: "Sai: commit to do it → Đúng: commit to doing it (to là giới từ, theo sau là V-ing). Chú ý commitment chỉ có một t ở giữa.", u: "be committed to + V-ing/noun; commit a crime/an error (phạm tội, mắc lỗi); a firm commitment. Dùng trang trọng trong thư tín TOEIC.", f: "commit (v), commitment (n), committed (adj), committee (n)" },
  "communicate": { m: "commun (chung, như common, community) + -ate → làm cho thông tin trở thành của chung, tức là truyền đạt.", e: "Sai: communicate each other → Đúng: communicate with each other (cần giới từ with).", u: "communicate with sb, communicate ideas/information effectively, communication skills. Phổ biến trong Speaking về công nghệ, công việc.", f: "communicate (v), communication (n), communicative (adj), communicator (n)" },
  "concentrate": { m: "con- (cùng) + centr (trung tâm, như center) → dồn mọi thứ về một trung tâm, tức là tập trung.", e: "Sai: concentrate in my study → Đúng: concentrate on my study (concentrate đi với on).", u: "concentrate on sth, find it hard to concentrate, be concentrated in (tập trung ở một khu vực). Danh từ concentration dùng cho cả nồng độ.", f: "concentrate (v, n), concentration (n), concentrated (adj)" },
  "confer": { m: "con- (cùng) + fer (mang, như transfer) → mang đến cùng nhau để bàn, hoặc mang danh hiệu trao cho ai.", e: "Nhầm confer với conference khi dùng từ loại: Sai: they conference about it → Đúng: they conferred about it. Nhấn âm 2: con-FER.", u: "Trang trọng: confer a degree/title on sb (trao), confer with colleagues (hội ý). Hiếm dùng trong văn nói hằng ngày.", f: "confer (v), conference (n), conferral (n)" },
  "contrast": { m: "contra- (ngược lại) + st (đứng) → đứng đối diện nhau, làm nổi bật sự khác biệt.", e: "Nhấn âm: danh từ CON-trast, động từ con-TRAST. Sai: in contrast of → Đúng: in contrast to/with.", u: "Rất hữu ích để so sánh trong IELTS: In contrast, ...; by contrast; a sharp/stark contrast between A and B; contrast A with B.", f: "contrast (n, v), contrasting (adj), contrastive (adj)" },
  "cycle": { m: "Gốc Hy Lạp kyklos (vòng tròn), như bicycle (hai vòng bánh) → chu kỳ lặp lại thành vòng.", e: "Phát âm sai: /si-kồ/ → Đúng: /ˈsaɪkl/ (cy đọc 'sai'). Recycle cũng đọc /riːˈsaɪkl/.", u: "IELTS Task 1 dạng quy trình: the life cycle of..., a natural cycle, the cycle repeats. Ngoài ra: business cycle, vicious cycle.", f: "cycle (n, v), cyclical (adj), cyclic (adj), recycle (v), cyclist (n)" },
  "debate": { m: "de- (xuống, hoàn toàn) + bate (đánh, như battle) → đánh qua đánh lại bằng lý lẽ.", e: "Sai: debate about the issue (động từ) → Đúng: debate the issue. Danh từ thì nói a debate about/on/over the issue.", u: "Mở bài IELTS: There has been much debate over whether...; a heated/ongoing debate; the topic is widely debated.", f: "debate (n, v), debatable (adj), debater (n)" },
  "despite": { m: "de- + spite (sự bất chấp) → bất chấp điều đó vẫn xảy ra, nghĩa là mặc dù.", e: "Sai: despite of the rain → Đúng: despite the rain hoặc in spite of the rain. Sau despite không dùng mệnh đề đầy đủ.", u: "despite + danh từ/V-ing/the fact that + mệnh đề. Dùng nhiều trong Writing để nối ý tương phản, trang trọng hơn although.", f: "despite (prep); cùng nghĩa: in spite of (prep)" },
  "dimension": { m: "di- / dis- + mens (đo, như measure) → kích thước đo được; mở rộng thành khía cạnh của vấn đề.", e: "Sai nhấn âm: DI-men-sion → Đúng: di-MEN-sion (nhấn âm 2).", u: "a new dimension to the problem, the social/economic dimension, three-dimensional (3D). Trang trọng hơn aspect, hợp với Writing.", f: "dimension (n), dimensional (adj), multidimensional (adj)" },
  "domestic": { m: "domus (nhà, như dome) → thuộc về nhà, gia đình; mở rộng thành trong nước, không phải nước ngoài.", e: "Sai: domestic tourists đi nước ngoài → domestic là nội địa. Sai: home violence → Đúng: domestic violence (bạo lực gia đình).", u: "domestic flights/market/demand (nội địa), domestic violence/chores, domestic animals. Đối lập: international, foreign.", f: "domestic (adj), domestically (adv), domesticate (v), domestication (n)" },
  "emerge": { m: "e- (ra ngoài) + merge (chìm, nhúng) → từ dưới nước trồi lên, tức là nổi lên, xuất hiện.", e: "Sai: a new trend was emerged → Đúng: a new trend emerged (nội động từ, không dùng bị động).", u: "Học thuật: emerge from, it emerged that..., emerging markets/economies, a pattern emerges. Hữu ích khi mô tả xu hướng mới.", f: "emerge (v), emergence (n), emerging (adj), emergent (adj), emergency (n)" },
  "error": { m: "err (đi lạc, sai, như errant) → đi lệch đường đúng, tức là sai sót.", e: "Sai: make an error about calculation → Đúng: make an error in the calculation (error đi với in).", u: "Trang trọng hơn mistake: a human error, a spelling error, in error (do nhầm lẫn), margin of error. Dùng tốt trong TOEIC thư tín.", f: "error (n), err (v), erroneous (adj), erroneously (adv)" },
  "ethnic": { m: "Gốc Hy Lạp ethnos (dân tộc, tộc người) → thuộc về một nhóm dân tộc có văn hóa riêng.", e: "Phát âm: /ˈeθnɪk/ với âm th /θ/, không đọc thành 'et-nic'. Sai: ethnic people (mơ hồ) → Đúng: ethnic minority groups.", u: "Collocation: ethnic minority, ethnic group, ethnic diversity, ethnic background. Cần dùng tế nhị, trung lập khi bàn về văn hóa.", f: "ethnic (adj), ethnicity (n), ethnically (adv)" },
  "goal": { m: "Như bàn thắng (goal) trong bóng đá: điểm đích cuối cùng mà mình nhắm tới.", e: "Sai: reach my goal of become a doctor → Đúng: achieve my goal of becoming a doctor (sau of dùng V-ing).", u: "achieve/reach/set a goal, a long-term goal, the main goal is to... Thường dùng trong Speaking Part 2 về dự định tương lai.", f: "goal (n), goalkeeper (n); gần nghĩa: aim, objective, target" },
  "grant": { m: "Liên hệ granted (được chấp thuận): grant là thứ được chính thức cấp cho ai, như khoản trợ cấp.", e: "Sai: take it for grant → Đúng: take it for granted (coi là điều hiển nhiên, dùng granted).", u: "a research/government grant, apply for/receive/award a grant. Động từ: grant permission/access/a visa. Hay gặp trong TOEIC và học thuật.", f: "grant (n, v), granted (adj, conj), grantee (n), grantor (n)" },
  "hence": { m: "Nhớ gần với 'từ đây' (from here) → từ điều vừa nói suy ra, do đó.", e: "Sai: hence, so prices rose → Đúng: hence, prices rose (không dùng hence và so cùng lúc). Sai viết: hense → Đúng: hence.", u: "Rất trang trọng, hợp với Writing học thuật: ..., hence the need for... (có thể theo sau bằng cụm danh từ). Văn nói dùng so.", f: "hence (adv); gần nghĩa: therefore, thus, consequently" },
  "hypothesis": { m: "hypo- (dưới) + thesis (luận điểm) → luận điểm đặt nền bên dưới, chưa chứng minh: giả thuyết.", e: "Số nhiều: Sai hypothesises → Đúng: hypotheses /haɪˈpɒθəsiːz/. Nhấn âm 2: hy-PO-the-sis.", u: "test/support/reject a hypothesis, put forward a hypothesis. Dùng trong bài đọc IELTS khoa học; tính từ hypothetical (giả định).", f: "hypothesis (n), hypotheses (n, plural), hypothesize (v), hypothetical (adj), hypothetically (adv)" },
  "implement": { m: "im- (vào) + ple (làm đầy, như complete) → đưa kế hoạch vào làm cho trọn, tức là triển khai.", e: "Sai: implement into practice → Đúng: put into practice hoặc implement a plan (implement không cần into).", u: "implement a policy/plan/strategy/system, fully implemented. Từ khóa mạnh trong Task 2 khi đề xuất giải pháp chính phủ.", f: "implement (v, n: công cụ), implementation (n)" },
  "implicate": { m: "im- (vào) + plic (gấp, xoắn, như complicate) → bị xoắn vào sự việc, tức là bị liên can.", e: "Nhầm implicate với imply: Sai: he implicated that he was tired → Đúng: he implied that he was tired.", u: "Thường bị động: be implicated in a crime/scandal (bị liên can). Học thuật: be implicated in disease (có liên quan đến bệnh).", f: "implicate (v), implication (n), implicit (adj), imply (v)" },
  "impose": { m: "im- (lên trên) + pose (đặt, như position) → đặt lên trên người khác, tức là áp đặt.", e: "Sai: impose a tax to imports → Đúng: impose a tax on imports (impose đi với on).", u: "impose a ban/tax/restriction/fine on sth. Rất hay dùng trong Task 2 khi bàn về luật, thuế. Danh từ imposition trang trọng.", f: "impose (v), imposition (n), imposing (adj: oai vệ)" },
  "integrate": { m: "integer (số nguyên, trọn vẹn) → làm thành một khối trọn vẹn, tức là tích hợp, hội nhập.", e: "Sai: integrate to the community → Đúng: integrate into the community; integrate A with B. Nhấn âm 1: IN-te-grate.", u: "integrate into society, integrate technology into the classroom, an integrated system. Hay gặp trong chủ đề nhập cư, giáo dục.", f: "integrate (v), integration (n), integrated (adj), integral (adj), integrity (n)" },
  "internal": { m: "inter/intern (bên trong, như interior) + -al → thuộc phía bên trong, nội bộ.", e: "Nhầm internal với international: Sai: internal flights (bay quốc tế) → Đúng: international flights; internal = nội bộ, domestic = nội địa.", u: "internal affairs, internal memo/communication (TOEIC), internal organs. Đối lập: external.", f: "internal (adj), internally (adv), internalize (v)" },
  "investigate": { m: "in- (vào) + vestig (dấu vết, như vestige) → lần theo dấu vết vào bên trong, tức là điều tra.", e: "Sai: investigate about the cause → Đúng: investigate the cause (investigate không cần about).", u: "investigate the effects of..., police investigate a crime, a thorough investigation into sth. Dùng trong bài đọc khoa học.", f: "investigate (v), investigation (n), investigator (n), investigative (adj)" },
  "job": { m: "Từ quen thuộc: việc làm cụ thể có trả lương, như job interview (phỏng vấn xin việc).", e: "Sai: I have many works → Đúng: I have a lot of work / many jobs (job đếm được, work không đếm được).", u: "apply for a job, a full-time/part-time job, job satisfaction/security, do a good job. Trung tính, dùng được cả nói và viết.", f: "job (n), jobless (adj), joblessness (n)" },
  "label": { m: "Liên hệ nhãn hàng, nhãn mác: mảnh giấy dán lên để ghi tên, thông tin.", e: "Phát âm: /ˈleɪbl/ ('lây-bồ'), không đọc 'la-ben'. Sai: label him a liar as → Đúng: label him as a liar.", u: "food labels, a warning label, label sb as... (gán mác ai đó, sắc thái tiêu cực). Chính tả: labelled (UK) / labeled (US).", f: "label (n, v), labelled/labeled (adj), labelling/labeling (n)" },
  "mechanism": { m: "mechan (máy móc, như machine, mechanic) + -ism → cách các bộ phận vận hành như một cỗ máy: cơ chế.", e: "Sai nhấn âm: me-CHA-nism → Đúng: MECH-a-nism /ˈmekənɪzəm/ (ch đọc /k/).", u: "a mechanism for doing sth, defence mechanism, market mechanism. Hợp với Writing khi giải thích cách một hệ thống hoạt động.", f: "mechanism (n), mechanical (adj), mechanic (n), mechanics (n), mechanize (v)" },
  "obvious": { m: "ob- (trên đường, phía trước) + via (đường, như via) → nằm ngay giữa đường, ai cũng thấy: hiển nhiên.", e: "Sai: it is obviously that... → Đúng: it is obvious that... (sau is cần tính từ, không dùng trạng từ).", u: "an obvious reason/choice/solution, it is obvious that... Trong Writing nên dùng thận trọng vì có thể nghe áp đặt; thay bằng clear.", f: "obvious (adj), obviously (adv), obviousness (n)" },
  "occupy": { m: "oc- (hoàn toàn) + cup (nắm, giữ, như capture) → nắm giữ hoàn toàn một chỗ, tức là chiếm giữ.", e: "Chính tả: Sai ocupy, occuppied → Đúng: occupy, occupied (hai c, một p). Sai: occupy in work → Đúng: be occupied with work.", u: "occupy a position/space/time, be occupied with sth, the seat is occupied. Danh từ occupation còn nghĩa nghề nghiệp (trong mẫu đơn).", f: "occupy (v), occupation (n), occupant (n), occupied (adj), occupational (adj)" },
  "option": { m: "opt (chọn, như adopt) + -ion → điều được chọn, lựa chọn.", e: "Sai: I have no option to accept → Đúng: I have no option but to accept (cấu trúc no option but to).", u: "a viable/cheap option, keep your options open, the best option is to... Tính từ optional (không bắt buộc) hay gặp trong TOEIC.", f: "option (n), opt (v), optional (adj), optionally (adv)" },
  "output": { m: "out (ra ngoài) + put (đặt) → những gì được đưa ra sau sản xuất: sản lượng, đầu ra.", e: "Sai: outputs of the factory increased much → Đúng: the factory's output increased significantly (output thường không đếm được).", u: "IELTS Task 1: industrial/agricultural output, output rose/fell, increase output. Đối lập: input. Trung tính, dùng được trong kinh tế.", f: "output (n, v); đối lập: input (n)" },
  "overall": { m: "over (bao trùm) + all (tất cả) → nhìn bao quát toàn bộ, tổng thể.", e: "Sai: Overally, the figure rose → Đúng: Overall, the figure rose (overall đã là trạng từ, không có dạng overally).", u: "Từ khóa IELTS Task 1: Overall, it is clear that...; the overall trend, overall cost/performance. Dùng làm tính từ và trạng từ.", f: "overall (adj, adv), overalls (n: quần yếm)" },
  "parallel": { m: "para- (bên cạnh) + allel (nhau, như other) → nằm bên cạnh nhau, song song.", e: "Chính tả: Sai paralell, parralel → Đúng: parallel (một r, hai l ở giữa, một l cuối). Nhấn âm 1: PAR-a-llel.", u: "parallel to/with sth, run parallel, draw a parallel between A and B (so sánh tương đồng). Dùng tốt trong Writing so sánh.", f: "parallel (adj, n, v), unparalleled (adj: vô song)" },
  "parameter": { m: "para- (bên cạnh) + meter (đo) → thước đo đặt bên cạnh để giới hạn: tham số, giới hạn.", e: "Nhấn âm 2: pa-RA-me-ter. Sai: perimeter (chu vi) dùng thay parameter → Đúng: within the parameters of the budget.", u: "Thường dùng số nhiều: within the parameters of, set parameters, key parameters. Sắc thái học thuật, kỹ thuật.", f: "parameter (n), parametric (adj)" },
  "phase": { m: "Gốc Hy Lạp phasis (sự xuất hiện), như các pha của mặt trăng → từng giai đoạn thay đổi.", e: "Phát âm: /feɪz/, không đọc ‘pha-se’. Nhầm phase với face hoặc phrase: Sai: the final phrase of the project → Đúng: the final phase.", u: "the first/final phase, in phases, phase in/out (đưa vào/loại bỏ dần). Dùng trong Task 1 quy trình và chủ đề dự án.", f: "phase (n, v), phased (adj)" },
  "predict": { m: "pre- (trước) + dict (nói, như dictionary) → nói trước điều sẽ xảy ra, tức là dự đoán.", e: "Sai: predict about the future → Đúng: predict the future (predict không cần about).", u: "IELTS Task 1 với số liệu tương lai: it is predicted that..., is predicted to rise; a reliable prediction, predictable results.", f: "predict (v), prediction (n), predictable (adj), unpredictable (adj), predictor (n)" },
  "principal": { m: "princ (đầu, thứ nhất, như prince, prime) → đứng đầu, chính yếu nhất.", e: "Nhầm principal (chính; hiệu trưởng) với principle (nguyên tắc): Sai: the main principal of science → Đúng: principle.", u: "the principal reason/cause/source, principal investor. Danh từ principal: hiệu trưởng (US). Trang trọng hơn main.", f: "principal (adj, n), principally (adv)" },
  "prior": { m: "Gần priority (ưu tiên) → cái gì đến trước thì được ưu tiên; prior nghĩa là trước.", e: "Sai: prior the meeting → Đúng: prior to the meeting (luôn có to). Không dùng prior than.", u: "Trang trọng, rất hay gặp trong TOEIC: prior to arrival, prior experience/notice, without prior approval. Văn nói dùng before.", f: "prior (adj), priority (n), prioritize (v)" },
  "professional": { m: "profess (tuyên bố công khai, như profession) → người công khai hành nghề, làm việc chuyên nghiệp.", e: "Chính tả: Sai proffessional → Đúng: professional (một f, hai s). Nhấn âm 2: pro-FES-sion-al.", u: "professional advice/help, a professional athlete, highly professional, professional development. Danh từ: a healthcare professional.", f: "professional (adj, n), profession (n), professionally (adv), professionalism (n)" },
  "project": { m: "pro- (về phía trước) + ject (ném, như reject, inject) → ném kế hoạch về phía trước: dự án; dự kiến.", e: "Nhấn âm: danh từ PRO-ject, động từ pro-JECT (dự kiến, chiếu). Sai: do a projection about → Đúng: carry out a project on.", u: "carry out/undertake/launch a project, a research project. Động từ: be projected to increase (Task 1 dự báo số liệu).", f: "project (n, v), projection (n), projector (n), projected (adj)" },
  "promote": { m: "pro- (về phía trước) + mote (di chuyển, như motion) → đẩy về phía trước: thúc đẩy, thăng chức.", e: "Sai: promote him to be manager → Đúng: promote him to manager / to the position of manager.", u: "promote health/tourism/equality, promote a product (quảng bá), be promoted to (thăng chức). Phổ biến trong Task 2 và TOEIC.", f: "promote (v), promotion (n), promotional (adj), promoter (n)" },
  "regime": { m: "reg (cai trị, như regulate, region) → hệ thống cai trị hay chế độ được quy định.", e: "Phát âm: /reɪˈʒiːm/ ('rây-giim'), nhấn âm 2. Đừng nhầm với regimen (chế độ ăn uống, điều trị).", u: "a military/political regime (sắc thái tiêu cực), a tax regime, a strict training regime. Dùng trong bài đọc chính trị, lịch sử.", f: "regime (n); liên quan: regimen (n), regiment (n)" },
  "resolve": { m: "re- (lại) + solve (giải, tháo) → tháo gỡ lại cho xong, tức là giải quyết dứt điểm.", e: "Sai: resolve the problem about → Đúng: resolve the problem / resolve a dispute (không cần about). Danh từ resolution, không phải resolvation.", u: "resolve a conflict/dispute/issue, resolve to do sth (quyết tâm). Trang trọng hơn solve, hay dùng trong TOEIC khiếu nại khách hàng.", f: "resolve (v, n), resolution (n), resolved (adj), unresolved (adj)" },
  "retain": { m: "re- (lại) + tain (giữ, như maintain, contain) → giữ lại, không để mất.", e: "Sai: retain from smoking (nhầm refrain) → Đúng: refrain from smoking; retain information/staff.", u: "retain staff/customers (TOEIC), retain information/heat, retain the right to... Danh từ retention: customer retention.", f: "retain (v), retention (n), retainer (n)" },
  "series": { m: "Gốc Latin series (hàng, chuỗi) → nhiều thứ nối nhau thành chuỗi, như phim series nhiều tập.", e: "Sai: a series of event / a serie → Đúng: a series of events (series số ít và số nhiều giống nhau).", u: "a series of + danh từ số nhiều + động từ số ít: A series of tests was carried out. TV series, time series.", f: "series (n, sing/plural), serial (adj, n), serialize (v)" },
  "statistic": { m: "stat (nhà nước, như state) → con số nhà nước thu thập về dân số, kinh tế: số liệu thống kê.", e: "Sai: a statistics shows → Đúng: statistics show / a statistic shows. Nhấn âm 2: sta-TIS-tic.", u: "official statistics, statistics show/suggest that..., statistically significant. Dùng làm dẫn chứng trong Task 2 và mô tả Task 1.", f: "statistic (n), statistics (n), statistical (adj), statistically (adv), statistician (n)" },
  "status": { m: "stat (đứng, như stand, state) → vị trí mình đứng trong xã hội, hay trạng thái hiện tại.", e: "Phát âm: /ˈsteɪtəs/ (Anh) hoặc /ˈstætəs/ (Mỹ), không đọc ‘sta-tút’. Sai: high statuses people → Đúng: people of high status.", u: "social status, status symbol, marital status (mẫu đơn), check the status of an order (TOEIC), legal status.", f: "status (n), statuses (n, plural)" },
  "stress": { m: "Từ quen thuộc: sức ép đè lên tâm lý, hoặc lực nhấn vào một âm tiết, một ý.", e: "Sai: I am very stress → Đúng: I am very stressed (tính từ stressed). Stressful dùng cho sự việc: a stressful job.", u: "reduce/relieve stress, under stress, stress-related illness; stress the importance of... (nhấn mạnh, trang trọng). Phổ biến trong Speaking.", f: "stress (n, v), stressed (adj), stressful (adj), stressor (n)" },
  "subsequent": { m: "sub- (dưới, sau) + sequ (theo, như sequence) → đi theo sau, tức là tiếp theo.", e: "Sai: subsequent the war → Đúng: subsequent to the war hoặc after the war. Nhấn âm 1: SUB-se-quent.", u: "in subsequent years, subsequent events/research, subsequently (sau đó) dùng để nối ý trong Task 1 quy trình, trang trọng hơn then.", f: "subsequent (adj), subsequently (adv)" },
  "sum": { m: "Gốc Latin summa (tổng, đỉnh cao), như summit → tổng cộng tất cả lại.", e: "Sai: a big sum of people → Đúng: a large number of people (sum dùng cho tiền, con số, không dùng cho người).", u: "a large/considerable sum of money, a lump sum, sum up (tóm lại). Trong Writing: To sum up, ... để kết bài.", f: "sum (n, v), summation (n), summary (n), summarize (v)" },
  "summary": { m: "sum (tổng) + -ary → bản tổng hợp lại ý chính: bản tóm tắt.", e: "Sai: make a summary about the book → Đúng: write a summary of the book (summary đi với of).", u: "in summary (tóm lại), a brief summary, summary of findings. IELTS Task 1 cần câu tóm tắt tổng quan (overview).", f: "summary (n), summarize/summarise (v), summarily (adv)" },
  "undertake": { m: "under (bên dưới) + take (nhận) → nhận lấy việc về mình gánh vác: đảm nhận, tiến hành.", e: "Sai: undertake to doing → Đúng: undertake to do sth (cam kết làm). Chia: undertake, undertook, undertaken.", u: "undertake research/a project/a task/a study. Trang trọng hơn do, carry out; rất hợp với Writing học thuật.", f: "undertake (v), undertaking (n), undertaker (n: người lo tang lễ)" },
  "academy": { m: "Từ Akademeia, khu vườn ở Athens nơi Plato dạy học → nơi đào tạo chuyên sâu; liên hệ academic (thuộc học thuật).", e: "Nhấn âm 2: a-CA-de-my, không phải A-ca-de-my. Lưu ý academic lại nhấn âm 3: a-ca-DE-mic.", u: "Dùng cho trường đào tạo chuyên ngành: military academy, police academy, academy of music. Văn trang trọng; IELTS hay gặp academic hơn academy.", f: "academy (n), academic (adj, n), academically (adv), academician (n)" },
  "adjust": { m: "ad- (hướng tới) + just (đúng, vừa) → chỉnh cho vừa, cho đúng; nhớ 'just right'.", e: "Sai: adjust with the new life → Đúng: adjust to the new life (thích nghi dùng giới từ to).", u: "adjust to changes / a new environment, adjust the price / settings, make adjustments. Dùng tốt trong IELTS khi nói về thích nghi văn hóa, du học.", f: "adjust (v), adjustment (n), adjustable (adj), adjusted (adj)" },
  "alter": { m: "Gốc Latin alter = 'cái khác' (như alternative) → làm cho khác đi, thay đổi một phần.", e: "Nhầm chính tả với altar (bàn thờ). Sai: alter the altar plan → hiểu đúng: alter = thay đổi, altar = bàn thờ; phát âm giống nhau.", u: "alter the plan / the course of history, significantly alter. Trang trọng hơn change, thường chỉ thay đổi một phần, không thay toàn bộ.", f: "alter (v), alteration (n), altered (adj), unaltered (adj)" },
  "amend": { m: "Gốc Latin emendare: e- (loại bỏ) + menda (lỗi) → bỏ lỗi đi, sửa cho đúng; liên hệ mend (vá, sửa).", e: "Sai: make amend for the mistake → Đúng: make amends for the mistake (bù đắp, luôn có -s).", u: "amend a law / a contract / the constitution, an amendment to the bill. Văn pháp lý, chính trị; TOEIC hay gặp trong hợp đồng.", f: "amend (v), amendment (n), amends (n), amended (adj)" },
  "aware": { m: "Liên hệ beware (cảnh giác) → aware là đã 'để mắt tới', đã biết điều gì đang xảy ra.", e: "Sai: I am aware about the risk → Đúng: I am aware of the risk (aware đi với of hoặc that).", u: "be aware of / that, raise awareness, environmentally aware. IELTS: 'raise public awareness of climate change' là cụm rất tự nhiên.", f: "aware (adj), awareness (n), unaware (adj), unawares (adv)" },
  "capacity": { m: "Gốc Latin capere (chứa, nắm) → capable, capture; capacity là khả năng chứa hoặc làm được bao nhiêu.", e: "Nhấn âm 2: ca-PA-ci-ty. Sai: capacity of learn → Đúng: capacity to learn / capacity for learning.", u: "seating capacity, production capacity, at full capacity, in my capacity as manager (với tư cách). Hợp văn học thuật và kinh doanh.", f: "capacity (n), capable (adj), capability (n), incapacity (n), capacitor (n)" },
  "challenge": { m: "Gốc Pháp cổ chalenge = lời buộc tội, thách đấu → thách thức cần vượt qua.", e: "Sai: face with many challenges → Đúng: face many challenges / be faced with many challenges (face là ngoại động từ).", u: "face / meet / pose a challenge, a major challenge, rise to the challenge. Động từ: challenge an idea (chất vấn). Hay dùng trong IELTS Writing.", f: "challenge (n, v), challenging (adj), challenger (n), challenged (adj)" },
  "clause": { m: "Gốc Latin claudere (đóng) → close; clause là một 'đoạn khép kín' trong câu hoặc trong hợp đồng.", e: "Phát âm /klɔːz/ như 'claws', không đọc /klaʊs/ như Santa Claus. Đừng nhầm với cause.", u: "Hợp đồng: a clause in the contract, a penalty clause. Ngữ pháp: main clause, relative clause, subordinate clause.", f: "clause (n), clausal (adj)" },
  "compound": { m: "com- (cùng) + ponere (đặt) → đặt chung với nhau → hợp chất; liên hệ component, compose.", e: "Nhấn âm: danh từ/tính từ COM-pound; động từ com-POUND (làm trầm trọng thêm). Sai: compound the problem (nhấn âm 1).", u: "chemical compound, compound word, compound interest. Động từ: compound the problem (làm vấn đề tệ hơn), văn trang trọng.", f: "compound (n, adj, v), compounded (adj)" },
  "conflict": { m: "con- (cùng nhau) + fligere (đánh) → đánh nhau → xung đột; liên hệ inflict (gây ra).", e: "Danh từ nhấn âm 1: CON-flict; động từ nhấn âm 2: con-FLICT. Sai: conflict to → Đúng: conflict with.", u: "armed conflict, a conflict of interest, resolve a conflict, come into conflict with. Dùng nhiều trong IELTS chủ đề xã hội, gia đình.", f: "conflict (n, v), conflicting (adj), conflicted (adj)" },
  "consult": { m: "Gốc Latin consulere (hỏi ý kiến, cân nhắc) → consultant là người được hỏi ý kiến.", e: "Sai: consult to a lawyer → Đúng: consult a lawyer. Nhấn âm 2: con-SULT; danh từ consultant nhấn âm 2: con-SUL-tant.", u: "consult a doctor / a lawyer / a dictionary, consult with colleagues (bàn bạc). Trang trọng hơn ask; TOEIC hay gặp consultant, consultation.", f: "consult (v), consultant (n), consultation (n), consultancy (n), consultative (adj)" },
  "contact": { m: "con- (cùng) + tangere (chạm) → chạm vào nhau → liên lạc, tiếp xúc; liên hệ tangible.", e: "Sai: contact with me by email → Đúng: contact me by email (động từ contact không cần with).", u: "Danh từ: be in contact with, make contact, lose contact, eye contact, contact details. TOEIC rất hay gặp trong email công việc.", f: "contact (n, v), contactable (adj), contactless (adj)" },
  "decline": { m: "de- (xuống) + clinare (nghiêng) → nghiêng xuống → giảm; liên hệ incline (dốc lên).", e: "Sai: decline down / a decline of sales → Đúng: decline / a decline in sales (danh từ dùng giới từ in).", u: "decline sharply / steadily, a sharp decline in, decline an invitation (từ chối lịch sự). Rất hữu ích cho IELTS Task 1 mô tả biểu đồ.", f: "decline (v, n), declining (adj)" },
  "discrete": { m: "Gốc Latin discretus = tách riêng ra → từng phần riêng biệt; chữ e tách hai chữ t-e như phần rời.", e: "Nhầm chính tả: discrete (riêng biệt) khác discreet (kín đáo). Sai: a discreet category → Đúng: a discrete category.", u: "discrete units / categories / stages, discrete data (dữ liệu rời rạc). Văn học thuật, kỹ thuật; ít dùng trong hội thoại.", f: "discrete (adj), discretely (adv), discreteness (n)" },
  "draft": { m: "Liên hệ draw (vẽ, kéo) → bản phác thảo đầu tiên được 'vẽ' ra trước khi hoàn thiện.", e: "Chính tả: draft (Mỹ, và nghĩa bản nháp ở Anh) khác draught (Anh: gió lùa, bia tươi). Sai: a first draught of the essay.", u: "first / rough / final draft, draft a letter / a proposal, a draft agreement. Hay dùng khi nói về quy trình viết luận.", f: "draft (n, v), drafting (n), drafter (n), draftsman (n)" },
  "enable": { m: "en- (làm cho) + able (có thể) → làm cho có thể → tạo điều kiện, cho phép.", e: "Sai: enable people doing something → Đúng: enable people to do something (enable + tân ngữ + to V).", u: "enable sb to do sth, enable a feature (bật tính năng). Trang trọng hơn let; rất hay dùng trong IELTS khi nói về công nghệ.", f: "enable (v), enabling (adj), enabler (n), enablement (n), disable (v), able (adj)" },
  "energy": { m: "Gốc Hy Lạp en- (trong) + ergon (công việc) → khả năng làm việc bên trong; liên hệ ergonomic.", e: "Phát âm /ˈenədʒi/, nhấn âm 1: EN-er-gy, không đọc 'e-nơ-gi'. Sai: a renewable energies sources → Đúng: renewable energy sources.", u: "renewable / solar / nuclear energy, energy consumption, save energy, full of energy. Chủ đề môi trường trong IELTS rất hay gặp.", f: "energy (n), energetic (adj), energetically (adv), energize (v)" },
  "enforce": { m: "en- (làm cho) + force (sức mạnh) → dùng sức mạnh để buộc luật được tuân theo.", e: "Sai: enforce people to obey → Đúng: force people to obey / enforce the law (enforce đi với luật, không đi với người + to V).", u: "enforce the law / rules / regulations, strictly enforce, law enforcement. Văn trang trọng, chủ đề chính phủ, pháp luật.", f: "enforce (v), enforcement (n), enforceable (adj), enforcer (n)" },
  "entity": { m: "Gốc Latin ens / esse (tồn tại) → essence; entity là một thứ tồn tại độc lập.", e: "Nhấn âm 1: EN-ti-ty. Số nhiều: entities, không viết entitys.", u: "a separate / legal / political entity, business entity. Văn học thuật, pháp lý; chỉ tổ chức hay vật tồn tại độc lập.", f: "entity (n), entities (n, số nhiều)" },
  "equivalent": { m: "equi- (bằng nhau) + valere (có giá trị) → có giá trị ngang nhau; liên hệ equal, value.", e: "Sai: equivalent with → Đúng: equivalent to (tính từ) hoặc the equivalent of (danh từ). Nhấn âm 2: e-QUIV-a-lent.", u: "be equivalent to, roughly equivalent, the equivalent of 5 dollars. Hữu ích khi so sánh số liệu trong IELTS Task 1.", f: "equivalent (adj, n), equivalence (n), equivalently (adv)" },
  "evolve": { m: "e- (ra ngoài) + volvere (cuộn) → cuộn mở ra dần → phát triển từ từ; liên hệ revolve.", e: "Sai: humans evolved by apes → Đúng: humans evolved from earlier species (evolve from / into).", u: "evolve from / into, gradually evolve, constantly evolving. Dùng cho sinh học lẫn ý tưởng, công nghệ, ngôn ngữ phát triển dần.", f: "evolve (v), evolution (n), evolutionary (adj), evolving (adj)" },
  "expand": { m: "ex- (ra ngoài) + pandere (giăng ra) → giăng rộng ra; liên hệ expanse, expansion.", e: "Nhầm từ loại: Sai: the expand of the city → Đúng: the expansion of the city. Không nhầm với extend (kéo dài).", u: "expand rapidly, expand into new markets, expand on an idea (nói chi tiết hơn). Rất hay gặp trong kinh doanh, TOEIC.", f: "expand (v), expansion (n), expansive (adj), expanded (adj), expansionary (adj)" },
  "expose": { m: "ex- (ra ngoài) + ponere (đặt) → đặt ra ngoài cho người ta thấy hoặc chịu tác động.", e: "Sai: be exposed with pollution → Đúng: be exposed to pollution (expose đi với to).", u: "expose sb to risk / danger, be exposed to sunlight, expose corruption (vạch trần). Chủ đề sức khỏe, môi trường, báo chí.", f: "expose (v), exposure (n), exposed (adj), exposé (n)" },
  "external": { m: "Gốc Latin exter (bên ngoài) → ex- như exit; ngược nghĩa với internal (bên trong).", e: "Sai: outside factors → nên dùng external factors trong văn học thuật. Không dùng external để chỉ người nước ngoài (đó là foreign).", u: "external factors / pressure / audit, external hard drive, for external use only. Văn học thuật và kinh doanh; đối lập internal.", f: "external (adj), externally (adv), externalize (v), externality (n)" },
  "facilitate": { m: "Gốc Latin facilis (dễ) → facile, facility; facilitate là làm cho việc gì dễ dàng hơn.", e: "Sai: facilitate students to learn → Đúng: facilitate students' learning / help students learn (facilitate nhận sự việc làm tân ngữ).", u: "facilitate communication / learning / trade, facilitate a discussion. Rất trang trọng; IELTS Writing dùng thay make easier.", f: "facilitate (v), facilitation (n), facilitator (n), facility (n)" },
  "fundamental": { m: "Gốc Latin fundus (đáy) → foundation, fund; fundamental là thuộc phần móng, nền tảng.", e: "Nhấn âm 3: fun-da-MEN-tal. Sai: a fundamental of the problem → Đúng: the fundamentals (số nhiều) hoặc fundamental to.", u: "fundamental change / principle / right, be fundamental to sth, fundamentally different. Trang trọng hơn basic, rất hợp IELTS.", f: "fundamental (adj), fundamentals (n), fundamentally (adv), fundamentalism (n), fundamentalist (n)" },
  "generate": { m: "Gốc Latin genus (giống, loài) → gene, generation; generate là sinh ra, tạo ra.", e: "Sai: generate an idea of new product → Đúng: generate ideas for a new product. Nhầm từ loại: generate (v) với generation (n).", u: "generate income / revenue / electricity / interest, generate jobs. Trang trọng hơn make, create; hữu ích trong IELTS và TOEIC.", f: "generate (v), generation (n), generator (n), generative (adj)" },
  "generation": { m: "Gốc Latin genus (giống, dòng dõi) → gene, generate; generation là một lứa người cùng thời.", e: "Sai: the young generations is → Đúng: the younger generation is (thường dùng số ít với the younger / older generation).", u: "the younger / older generation, future generations, generation gap, power generation (sản xuất điện). Phổ biến trong IELTS chủ đề gia đình.", f: "generation (n), generational (adj), generate (v)" },
  "image": { m: "Gốc Latin imago (hình ảnh) → imagine, imagination; image là hình ảnh nhìn thấy hoặc hình dung.", e: "Phát âm /ˈɪmɪdʒ/: IM-ij, không đọc 'i-mây' hay 'i-mếch'.", u: "public / brand / self image, improve its image, an image of. Hay dùng khi nói về danh tiếng công ty, quảng cáo, mạng xã hội.", f: "image (n), imagery (n), imagine (v), imaginary (adj), imaginative (adj)" },
  "liberal": { m: "Gốc Latin liber (tự do) → liberty, liberate; liberal là cởi mở, tôn trọng tự do cá nhân.", e: "False friend: liberal không có nghĩa 'rảnh rỗi' như free. Sai: liberal time → Đúng: free time; liberal chỉ quan điểm cởi mở.", u: "liberal attitudes / views, liberal arts, liberal democracy, a liberal amount of (nhiều, rộng rãi). Chủ đề chính trị, xã hội.", f: "liberal (adj, n), liberalism (n), liberalize (v), liberally (adv), liberty (n)" },
  "licence": { m: "Gốc Latin licere (được phép) → license; licence là giấy cho phép làm việc gì.", e: "Chính tả: Anh-Anh licence (n) / license (v); Anh-Mỹ dùng license cho cả hai. Sai: driver licence (Mỹ) → Đúng: driver's license.", u: "driving licence, a licence to sell alcohol, under licence, revoke a licence. TOEIC hay gặp trong ngữ cảnh kinh doanh, pháp lý.", f: "licence (n), license (v), licensed (adj), licensee (n), licensing (n)" },
  "logic": { m: "Gốc Hy Lạp logos (lời nói, lý lẽ) → biology, dialogue; logic là cách lập luận hợp lý.", e: "Nhầm từ loại: Sai: his argument is very logic → Đúng: his argument is very logical (logic là danh từ).", u: "the logic behind a decision, flawed logic, logical conclusion. IELTS: tiêu chí Coherence đòi hỏi lập luận logical.", f: "logic (n), logical (adj), logically (adv), illogical (adj), logician (n)" },
  "margin": { m: "Gốc Latin margo (mép, bờ) → marginal; margin là phần lề, phần chênh lệch ở rìa.", e: "Sai: win with a big margin → Đúng: win by a wide margin (đi với by và wide / narrow).", u: "profit margin, by a narrow / wide margin, in the margin (ở lề giấy), margin of error. TOEIC rất hay gặp profit margin.", f: "margin (n), marginal (adj), marginally (adv), marginalize (v), marginalized (adj)" },
  "medical": { m: "Gốc Latin medicus (thầy thuốc) → medicine, remedy; medical là thuộc về y khoa.", e: "Nhầm từ: Sai: I need some medical (thuốc) → Đúng: I need some medicine. Medical là tính từ, trừ nghĩa 'buổi khám sức khỏe' (Anh-Anh).", u: "medical treatment / care / research / record, medical staff, seek medical advice. Chủ đề sức khỏe IELTS rất hay gặp.", f: "medical (adj), medically (adv), medicine (n), medication (n), medicinal (adj)" },
  "mental": { m: "Gốc Latin mens (tâm trí) → mind, mention, mentality; mental là thuộc về tâm trí.", e: "Sai: mental health is important for spirit → Đúng: mental health; đừng nhầm mental (tâm lý, trí óc) với spiritual (tâm linh).", u: "mental health / illness / ability, mental arithmetic, make a mental note. Chủ đề sức khỏe, áp lực học tập trong IELTS.", f: "mental (adj), mentally (adv), mentality (n)" },
  "modify": { m: "Gốc Latin modus (cách thức, khuôn) → mode, model; modify là chỉnh lại khuôn, thay đổi nhẹ.", e: "Sai: modify about the plan → Đúng: modify the plan (ngoại động từ, không cần giới từ). Phân biệt modify (chỉnh nhẹ) và change.", u: "modify a design / behaviour / plan, genetically modified food (GM food), slightly modified. Chủ đề khoa học, công nghệ trong IELTS.", f: "modify (v), modification (n), modified (adj), modifier (n)" },
  "monitor": { m: "Gốc Latin monere (cảnh báo, nhắc) → admonish; monitor là người hay vật theo dõi và cảnh báo.", e: "Nhấn âm 1: MON-i-tor. False friend: lớp trưởng là class monitor (Anh-Anh), không phải monitor of class.", u: "monitor progress / closely / pollution levels, a heart monitor, computer monitor. Trang trọng hơn watch; hay dùng trong kinh doanh, y tế.", f: "monitor (v, n), monitoring (n), monitored (adj)" },
  "network": { m: "net (lưới) + work → mạng lưới các đường nối với nhau; dễ nhớ như lưới đánh cá.", e: "Sai: social networks site → Đúng: social networking site. Nhầm network (mạng) với internet (Internet viết hoa là mạng toàn cầu).", u: "social network, transport network, build a network of contacts, networking event. TOEIC: networking là mở rộng quan hệ công việc.", f: "network (n, v), networking (n), networked (adj)" },
  "notion": { m: "Gốc Latin noscere (biết) → notice, note; notion là điều mình biết hoặc nghĩ trong đầu → khái niệm.", e: "Sai: I have no notion about it → Tự nhiên hơn: I have no idea about it. Notion đi với of hoặc that: the notion that...", u: "the notion of freedom, reject the notion that, a vague notion. Văn học thuật, trang trọng hơn idea, hợp IELTS Writing.", f: "notion (n), notional (adj), notionally (adv)" },
  "objective": { m: "ob- (hướng vào) + jacere (ném) → thứ ném ra phía trước để nhắm tới; liên hệ object, project.", e: "Nhầm nghĩa: objective (n) = mục tiêu, objective (adj) = khách quan. Sai: an objectively → Đúng: an objective (mục tiêu).", u: "achieve / meet an objective, main objective, objective assessment (adj). Trang trọng hơn goal; hay dùng trong kế hoạch kinh doanh.", f: "objective (n, adj), objectively (adv), objectivity (n), object (n, v)" },
  "orient": { m: "Gốc Latin oriri (mọc lên) → phương đông nơi mặt trời mọc; orient là xác định hướng đi.", e: "Anh-Anh thường dùng orientate, Anh-Mỹ dùng orient. Sai: a customer orientated company (Mỹ) → customer-oriented company.", u: "be oriented towards / to, career-oriented, orient yourself in a new city, orientation week. Dạng phân từ oriented phổ biến nhất.", f: "orient (v), orientate (v), orientation (n), oriented (adj), disoriented (adj)" },
  "perspective": { m: "per- (xuyên qua) + specere (nhìn) → nhìn xuyên qua → góc nhìn; liên hệ inspect, spectator.", e: "Sai: in my perspective → Đúng: from my perspective. Nhấn âm 2: per-SPEC-tive.", u: "from a different perspective, put things into perspective, a historical / global perspective. IELTS Writing dùng thay 'in my opinion'.", f: "perspective (n), perspectives (n, số nhiều)" },
  "precise": { m: "pre- (trước) + caedere (cắt) → cắt gọn sẵn → chính xác, rõ ràng; liên hệ concise, scissors.", e: "Nhầm từ loại: Sai: the precise of the data → Đúng: the precision of the data. Phát âm /prɪˈsaɪs/, nhấn âm 2.", u: "precise details / measurements / instructions, to be precise. Mạnh hơn exact trong văn kỹ thuật; dùng tốt trong IELTS Speaking.", f: "precise (adj), precisely (adv), precision (n), imprecise (adj)" },
  "prime": { m: "Gốc Latin primus (thứ nhất) → primary, prince; prime là quan trọng hàng đầu, chính yếu.", e: "Sai: prime minister of Vietnam (viết hoa khi là chức danh) → Prime Minister. Không nhầm prime với primary trong 'primary school'.", u: "prime example / suspect / location / time, of prime importance, prime minister. Trang trọng; 'a prime example of' rất hữu ích trong IELTS.", f: "prime (adj, n, v), primary (adj), primarily (adv), primal (adj)" },
  "psychology": { m: "Gốc Hy Lạp psyche (tâm hồn) + logos (môn học) → môn học về tâm trí; liên hệ biology.", e: "Chữ p câm: phát âm /saɪˈkɒlədʒi/, nhấn âm 2: psy-CHO-lo-gy. Sai: đọc 'pờ-sai-cô-lô-gi'.", u: "child psychology, the psychology of consumers, study psychology. Chủ đề giáo dục, quảng cáo; dạng psychological dùng rất nhiều.", f: "psychology (n), psychological (adj), psychologically (adv), psychologist (n)" },
  "pursue": { m: "pur- (= pro, về phía trước) + sequi (theo) → đi theo về phía trước; liên hệ sequence, follow.", e: "Sai: pursue after a dream → Đúng: pursue a dream (không cần after). Chính tả: pursue, không phải persue.", u: "pursue a career / a degree / a goal / a dream, pursue further studies. Trang trọng; rất hợp IELTS khi nói về du học.", f: "pursue (v), pursuit (n), pursuer (n)" },
  "ratio": { m: "Gốc Latin ratio (sự tính toán) → rate, rational; ratio là phép so sánh hai số lượng.", e: "Sai: the ratio of men and women → Đúng: the ratio of men to women. Phát âm /ˈreɪʃiəʊ/: RAY-shee-oh.", u: "a ratio of 3 to 1, the teacher-student ratio, the ratio of A to B. Hữu ích trong IELTS Task 1 khi so sánh số liệu.", f: "ratio (n), ratios (n, số nhiều)" },
  "reject": { m: "re- (lại, trở lại) + jacere (ném) → ném trả lại → từ chối, bác bỏ; liên hệ eject, project.", e: "Danh từ nhấn âm 1: RE-ject (đồ bị loại); động từ nhấn âm 2: re-JECT. Sai: reject to do → Đúng: refuse to do.", u: "reject a proposal / an offer / an idea, flatly reject, be rejected by. Mạnh hơn decline; dùng trong văn trang trọng.", f: "reject (v, n), rejection (n), rejected (adj)" },
  "revenue": { m: "re- (trở lại) + venire (đến) → tiền quay lại với mình → doanh thu; liên hệ venue, avenue.", e: "Nhầm revenue (doanh thu) với profit (lợi nhuận, sau khi trừ chi phí). Nhấn âm 1: REV-e-nue.", u: "generate / increase revenue, tax revenue, advertising revenue, annual revenue. TOEIC và IELTS Task 1 về số liệu kinh doanh.", f: "revenue (n), revenues (n, số nhiều)" },
  "stable": { m: "Gốc Latin stare (đứng) → stand, status; stable là đứng vững, không lung lay.", e: "Nhầm từ loại: Sai: the stable of the economy → Đúng: the stability of the economy. Phát âm /ˈsteɪbl/, nhấn âm 1.", u: "a stable job / income / relationship, remain stable, a stable condition. IELTS Task 1: 'remained stable at 20%' rất hay dùng.", f: "stable (adj), stability (n), stabilize (v), unstable (adj), instability (n)" },
  "style": { m: "Gốc Latin stilus (cây bút viết) → cách viết riêng của mỗi người → phong cách.", e: "Phát âm /staɪl/ một âm tiết, không đọc 'xờ-tai-lờ'. Sai: a life style → Đúng: lifestyle (viết liền).", u: "lifestyle, learning style, management style, writing style, in style (thời thượng). Chủ đề lối sống, thời trang trong IELTS Speaking.", f: "style (n, v), stylish (adj), stylist (n), stylistic (adj), stylishly (adv)" },
  "substitute": { m: "sub- (thay ở dưới) + statuere (đặt) → đặt vào chỗ thay thế; liên hệ institute, constitute.", e: "Sai: substitute A by B → Đúng: substitute B for A (dùng B thay A) hoặc replace A with B.", u: "a substitute for sugar, substitute teacher, no substitute for experience. Dạng 'there is no substitute for' rất tự nhiên trong IELTS.", f: "substitute (n, v), substitution (n), substitutable (adj)" },
  "sustain": { m: "sus- (= sub, từ dưới) + tenere (giữ) → giữ đỡ từ bên dưới → duy trì; liên hệ maintain.", e: "Nhầm từ loại: Sai: sustain development → Đúng: sustainable development (tính từ sustainable).", u: "sustain growth / interest / life, sustain an injury (bị thương), sustainable energy. Chủ đề môi trường IELTS rất hay dùng.", f: "sustain (v), sustainable (adj), sustainability (n), sustained (adj), sustenance (n)" },
  "symbol": { m: "Gốc Hy Lạp sym- (cùng) + ballein (ném) → ném chung lại thành dấu hiệu nhận biết; liên hệ symphony.", e: "Chính tả: symbol (biểu tượng) khác cymbal (cái chũm chọe), phát âm giống nhau. Sai: a symbol for peace → thường dùng a symbol of peace.", u: "a symbol of power / freedom / wealth, status symbol, chemical symbol. Hay dùng khi nói về văn hóa, di sản trong IELTS.", f: "symbol (n), symbolic (adj), symbolize (v), symbolism (n), symbolically (adv)" },
  "target": { m: "Gốc Pháp cổ targe (cái khiên tròn) → hồng tâm để nhắm bắn → mục tiêu, chỉ tiêu.", e: "Phát âm /ˈtɑːɡɪt/: TAR-git, không đọc 'tar-gét'. Sai: reach the target to → Đúng: meet / reach / hit a target.", u: "meet / achieve / set a target, sales target, target audience / market, be targeted at. Rất hay gặp trong TOEIC kinh doanh.", f: "target (n, v), targeted (adj)" },
  "transit": { m: "trans- (qua, ngang) + ire (đi) → đi băng qua; liên hệ transition, transport.", e: "Sai: the goods were damaged on transit → Đúng: in transit. Phân biệt transit (quá cảnh) với transition (chuyển đổi).", u: "in transit, public transit (Mỹ), transit passengers / visa, mass transit. TOEIC hay gặp trong vận chuyển hàng và du lịch.", f: "transit (n, v), transition (n), transitional (adj), transitory (adj)" },
  "trend": { m: "Gốc Anh cổ trendan (xoay, lăn) → hướng đi đang xoay theo → xu hướng; liên hệ trendy.", e: "Sai: a trend of using smartphones → Đúng: a trend towards using smartphones / the trend in smartphone use.", u: "upward / downward trend, follow / set a trend, current trends, fashion trends. Cực kỳ quan trọng cho IELTS Task 1 mô tả xu hướng.", f: "trend (n, v), trendy (adj), trending (adj), trendsetter (n)" },
  "version": { m: "Gốc Latin vertere (xoay, chuyển) → convert, reverse; version là một bản 'xoay' khác của cùng một thứ.", e: "Sai: the new version of iPhone 15 → Đúng: the new version of the iPhone / the latest version. Phát âm /ˈvɜːʃn/: VER-shən.", u: "the latest / updated / online version, a simplified version, your version of events. Dùng nhiều cho phần mềm, sách, câu chuyện.", f: "version (n), versions (n, số nhiều)" },
  "welfare": { m: "well (tốt) + fare (đi, sống) → sống tốt → phúc lợi; liên hệ farewell (lời chúc đi bình an).", e: "Chính tả: welfare chỉ có một chữ l, không viết wellfare. Không đếm được: Sai: welfares → Đúng: welfare.", u: "social welfare, animal welfare, the welfare of children, welfare state, be on welfare (Mỹ: nhận trợ cấp). Chủ đề chính phủ trong IELTS.", f: "welfare (n), welfarism (n)" },
  "whereas": { m: "where + as → 'ở chỗ này... còn ở chỗ kia' → dùng để đối lập hai sự việc.", e: "Sai: Whereas, prices rose. → Đúng: Prices rose, whereas wages fell. Whereas nối hai mệnh đề, không đứng một mình như however.", u: "Dùng đối chiếu số liệu trong IELTS Task 1: A increased, whereas B decreased. Trang trọng hơn while, có thể đứng đầu câu.", f: "whereas (conj); không có dạng khác" },
  "abstract": { m: "abs- (rời khỏi) + tract (kéo, như tractor) → kéo ra khỏi thực tế cụ thể → trừu tượng.", e: "Sai: nhấn âm 2 khi là tính từ → Đúng: AB-stract (adj), còn động từ nhấn ab-STRACT; danh từ 'tóm tắt' cũng là AB-stract.", u: "abstract concept/idea/thinking; in the abstract (trên lý thuyết). Hay dùng trong Writing Task 2 khi đối lập với 'concrete' (cụ thể).", f: "abstract (adj/n/v), abstraction (n), abstractly (adv)" },
  "accurate": { m: "ac- (hướng tới) + cura (chăm chút, như cure, care) → làm cẩn thận nên chính xác.", e: "Sai: The data is accuracy → Đúng: The data is accurate (accuracy là danh từ, accurate là tính từ).", u: "accurate information/data/figures/description; highly accurate. Trang trọng hơn 'correct'; nhấn mạnh độ chính xác chi tiết, phù hợp Task 1 và TOEIC.", f: "accurate (adj), accuracy (n), accurately (adv), inaccurate (adj), inaccuracy (n)" },
  "acknowledge": { m: "ac- + knowledge (hiểu biết) → công nhận điều mình đã biết → thừa nhận.", e: "Sai: acknowledge about the problem → Đúng: acknowledge the problem (không đi với about). Lưu ý chính tả: acknowledgement (UK) / acknowledgment (US).", u: "acknowledge the importance/fact that...; widely acknowledged as. Trang trọng hơn 'admit'; dùng để nhượng bộ trong bài luận: 'It must be acknowledged that...'.", f: "acknowledge (v), acknowledgement/acknowledgment (n), acknowledged (adj)" },
  "aggregate": { m: "ag- (vào) + greg (bầy đàn, như congregate) → gom cả đàn lại → tổng hợp.", e: "Sai: đọc giống nhau cho mọi từ loại → Đúng: tính từ/danh từ đọc /ˈægrɪɡət/, động từ đọc /ˈægrɪɡeɪt/.", u: "aggregate data/demand/score; in aggregate (tính tổng thể). Văn phong kinh tế, thống kê; hợp với Task 1 khi nói số liệu tổng.", f: "aggregate (adj/n/v), aggregation (n)" },
  "allocate": { m: "al- (tới) + locus (chỗ, như location) → đặt mỗi thứ vào chỗ của nó → phân bổ.", e: "Sai: allocate money for each department → Đúng: allocate money to each department (giao cho ai dùng to; 'for' dành cho mục đích).", u: "allocate funds/resources/time to sth; allocate budget for a project. Thường dùng bị động: be allocated to. Rất phổ biến trong TOEIC và Task 2 về chính sách.", f: "allocate (v), allocation (n), allocated (adj)" },
  "assign": { m: "as- (tới) + sign (dấu hiệu, ký) → đánh dấu giao cho ai đó → phân công.", e: "Sai: phát âm rõ chữ g /əˈsɪɡn/ → Đúng: /əˈsaɪn/, g câm; assignment cũng câm g.", u: "assign a task/project to sb; be assigned to a team. 'Assignment' là bài tập được giao. Thường gặp trong email công việc TOEIC.", f: "assign (v), assignment (n), assigned (adj), reassign (v)" },
  "attach": { m: "Ngược với detach (tháo ra) → attach là gắn vào; nghĩa bóng: gắn tầm quan trọng vào điều gì.", e: "Sai: attach importance on education → Đúng: attach importance to education (luôn đi với to). Chính tả: attach, không có t trước ch.", u: "attach a file/document; attach great importance/value to sth; be attached to sb (gắn bó). 'Please find attached...' là câu kinh điển trong email TOEIC.", f: "attach (v), attachment (n), attached (adj), detach (v)" },
  "author": { m: "Cùng gốc auctor (người tạo ra, liên quan authority) → người tạo ra tác phẩm → tác giả.", e: "Sai: The author of this song → Đúng: The writer/composer of this song (author chủ yếu dùng cho sách, bài viết).", u: "the author of a book/study/report; co-author. Động từ 'author' khá trang trọng. Trong Writing, tránh nói 'the author thinks' nếu không có văn bản.", f: "author (n/v), authorship (n), co-author (n/v)" },
  "bond": { m: "Gần với bind (buộc) → sợi dây buộc người với người → mối liên kết; giấy cam kết nợ → trái phiếu.", e: "Sai: a strong bond among mother with child → Đúng: a strong bond between mother and child (bond between A and B).", u: "form/build a bond; emotional/family bond; government bonds (trái phiếu chính phủ). Nghĩa tài chính hay gặp trong TOEIC, nghĩa tình cảm trong Speaking.", f: "bond (n/v), bonding (n), bondage (n)" },
  "brief": { m: "Gốc Latin brevis (ngắn), cùng gốc brevity, abbreviate → ngắn gọn.", e: "Sai: In brief time, he finished → Đúng: In a short time, he finished; 'in brief' nghĩa là 'tóm lại'.", u: "a brief summary/visit/description; keep it brief; in brief. Danh từ 'brief' là bản hướng dẫn công việc, động từ 'brief sb on sth' là tóm tắt thông tin.", f: "brief (adj/n/v), briefly (adv), briefing (n), brevity (n)" },
  "capable": { m: "Gốc capere (nắm lấy, như capture, capacity) → nắm được việc → có khả năng.", e: "Sai: She is capable to solve it → Đúng: She is capable of solving it (capable of + V-ing; able to + V).", u: "be capable of doing sth; highly capable staff. Mang nghĩa có năng lực thực sự, trang trọng hơn 'can'.", f: "capable (adj), capability (n), capably (adv), incapable (adj)" },
  "cite": { m: "Gốc citare (gọi ra, như recite) → gọi tên nguồn ra → trích dẫn.", e: "Sai: nhầm cite với site/sight do đọc giống nhau → Đúng: cite a source (trích dẫn); site là địa điểm; sight là cảnh tượng.", u: "cite an example/a study/a reason; be cited as. Hay dùng trong văn học thuật: 'As cited in...'. Có thể thay 'give an example' trong Task 2.", f: "cite (v), citation (n), cited (adj)" },
  "cooperate": { m: "co- (cùng) + operate (làm việc, vận hành) → cùng làm việc → hợp tác.", e: "Sai: cooperate together with them → Đúng: cooperate with them ('together' thừa vì co- đã có nghĩa 'cùng').", u: "cooperate with sb on sth; international cooperation; cooperative attitude. Hay dùng trong Task 2 về toàn cầu hóa, môi trường.", f: "cooperate (v), cooperation (n), cooperative (adj/n), cooperatively (adv)" },
  "discriminate": { m: "dis- (tách) + cernere (sàng lọc, như discern) → tách riêng ra → phân biệt, phân biệt đối xử.", e: "Sai: discriminate women → Đúng: discriminate against women (phân biệt đối xử phải có against); 'discriminate between A and B' là phân biệt A với B.", u: "discriminate against minorities; racial/gender discrimination; discriminate between right and wrong. Chủ đề quen thuộc trong Task 2 về bình đẳng.", f: "discriminate (v), discrimination (n), discriminatory (adj)" },
  "display": { m: "dis- (mở ra) + plicare (gấp, như reply) → mở nếp gấp ra cho người xem → trưng bày.", e: "Sai: The goods are displayed at the window → Đúng: The goods are displayed in the window (trong tủ kính dùng in).", u: "display products/emotions/skills; on display (đang trưng bày). Trong Task 1: 'The chart displays...' thay cho 'shows' để đa dạng từ vựng.", f: "display (v/n), displayed (adj)" },
  "diverse": { m: "di- (tách ra) + vertere (quay, như divert, reverse) → quay về nhiều hướng → đa dạng.", e: "Sai: a diversity culture → Đúng: a diverse culture (diverse là tính từ, diversity là danh từ).", u: "a diverse range of; culturally diverse; diverse backgrounds. 'Biodiversity' là đa dạng sinh học, hay gặp trong Task 2 về môi trường.", f: "diverse (adj), diversity (n), diversify (v), diversification (n), diversely (adv)" },
  "domain": { m: "Gốc dominus (chủ nhân, như dominate) → vùng do chủ cai quản → lĩnh vực, phạm vi.", e: "Sai: đọc nhấn âm 2 do-MAIN → Đúng: nhấn âm 1: DO-main /ˈdəʊmeɪn/.", u: "in the domain of science; public domain (thuộc sở hữu chung); domain name (tên miền). Trang trọng hơn 'field' hoặc 'area'.", f: "domain (n), dominate (v), dominion (n)" },
  "edit": { m: "Gốc edere (đưa ra, như edition) → chỉnh sửa trước khi đưa ra công chúng.", e: "Sai: the second editor of the book → Đúng: the second edition of the book (edition là ấn bản; editor là người biên tập).", u: "edit a document/video; edited by; a revised edition. Dùng trong TOEIC về xuất bản, truyền thông.", f: "edit (v/n), editor (n), edition (n), editorial (adj/n), editing (n)" },
  "enhance": { m: "en- (làm cho) + altus (cao, như altitude) → làm cho cao hơn → nâng cao.", e: "Sai: enhance people → Đúng: enhance people's skills (enhance đi với chất lượng, giá trị, kỹ năng chứ không đi với người).", u: "enhance quality/performance/reputation/the experience. Trang trọng, thay 'improve' trong Writing để ăn điểm từ vựng.", f: "enhance (v), enhancement (n), enhanced (adj)" },
  "estate": { m: "Gốc status (tình trạng, như state) → tài sản thể hiện địa vị → điền trang, bất động sản.", e: "Sai: real-estates market → Đúng: real estate market (real estate là danh từ không đếm được).", u: "real estate agent/market; housing estate (UK: khu nhà ở); estate (di sản của người đã mất). Hay gặp trong TOEIC về nhà đất.", f: "estate (n), real estate (n)" },
  "exceed": { m: "ex- (ra ngoài) + cedere (đi, như proceed) → đi ra ngoài giới hạn → vượt quá.", e: "Sai: exceed over the limit → Đúng: exceed the limit (exceed là ngoại động từ, không cần over). Chính tả: exceed, không phải exceede.", u: "exceed expectations/the limit/the budget/the speed limit. Trong Task 1: 'Sales exceeded 5 million'. 'Excessive' mang nghĩa tiêu cực.", f: "exceed (v), excess (n/adj), excessive (adj), excessively (adv), exceedingly (adv)" },
  "expert": { m: "Gốc experiri (thử, như experience, experiment) → người thử nhiều nên thành thạo → chuyên gia.", e: "Sai: an expert about economics → Đúng: an expert in/on economics (expert đi với in hoặc on).", u: "an expert in/on sth; according to experts; expert advice/opinion. Dùng để dẫn chứng trong Task 2: 'Experts argue that...'.", f: "expert (n/adj), expertise (n), expertly (adv)" },
  "explicit": { m: "ex- (ra) + plicare (gấp) → mở nếp gấp ra hết → rõ ràng; trái nghĩa implicit (ngầm).", e: "Sai: The rules are stated explicit → Đúng: The rules are stated explicitly (bổ nghĩa động từ cần trạng từ).", u: "explicit instructions/rules/reference; make sth explicit. Văn phong trang trọng, nhấn mạnh nói thẳng, không mơ hồ.", f: "explicit (adj), explicitly (adv), explicitness (n), implicit (adj)" },
  "federal": { m: "Gốc foedus (hiệp ước, như federation) → các bang ký hiệp ước liên kết → liên bang.", e: "Sai: the federal of states → Đúng: the federation of states (federal là tính từ, federation là danh từ).", u: "federal government/law/budget; at the federal level. Dùng khi nói về Mỹ, Úc, Đức; đối lập với state/local.", f: "federal (adj), federation (n), federalism (n), federally (adv)" },
  "fee": { m: "Dễ nhớ: 'phí' và 'fee' gần âm. Fee là tiền trả cho dịch vụ chuyên môn.", e: "Sai: bus fee, hotel fee → Đúng: bus fare, hotel rate; fee dùng cho học phí, phí dịch vụ: tuition fees, entrance fee.", u: "tuition/membership/entrance/late fee; charge a fee; pay a fee. Phân biệt fare (vé xe), fine (tiền phạt), charge (phí chung).", f: "fee (n)" },
  "flexible": { m: "flex (uốn cong, như reflex) + -ible (có thể) → có thể uốn được → linh hoạt.", e: "Sai: flexable → Đúng: flexible (đuôi -ible). Danh từ là flexibility, không phải flexiblity.", u: "flexible working hours/schedule/approach; be flexible about sth. Chủ đề work-life balance hay gặp trong IELTS và TOEIC.", f: "flexible (adj), flexibility (n), flexibly (adv), inflexible (adj)" },
  "furthermore": { m: "further (xa hơn) + more (thêm) → đi xa thêm một ý → hơn nữa.", e: "Sai: Furthermore that, ... → Đúng: Furthermore, ... (đứng đầu câu, theo sau là dấu phẩy, không đi với that).", u: "Từ nối bổ sung ý, trang trọng; dùng trong Writing thay 'and' hoặc 'also'. Đồng nghĩa: moreover, in addition. Tránh lạm dụng.", f: "furthermore (adv), further (adv/adj/v)" },
  "gender": { m: "Gốc genus (loại, giống, như generate, genre) → giống loài → giới tính.", e: "Sai: dùng gender và sex hoàn toàn như nhau → Đúng: gender nhấn mạnh vai trò xã hội; sex chỉ giới tính sinh học.", u: "gender equality/gap/roles/discrimination; regardless of gender. Chủ đề quan trọng trong Task 2.", f: "gender (n), gendered (adj)" },
  "ignorant": { m: "i- (không) + gnoscere (biết, như know, diagnose) → không biết → thiếu hiểu biết.", e: "Sai: He is ignorant about me → Đúng: He ignores me (ignore là phớt lờ; ignorant of sth là không biết gì về điều đó).", u: "be ignorant of/about sth; ignorance of the law. Có thể mang sắc thái chê bai, cần thận trọng khi nói về người khác.", f: "ignorant (adj), ignorance (n), ignore (v), ignorantly (adv)" },
  "incentive": { m: "in- + canere (hát, thổi nhạc, như chant) → điệu nhạc thúc giục người ta hành động → động lực, ưu đãi.", e: "Sai: an incentive money → Đúng: a financial incentive (incentive là danh từ đếm được: incentives; cấu trúc: an incentive for sb to do sth).", u: "tax incentives; financial incentive; provide/offer an incentive to do sth. Hay dùng trong Task 2 khi đề xuất giải pháp chính sách.", f: "incentive (n), incentivize/incentivise (v)" },
  "incidence": { m: "in- (vào) + cadere (rơi, như accident) → số lần điều gì 'rơi vào' → tỉ lệ xảy ra.", e: "Sai: nhầm incidence với incident → Đúng: the incidence of cancer (tỉ lệ mắc); an incident là một vụ việc cụ thể.", u: "a high/low incidence of disease/crime; increase in incidence. Văn phong học thuật, y tế; hợp với Task 1 và Reading.", f: "incidence (n), incident (n), incidental (adj), incidentally (adv)" },
  "incorporate": { m: "in- (vào) + corpus (thân thể, như corporation) → đưa vào thành một thể → kết hợp.", e: "Sai: incorporate exercise to daily life → Đúng: incorporate exercise into daily life (đi với into).", u: "incorporate sth into sth; incorporate feedback/technology. 'Incorporated (Inc.)' là công ty cổ phần trong TOEIC.", f: "incorporate (v), incorporation (n), incorporated (adj)" },
  "index": { m: "Gốc indicare (chỉ ra, như indicate) → ngón trỏ là index finger → chỉ số, mục lục.", e: "Sai: many indexs → Đúng: indexes (thông dụng) hoặc indices (học thuật, kinh tế).", u: "price index; consumer price index; stock market index; body mass index. Hay gặp trong Task 1 và tin kinh tế TOEIC.", f: "index (n/v), indices (n pl), indexed (adj), indexation (n)" },
  "inhibit": { m: "in- (vào trong) + habere (giữ, như habit) → giữ lại bên trong → kìm hãm.", e: "Sai: inhibit him to speak → Đúng: inhibit him from speaking (inhibit sb from doing sth). Đừng nhầm với inhabit (cư trú).", u: "inhibit growth/development; inhibit sb from doing sth. Trang trọng hơn 'prevent', 'stop'. Hay dùng trong khoa học và tâm lý.", f: "inhibit (v), inhibition (n), inhibitor (n), inhibited (adj)" },
  "initiate": { m: "Gốc initium (sự khởi đầu, như initial) → bắt đầu một việc → khởi xướng.", e: "Sai: initiate to do sth → Đúng: initiate a project; initiate là ngoại động từ, cần tân ngữ, không theo sau bởi to-V.", u: "initiate a programme/change/talks; take the initiative (chủ động). Trang trọng hơn 'start'; phù hợp Writing và TOEIC.", f: "initiate (v), initiative (n), initiation (n), initial (adj), initially (adv)" },
  "input": { m: "in (vào) + put (đặt) → thứ được đặt vào → đầu vào, ý kiến đóng góp.", e: "Sai: give many inputs → Đúng: give a lot of input (nghĩa 'ý kiến đóng góp' thường không đếm được).", u: "input into/on sth; valuable input; input and output. Trong công việc: 'We value your input'. Hay gặp trong TOEIC.", f: "input (n/v), output (n)" },
  "instruct": { m: "in- (vào) + struere (xây, như construct, structure) → xây kiến thức vào đầu → hướng dẫn.", e: "Sai: instruct him doing sth → Đúng: instruct him to do sth (instruct sb to do sth).", u: "instruct sb to do sth; as instructed; follow instructions. Trang trọng hơn 'tell'; dùng nhiều trong văn bản hướng dẫn TOEIC.", f: "instruct (v), instruction (n), instructor (n), instructive (adj), instructional (adj)" },
  "intelligence": { m: "inter (giữa) + legere (chọn, đọc) → chọn đúng giữa các khả năng → trí thông minh.", e: "Sai: an intelligence student → Đúng: an intelligent student (intelligent là tính từ, intelligence là danh từ).", u: "artificial intelligence (AI); emotional intelligence; intelligence agency (tình báo). Chủ đề công nghệ phổ biến trong Task 2.", f: "intelligence (n), intelligent (adj), intelligently (adv), intellect (n), intellectual (adj)" },
  "interval": { m: "inter (giữa) + vallum (bờ tường) → khoảng giữa hai bức tường → khoảng cách, quãng nghỉ.", e: "Sai: nhấn âm 2 in-TER-val → Đúng: nhấn âm 1: IN-ter-val /ˈɪntəvl/.", u: "at regular intervals; at intervals of five minutes; a short interval. Trong UK, 'interval' còn là giờ giải lao ở rạp hát.", f: "interval (n)" },
  "lecture": { m: "Gốc legere (đọc, như legible) → ngày xưa giảng viên đọc bài cho sinh viên nghe → bài giảng.", e: "Sai: lecture about the students → Đúng: give a lecture on economics; lecture sb (động từ) còn có nghĩa thuyết giáo, mắng.", u: "give/deliver/attend a lecture on sth; lecture hall/theatre. Hay xuất hiện trong IELTS Listening phần 4.", f: "lecture (n/v), lecturer (n)" },
  "migrate": { m: "Gốc migrare (chuyển chỗ) → chim di trú, người di cư; im- (vào) thành immigrate.", e: "Sai: dùng migrate, emigrate, immigrate như nhau → Đúng: emigrate from (rời nước), immigrate to (đến nước mới), migrate chung chung hoặc theo mùa.", u: "migrate to cities; rural-urban migration; migrant workers. Chủ đề đô thị hóa rất hay gặp trong Task 2.", f: "migrate (v), migration (n), migrant (n/adj), migratory (adj)" },
  "minimum": { m: "Gốc minimus (nhỏ nhất, như mini, minor) → mức nhỏ nhất → tối thiểu.", e: "Sai: minimum salary cho lương tối thiểu theo luật → Đúng: minimum wage (cụm cố định).", u: "minimum wage/requirement/age; keep sth to a minimum; a minimum of 3 years. Hay gặp trong Task 2 và TOEIC tuyển dụng.", f: "minimum (n/adj), minimal (adj), minimize/minimise (v), minimally (adv)" },
  "ministry": { m: "minister (bộ trưởng, gốc minor: người phục vụ) + -ry → nơi bộ trưởng làm việc → bộ.", e: "Sai: the ministry of education (tên riêng viết thường) → Đúng: the Ministry of Education (viết hoa tên cơ quan).", u: "the Ministry of Health/Finance/Education; government ministry. Dùng khi nói về chính phủ Anh, Việt Nam; Mỹ dùng Department.", f: "ministry (n), minister (n), ministerial (adj)" },
  "motive": { m: "Gốc movere (chuyển động, như move, motion) → điều làm ta chuyển động → động cơ.", e: "Sai: motive to the crime → Đúng: motive for the crime (motive for sth); đừng nhầm với motivation (sự có động lực).", u: "a motive for murder; hidden/ulterior motive; profit motive. Mang sắc thái lý do ẩn sau hành động, thường trong ngữ cảnh điều tra, phân tích.", f: "motive (n), motivate (v), motivation (n), motivated (adj)" },
  "neutral": { m: "ne- (không) + uter (một trong hai) → không theo bên nào → trung lập.", e: "Sai: a neutrality country → Đúng: a neutral country (neutral là tính từ; neutrality là danh từ).", u: "remain/stay neutral; neutral position/tone; carbon neutral. Trong Writing có thể nói 'take a neutral stance'.", f: "neutral (adj/n), neutrality (n), neutralize/neutralise (v)" },
  "nevertheless": { m: "never + the + less → không vì thế mà kém đi → tuy nhiên, dù vậy.", e: "Sai: Nevertheless he tried, he failed → Đúng: He tried. Nevertheless, he failed (nevertheless là trạng từ nối, không phải liên từ như although).", u: "Từ nối đối lập trang trọng, đồng nghĩa nonetheless, however. Đặt đầu câu, sau dấu chấm hoặc chấm phẩy, theo sau là dấu phẩy.", f: "nevertheless (adv), nonetheless (adv)" },
  "overseas": { m: "over (qua) + seas (biển) → vượt biển → ở nước ngoài.", e: "Sai: go to overseas → Đúng: go overseas (overseas làm trạng từ không cần to, giống go abroad).", u: "study/work/travel overseas; overseas students/markets. Thay 'abroad' hoặc 'foreign' trong Writing để đa dạng từ.", f: "overseas (adj/adv)" },
  "precede": { m: "pre- (trước) + cedere (đi, như proceed) → đi trước → đứng trước, xảy ra trước.", e: "Sai: nhầm precede với proceed → Đúng: precede = xảy ra trước; proceed = tiếp tục. Chính tả: precede (-cede), proceed (-ceed).", u: "be preceded by; the preceding year; take precedence over (được ưu tiên hơn). Hay dùng trong Task 1 khi so sánh các giai đoạn.", f: "precede (v), preceding (adj), precedent (n), precedence (n)" },
  "presume": { m: "pre- (trước) + sumere (lấy, như assume, consume) → lấy làm đúng từ trước → cho là.", e: "Sai: nhầm presume với assume trong mọi ngữ cảnh → Đúng: presume dựa trên khả năng cao; 'presumed innocent' là được coi vô tội đến khi có bằng chứng.", u: "presume that...; be presumed dead/innocent; I presume so. Mang sắc thái giả định có cơ sở, trang trọng hơn 'suppose'.", f: "presume (v), presumption (n), presumably (adv), presumptuous (adj)" },
  "rational": { m: "Gốc ratio (lý trí, sự tính toán, như reason) → dựa trên lý trí → hợp lý.", e: "Sai: nhầm rational với rationale → Đúng: a rational decision (adj); the rationale for the decision (n: lý do căn bản).", u: "rational decision/choice/argument; rational thinking. Trái nghĩa irrational. Phù hợp Task 2 khi bàn về lập luận, quyết định.", f: "rational (adj), rationality (n), rationally (adv), rationale (n), irrational (adj)" },
  "recover": { m: "re- (lại) + capere (lấy) → lấy lại → phục hồi; giống 'cover' nên dễ nhớ.", e: "Sai: recover the illness → Đúng: recover from the illness (hồi phục sau bệnh dùng from).", u: "recover from an illness/a recession; economic recovery; recover costs/data. Dùng nhiều trong kinh tế TOEIC và Task 1.", f: "recover (v), recovery (n), recoverable (adj)" },
  "reveal": { m: "re- (ngược lại) + velum (tấm màn, như veil) → kéo màn ra → tiết lộ, cho thấy.", e: "Sai: The survey reveals that people is... → Đúng: The survey reveals that people are... (people là số nhiều); danh từ là revelation, không phải revealation.", u: "reveal the truth/a secret; research reveals that...; the figures reveal. Dùng thay 'show' trong Task 1 và 2.", f: "reveal (v), revelation (n), revealing (adj)" },
  "scope": { m: "Gốc Hy Lạp skopein (nhìn, như telescope, microscope) → tầm nhìn bao quát → phạm vi.", e: "Sai: a big scope → Đúng: a broad/wide/narrow scope (scope đi với broad, wide, limited).", u: "the scope of the study/project; beyond the scope of; scope for improvement (cơ hội cải thiện). Văn phong học thuật.", f: "scope (n/v)" },
  "subsidy": { m: "sub- (dưới) + sedere (ngồi) → đội quân ngồi sau hỗ trợ → trợ cấp, hỗ trợ.", e: "Sai: The government subsidy farmers → Đúng: The government subsidizes farmers (subsidy là danh từ, subsidize/subsidise là động từ).", u: "government/state subsidies; subsidies for/on sth; heavily subsidized. Rất hay dùng trong Task 2 về giao thông công cộng, nông nghiệp.", f: "subsidy (n), subsidize/subsidise (v), subsidized (adj)" },
  "tape": { m: "Nghĩ 'băng keo' gần âm 'tape' → băng dính; băng ghi âm cũng là cuộn băng.", e: "Sai: dùng 'tape' cho băng y tế quấn vết thương → Đúng: bandage; tape là băng dính hoặc băng ghi âm, ghi hình.", u: "adhesive/sticky tape; tape recording; red tape (thủ tục rườm rà). 'Red tape' là thành ngữ rất hữu ích trong Task 2 về chính phủ.", f: "tape (n/v), taped (adj)" },
  "trace": { m: "Gốc trahere (kéo, như tractor, track) → vết kéo để lại → dấu vết, lần theo.", e: "Sai: trace from the history → Đúng: trace sth back to sth (lần ngược về nguồn gốc): The tradition can be traced back to the 15th century.", u: "trace the origin/history of; trace back to; without trace; traces of chemicals. Danh từ trace là dấu vết, lượng rất nhỏ.", f: "trace (v/n), traceable (adj), tracing (n)" },
  "transform": { m: "trans- (chuyển qua) + form (hình dạng) → chuyển sang hình dạng khác → biến đổi.", e: "Sai: transform to a city → Đúng: transform into a city (transform A into B).", u: "transform sth into sth; dramatic transformation; digital transformation. Mạnh hơn 'change'; dùng trong Task 1 bản đồ khi mô tả thay đổi lớn.", f: "transform (v), transformation (n), transformative (adj), transformer (n)" },
  "transport": { m: "trans- (qua) + portare (mang, như export, portable) → mang từ nơi này qua nơi khác → vận tải.", e: "Sai: public transports → Đúng: public transport (UK) / transportation (US), không đếm được. Danh từ nhấn âm 1 TRANS-port, động từ nhấn âm 2.", u: "public transport; means of transport; transport links. Chủ đề giao thông rất phổ biến trong IELTS Task 2 và TOEIC.", f: "transport (n/v), transportation (n), transporter (n)" },
  "underlie": { m: "under (bên dưới) + lie (nằm) → nằm bên dưới → làm nền tảng, là nguyên nhân sâu xa.", e: "Sai: The underlie reason → Đúng: The underlying reason (dạng tính từ là underlying, hay dùng hơn động từ underlie).", u: "underlying causes/problems/assumptions; factors that underlie the decision. Văn phong học thuật, hữu ích khi phân tích nguyên nhân trong Task 2.", f: "underlie (v), underlying (adj)" },
  "utilise": { m: "Gốc uti (dùng, như utility, use) + -ise (làm) → đưa vào sử dụng → tận dụng.", e: "Sai: utilize trong bài viết theo chuẩn Anh → Đúng: utilise (UK) / utilize (US); giữ thống nhất một chuẩn chính tả.", u: "utilise resources/space/technology effectively; fully utilised. Trang trọng, nhấn mạnh dùng hiệu quả; trong văn nói nên dùng 'use'.", f: "utilise/utilize (v), utilisation/utilization (n), utility (n)" },
  "adapt": { m: "ad- (hướng tới) + apt (phù hợp, như 'apt' trong aptitude) → làm cho phù hợp với điều kiện mới.", e: "Sai: adapt with the new environment → Đúng: adapt to the new environment. Đừng nhầm adapt (thích nghi) với adopt (nhận nuôi, áp dụng).", u: "adapt to change/conditions, adapt a method for…, well adapted to. Hay dùng trong IELTS Writing về môi trường, công nghệ, di cư.", f: "adaptation (n), adaptable (adj), adaptability (n), adaptive (adj), adapter (n)" },
  "adult": { m: "Gốc Latin adultus = đã lớn lên (cùng gốc với adolescent: đang lớn) → người đã trưởng thành.", e: "Sai: adults people → Đúng: adults / adult people (adult làm tính từ không thêm s). Anh-Mỹ hay nhấn âm 2: a-DULT.", u: "young adults, adult learners, adult education, in adulthood. Trang trọng hơn grown-up; dùng nhiều trong bài về giáo dục, sức khỏe.", f: "adulthood (n), adult (adj)" },
  "advocate": { m: "ad- (hướng tới) + voc (giọng nói, như voice, vocal) → cất tiếng nói thay cho ai đó, ủng hộ.", e: "Sai: advocate about reform → Đúng: advocate reform (động từ, không cần about). Phát âm: động từ -cate /keɪt/, danh từ -cate /kət/.", u: "advocate a policy/an approach, a strong advocate of/for sth. Trang trọng, hợp IELTS Writing khi nêu quan điểm: 'Many experts advocate…'.", f: "advocate (n), advocacy (n)" },
  "aid": { m: "Liên hệ first aid (sơ cứu), hearing aid (máy trợ thính) → aid là sự trợ giúp, viện trợ.", e: "Sai: many aids to poor countries → Đúng: much aid to poor countries (aid nghĩa viện trợ là danh từ không đếm được).", u: "foreign/humanitarian/financial aid, provide aid, with the aid of. Trang trọng hơn help; phổ biến trong bài về nước đang phát triển.", f: "aid (v), aide (n: trợ lý)" },
  "channel": { m: "Cùng gốc với canal (kênh đào) → đường dẫn nước, rồi mở rộng thành kênh truyền hình, kênh thông tin.", e: "Sai: watch on channel VTV1 → Đúng: watch it on VTV1 / on channel 1. Phân biệt channel (kênh) với chanel (thương hiệu), đừng viết sai chính tả.", u: "communication channels, distribution channel, through official channels, channel resources into… (động từ: dồn vào). Hay gặp trong TOEIC marketing.", f: "channel (v), channelled/channeled (adj)" },
  "chemical": { m: "chem- (hóa học, như chemistry) + -ical (tính từ/danh từ) → chất hóa học.", e: "Sai: use chemistry to kill pests → Đúng: use chemicals to kill pests. chemistry là môn hóa học, chemical là hóa chất (đếm được).", u: "toxic/harmful chemicals, chemical fertilisers, chemical reaction. Thường dùng trong bài về môi trường, nông nghiệp, sức khỏe.", f: "chemistry (n), chemist (n), chemically (adv)" },
  "classic": { m: "class (hạng nhất) + -ic → thuộc hàng mẫu mực, kinh điển, điển hình.", e: "Sai: classic music → Đúng: classical music. classic = điển hình, kinh điển; classical = thuộc trường phái cổ điển.", u: "a classic example of…, a classic case, classic novel. Câu 'This is a classic example of…' rất hữu ích khi đưa ví dụ trong IELTS.", f: "classic (n), classical (adj), classics (n)" },
  "comprehensive": { m: "com- (toàn bộ) + prehend (nắm bắt) → nắm bắt mọi thứ → toàn diện, bao quát.", e: "Nhầm với comprehensible (dễ hiểu). Sai: a comprehensible review of all data → Đúng: a comprehensive review of all data.", u: "comprehensive study/survey/coverage/insurance, a comprehensive range of. Trang trọng, hợp IELTS Writing và báo cáo TOEIC.", f: "comprehensively (adv), comprehensiveness (n), comprehend (v), comprehension (n)" },
  "comprise": { m: "com- (cùng nhau) + prise (nắm, như prison) → nắm giữ các phần cùng nhau → bao gồm.", e: "Sai: The team is comprised by five people → Đúng: The team comprises five people / consists of five people. Tránh 'comprise of'.", u: "Rất hay dùng mô tả biểu đồ IELTS Task 1: 'Women comprise 40% of the workforce.' Trang trọng hơn include.", f: "comprising (prep/adj)" },
  "confirm": { m: "con- (hoàn toàn) + firm (chắc chắn) → làm cho chắc chắn hoàn toàn → xác nhận.", e: "Sai: confirm about the booking → Đúng: confirm the booking (confirm là ngoại động từ, không cần about).", u: "confirm a reservation/appointment/order, confirm that…, written confirmation. Rất phổ biến trong email TOEIC.", f: "confirmation (n), confirmed (adj)" },
  "contrary": { m: "contra- (ngược lại, như contrast, contradict) → trái ngược.", e: "Sai: On the contrary, cities are crowded (khi chỉ so sánh) → Đúng: In contrast, cities are crowded. 'On the contrary' dùng để bác bỏ ý trước.", u: "contrary to popular belief, contrary to expectations, evidence to the contrary. Hữu ích khi phản biện trong IELTS Writing.", f: "contrary (n), contrarily (adv), contrarian (n)" },
  "convert": { m: "con- (hoàn toàn) + vert (xoay, như reverse, vertical) → xoay hẳn sang dạng khác → chuyển đổi.", e: "Sai: convert sth to become sth → Đúng: convert sth into/to sth. Nhấn âm: động từ con-VERT, danh từ CON-vert (người cải đạo).", u: "convert energy/currency, convert A into B, convert a building into flats. Dùng nhiều khi mô tả quy trình (IELTS Task 1).", f: "conversion (n), convertible (adj, n), converter (n)" },
  "couple": { m: "Gốc Latin copula = sợi dây buộc (như copulative) → hai thứ được buộc với nhau → cặp đôi; a couple of = vài.", e: "Sai: a couple of time → Đúng: a couple of times (danh từ theo sau ở số nhiều). Trong văn trang trọng nên dùng 'a few'.", u: "a couple of days/weeks, a married couple, coupled with (kết hợp với). 'Coupled with…' rất hay trong IELTS Writing.", f: "couple (v), coupled (adj), coupling (n)" },
  "decade": { m: "deca- (mười, như decimal) → khoảng thời gian mười năm.", e: "Sai: in the last decade years → Đúng: in the last decade / over the past ten years. Nhấn âm 1: DE-cade.", u: "over the past/last decade, for decades, in recent decades. Rất phổ biến khi mô tả xu hướng trong IELTS Task 1.", f: "decadal (adj)" },
  "definite": { m: "de- (hoàn toàn) + fin (giới hạn, như finish, finite) → có giới hạn rõ ràng → xác định, chắc chắn.", e: "Lỗi chính tả: definate → Đúng: definite, definitely. Đừng nhầm với definitive (dứt khoát, cuối cùng).", u: "a definite answer/plan/improvement, definitely (chắc chắn). Trong IELTS Speaking 'definitely' rất tự nhiên.", f: "definitely (adv), define (v), definition (n), definitive (adj)" },
  "deny": { m: "de- (hoàn toàn) + ny (nói không, như negative) → nói không → phủ nhận, từ chối.", e: "Sai: He denied to take the money → Đúng: He denied taking the money (deny + V-ing). Muốn 'từ chối làm' dùng refuse to.", u: "deny the allegations/charges, deny sb access to, there is no denying that… Trang trọng; hay gặp trong tin tức.", f: "denial (n), undeniable (adj), undeniably (adv)" },
  "differentiate": { m: "different (khác) + -iate (làm cho) → làm rõ sự khác biệt → phân biệt.", e: "Sai: differentiate A with B → Đúng: differentiate A from B / differentiate between A and B. Nhấn âm 3: dif-fe-REN-ti-ate.", u: "differentiate between fact and opinion, differentiate a product from competitors. Trang trọng hơn tell apart; hay dùng trong kinh doanh, giáo dục.", f: "differentiation (n), different (adj), difference (n), differ (v)" },
  "dispose": { m: "dis- (rời xa) + pose (đặt, như position) → đặt ra xa → vứt bỏ, xử lý.", e: "Sai: dispose the rubbish → Đúng: dispose of the rubbish (luôn đi với of khi nghĩa là vứt bỏ).", u: "dispose of waste safely, disposable income, disposable cups. Hay gặp trong bài IELTS về rác thải, môi trường.", f: "disposal (n), disposable (adj), disposition (n)" },
  "dynamic": { m: "Gốc Hy Lạp dynamis = sức mạnh (như dynamite, dynamo) → tràn đầy năng lượng, năng động.", e: "Sai: She is very dynamics → Đúng: She is very dynamic. dynamics (n) là động lực học / sự tương tác.", u: "a dynamic economy/city/leader, a dynamic environment, group dynamics. Mang sắc thái tích cực; phổ biến trong CV và TOEIC.", f: "dynamics (n), dynamically (adv), dynamism (n)" },
  "eliminate": { m: "e- (ra ngoài) + limin (ngưỡng cửa, như preliminary) → đẩy ra khỏi cửa → loại bỏ.", e: "Sai: eliminate out the risk → Đúng: eliminate the risk (không cần out). Nhấn âm 2: e-LIM-i-nate.", u: "eliminate poverty/waste/the need for, completely eliminate. Mạnh hơn reduce; dùng cẩn thận vì nghĩa là loại bỏ hoàn toàn.", f: "elimination (n)" },
  "empirical": { m: "Gốc Hy Lạp empeiria = kinh nghiệm → dựa trên quan sát, kinh nghiệm thực tế → thực nghiệm.", e: "Đừng nhầm với imperial (đế quốc). Sai: empiric data → Đúng: empirical data/evidence. Nhấn âm 2: em-PI-ri-cal.", u: "empirical evidence/research/study, empirically tested. Rất học thuật; dùng trong IELTS Writing khi bàn về nghiên cứu khoa học.", f: "empirically (adv), empiricism (n), empiricist (n)" },
  "equip": { m: "Liên hệ equipment (thiết bị) → equip là cung cấp thiết bị, trang bị.", e: "Sai: equipments → Đúng: equipment (không đếm được). Sai: equip students for skills → Đúng: equip students with skills.", u: "equip sb with skills/knowledge, well-equipped, be equipped to do sth. Hay dùng trong bài IELTS về giáo dục.", f: "equipment (n), equipped (adj)" },
  "extract": { m: "ex- (ra ngoài) + tract (kéo, như tractor, attract) → kéo ra ngoài → chiết xuất, khai thác.", e: "Nhấn âm: động từ ex-TRACT, danh từ EX-tract (đoạn trích, chiết xuất). Sai: extract oil out from → Đúng: extract oil from.", u: "extract minerals/oil/data/information from, an extract from a book. Dùng trong bài về tài nguyên, quy trình sản xuất.", f: "extraction (n), extract (n), extractive (adj)" },
  "file": { m: "Liên hệ file trên máy tính (tệp) và file trong văn phòng (hồ sơ) → nơi lưu giữ tài liệu.", e: "Sai: send me the files via email attach → Đúng: send me the files as attachments. Động từ file đi với: file a complaint, không phải make a file complaint.", u: "keep a file on sb, on file, file a complaint/report/lawsuit (động từ: nộp). Rất hay gặp trong TOEIC văn phòng.", f: "file (v), filing (n)" },
  "finite": { m: "fin (giới hạn, kết thúc, như finish, final) → có giới hạn → hữu hạn; ngược lại là infinite.", e: "Phát âm: FAI-nait /ˈfaɪnaɪt/, nhưng infinite đọc /ˈɪnfɪnət/. Đừng đọc 'fi-nít'.", u: "finite resources, a finite number of. Rất hữu ích trong IELTS Writing về tài nguyên thiên nhiên: 'Fossil fuels are finite.'", f: "infinite (adj), finitely (adv)" },
  "foundation": { m: "found (thành lập, như founder) + -ation → nền móng để xây dựng; tổ chức được lập ra (quỹ).", e: "Sai: The foundation of the company was in 1990 → tự nhiên hơn: The company was founded in 1990. found (lập) khác find–found (tìm).", u: "lay the foundation(s) for, a solid foundation, a charitable foundation. 'Lay the foundation for' rất hay trong IELTS.", f: "found (v), founder (n), fundamental (adj)" },
  "globe": { m: "Liên hệ quả địa cầu tròn → globe; global = toàn cầu, globalisation = toàn cầu hóa.", e: "Sai: all over the globe countries → Đúng: all over the globe / around the globe. Đừng nhầm globe (n) với global (adj).", u: "around/across the globe, the global economy, global warming. 'Across the globe' thay cho 'in the world' để đa dạng từ.", f: "global (adj), globally (adv), globalisation (n), globalise (v)" },
  "grade": { m: "Gốc Latin gradus = bước, bậc (như gradual, graduate) → bậc, cấp độ, điểm số.", e: "Sai: I got a high mark of grade A in my score → Đúng: I got an A / got a high grade. Mỹ: grade 5 = lớp 5.", u: "get good grades, high-grade materials, grade papers (chấm bài). grade phổ biến kiểu Mỹ, mark kiểu Anh.", f: "grade (v), gradual (adj), graduate (v, n), gradation (n)" },
  "guarantee": { m: "Cùng gốc với warranty (bảo hành) → cam kết chắc chắn → đảm bảo.", e: "Lỗi chính tả: garantee/guarantie → Đúng: guarantee. Nhấn âm cuối: gua-ran-TEE.", u: "guarantee success/quality, a money-back guarantee, there is no guarantee that… Rất phổ biến trong TOEIC mua bán, bảo hành.", f: "guarantee (n), guaranteed (adj), guarantor (n)" },
  "hierarchy": { m: "hier- (thiêng liêng, như hieroglyph) + archy (cai trị, như monarchy) → thứ bậc trong giáo hội → hệ thống cấp bậc.", e: "Phát âm khó: HAI-ơ-raa-ki /ˈhaɪərɑːki/, nhấn âm 1. Lỗi chính tả: hierachy → Đúng: hierarchy.", u: "a social/corporate hierarchy, a strict hierarchy, at the top of the hierarchy. Hay dùng trong bài về nơi làm việc, xã hội.", f: "hierarchical (adj), hierarchically (adv)" },
  "identical": { m: "ident (giống, như identity) + -ical → giống hệt nhau; identical twins = sinh đôi cùng trứng.", e: "Sai: identical with each other như similar with → Đúng: identical to the original (thường đi với to). Không nói very identical, dùng almost identical.", u: "identical to, almost/virtually identical, identical twins. Mạnh hơn similar; dùng khi so sánh số liệu trong IELTS Task 1.", f: "identically (adv), identity (n), identify (v)" },
  "ideology": { m: "ideo (ý tưởng, như idea) + -logy (học thuyết) → học thuyết về ý tưởng → hệ tư tưởng.", e: "Phát âm: ai-đi-O-lơ-gi, nhấn âm 3, âm đầu đọc /aɪ/. Đừng nhầm với idealism (chủ nghĩa lý tưởng).", u: "political/religious ideology, a dominant ideology. Mang tính học thuật, đôi khi hơi tiêu cực; dùng trong bài về chính trị, xã hội.", f: "ideological (adj), ideologically (adv), ideologue (n)" },
  "infer": { m: "in- (vào) + fer (mang, như transfer) → mang thông tin vào đầu để rút ra kết luận → suy luận.", e: "Sai: The writer infers that… (khi ý là ngụ ý) → Đúng: The writer implies that…; người đọc mới infer. Nhấn âm 2: in-FER.", u: "infer sth from evidence/data, it can be inferred that… Rất hay trong IELTS Reading và khi phân tích số liệu.", f: "inference (n), inferential (adj)" },
  "innovate": { m: "in- (vào) + nov (mới, như novel, renovate) → đưa cái mới vào → đổi mới, cải tiến.", e: "Sai: innovate the system (kém tự nhiên) → Đúng: innovate in the field / modernise the system. Nhấn âm 1: IN-no-vate.", u: "innovate constantly, technological innovation, innovative solutions/ideas. Từ yêu thích trong TOEIC kinh doanh và IELTS về công nghệ.", f: "innovation (n), innovative (adj), innovator (n)" },
  "insert": { m: "in- (vào) + sert (nối, đặt, như series) → đặt vào giữa → chèn vào.", e: "Sai: insert the card in into the slot → Đúng: insert the card into the slot. Nhấn âm: động từ in-SERT, danh từ IN-sert (tờ rời).", u: "insert a coin/card/key, insert a clause/paragraph into a document. Hay gặp trong hướng dẫn sử dụng và TOEIC văn phòng.", f: "insertion (n), insert (n)" },
  "intervene": { m: "inter- (giữa, như international) + ven (đến, như convene, event) → đến chen vào giữa → can thiệp.", e: "Sai: intervene the conflict → Đúng: intervene in the conflict (cần in). Lỗi chính tả: intervine → Đúng: intervene.", u: "the government should intervene in…, intervene to prevent, military intervention. Rất hay trong IELTS Writing về vai trò chính phủ.", f: "intervention (n), interventionist (adj, n)" },
  "isolate": { m: "Gốc Ý isola = hòn đảo (như island, isle) → biến thành hòn đảo riêng → cô lập, tách riêng.", e: "Sai: feel isolate → Đúng: feel isolated (dùng tính từ). Nhấn âm 1: AI-so-late /ˈaɪsəleɪt/.", u: "feel socially isolated, isolate a virus, in isolation, an isolated case. Dùng trong bài về người già, mạng xã hội, dịch bệnh.", f: "isolation (n), isolated (adj)" },
  "media": { m: "Số nhiều của medium (phương tiện ở giữa, như medium size) → các phương tiện truyền thông.", e: "Sai: medias → Đúng: the media (đã là số nhiều). Có thể dùng động từ số ít hoặc nhiều: The media is/are…", u: "the mass media, social media, media coverage, in the media. Chủ đề rất phổ biến trong IELTS Writing và Speaking.", f: "medium (n), mediate (v), multimedia (n)" },
  "mode": { m: "Gốc Latin modus = cách thức (như model, modify) → phương thức, chế độ; liên hệ 'airplane mode'.", e: "Đừng nhầm mode (phương thức) với mood (tâm trạng). Sai: I'm in a good mode → Đúng: I'm in a good mood.", u: "mode of transport/communication, in silent mode, a mode of thinking. 'Mode of transport' rất phổ biến trong IELTS.", f: "modal (adj), modality (n)" },
  "paradigm": { m: "para- (bên cạnh) + deigma (ví dụ) → mẫu đặt bên cạnh để so sánh → mô hình, hệ hình.", e: "Phát âm: PA-ra-đaim /ˈpærədaɪm/, chữ g câm. Đừng đọc 'pa-ra-đi-gơm'.", u: "a paradigm shift (sự thay đổi căn bản), a new paradigm. Rất học thuật; dùng ít và chính xác trong IELTS Writing để tránh khoa trương.", f: "paradigmatic (adj)" },
  "phenomenon": { m: "Gốc Hy Lạp phainein = hiện ra, xuất hiện → điều hiện ra mà ta quan sát được → hiện tượng.", e: "Sai: these phenomenon / a phenomena → Đúng: this phenomenon, these phenomena (số nhiều bất quy tắc). Nhấn âm 2: phe-NOM-e-non.", u: "a natural/social/global phenomenon, a growing phenomenon. Dùng mở bài IELTS: 'This phenomenon has become increasingly common.'", f: "phenomena (n pl), phenomenal (adj), phenomenally (adv)" },
  "priority": { m: "prior (trước, như prior to) + -ity → điều được đặt lên trước → ưu tiên.", e: "Sai: give priority for education → Đúng: give priority to education. Sai: the most top priority → Đúng: the top priority.", u: "a top/high priority, set priorities, take priority over, prioritise sth. Hay dùng trong IELTS về ngân sách chính phủ.", f: "prioritise/prioritize (v), prior (adj), prioritisation (n)" },
  "prohibit": { m: "pro- (phía trước) + hibit (giữ, như exhibit) → giữ lại phía trước, không cho làm → cấm.", e: "Sai: prohibit people to smoke → Đúng: prohibit people from smoking (prohibit sb from V-ing). Nhấn âm 2: pro-HI-bit.", u: "be strictly prohibited, prohibit sb from doing sth. Trang trọng hơn ban; hay gặp trong biển báo, quy định TOEIC.", f: "prohibition (n), prohibitive (adj), prohibited (adj)" },
  "publication": { m: "public (công chúng) + -ation → đưa ra công chúng → sự xuất bản, ấn phẩm.", e: "Đừng nhầm publication (xuất bản) với publicity (sự quảng bá). Sai: the publication of the new product → Đúng: the publicity for the new product.", u: "the publication of a report, academic publications, at the time of publication. Hay gặp trong TOEIC và văn học thuật.", f: "publish (v), publisher (n), public (adj, n)" },
  "quote": { m: "Gốc Latin quotus = bao nhiêu, đánh số → ghi lại chính xác lời người khác → trích dẫn; cũng là báo giá.", e: "Sai: according to the quotation of the expert, he said… → Đúng: as the expert said / to quote the expert… Danh từ trang trọng: quotation.", u: "quote sb/a source, quote a price (báo giá), in quotes. Trong TOEIC 'quote' thường là báo giá.", f: "quotation (n), quote (n), quotable (adj)" },
  "release": { m: "re- (trở lại) + lease (thả lỏng, cùng gốc với relax) → thả ra → thải ra, phát hành.", e: "Sai: release out gas → Đúng: release gas into the air. Lỗi chính tả: realease → Đúng: release.", u: "release emissions/carbon dioxide, release a film/product, press release. Dùng trong bài môi trường (IELTS) và marketing (TOEIC).", f: "release (n)" },
  "reverse": { m: "re- (ngược lại) + vers (xoay, như convert, version) → xoay ngược lại → đảo ngược.", e: "Sai: The trend reversed back → Đúng: The trend reversed / was reversed (không cần back). Đừng nhầm reverse với inverse.", u: "reverse a trend/decision/damage, in reverse order, the reverse is true. Hữu ích khi mô tả biểu đồ IELTS Task 1.", f: "reversal (n), reverse (n, adj), reversible (adj), irreversible (adj)" },
  "simulate": { m: "simil (giống, như similar) + -ate → làm cho giống thật → mô phỏng.", e: "Đừng nhầm simulate (mô phỏng) với stimulate (kích thích). Nhấn âm 1: SIM-u-late.", u: "simulate real-life conditions, computer simulation, flight simulator. Dùng trong bài về công nghệ, đào tạo, giáo dục.", f: "simulation (n), simulator (n), simulated (adj)" },
  "sole": { m: "Gốc Latin solus = một mình (như solo, solitary) → duy nhất.", e: "Sai: the sole of reason → Đúng: the sole reason (sole là tính từ đứng trước danh từ). Đồng âm với soul (linh hồn).", u: "the sole purpose/reason/responsibility, sole owner, solely (chỉ, duy nhất). Trang trọng hơn only; hay gặp trong TOEIC hợp đồng.", f: "solely (adv)" },
  "somewhat": { m: "some (một ít) + what → ở mức độ nào đó → hơi, phần nào.", e: "Sai: The price rose some what → Đúng: rose somewhat (viết liền). Sai: somewhat of reason → Đúng: somewhat reasonable.", u: "somewhat surprising/different, decline somewhat. Trang trọng hơn a bit; giúp nói giảm nhẹ trong IELTS Writing.", f: "Không có dạng khác (trạng từ cố định)" },
  "submit": { m: "sub- (dưới) + mit (gửi, như transmit) → gửi lên người cấp trên → nộp, đệ trình.", e: "Sai: submit the report for the manager → Đúng: submit the report to the manager. Nhấn âm 2: sub-MIT.", u: "submit an application/assignment/proposal, submit to authority (phục tùng). Rất phổ biến trong email TOEIC.", f: "submission (n), submissive (adj)" },
  "successor": { m: "success (cùng gốc succeed: đi tiếp sau) + -or (người) → người đi tiếp theo → người kế nhiệm.", e: "Đừng hiểu nhầm là 'người thành công'. Sai: He is a successor in business → Đúng: He is successful in business. successor to/of sb.", u: "a successor to the CEO, a worthy successor, name a successor. Ngược nghĩa với predecessor; hay gặp trong TOEIC nhân sự.", f: "succeed (v), succession (n), successive (adj)" },
  "survive": { m: "sur- (vượt lên) + viv (sống, như vivid, revive) → sống vượt qua → sống sót, tồn tại.", e: "Sai: survive from the accident → Đúng: survive the accident (không cần from). Nhấn âm 2: sur-VIVE.", u: "survive a crisis/disaster, struggle to survive, survival rate. Dùng trong bài về kinh doanh nhỏ, động vật hoang dã.", f: "survival (n), survivor (n), surviving (adj)" },
  "thesis": { m: "Gốc Hy Lạp thesis = sự đặt ra → luận điểm được đặt ra; như hypothesis (giả thuyết), synthesis.", e: "Sai: two thesis → Đúng: two theses /ˈθiːsiːz/ (số nhiều bất quy tắc). Âm th đọc /θ/, không đọc 't'.", u: "write a thesis, a doctoral/master's thesis, thesis statement (câu luận điểm). Thesis statement là câu then chốt trong mở bài IELTS.", f: "theses (n pl), hypothesis (n)" },
  "topic": { m: "Gốc Hy Lạp topos = nơi chốn → 'nơi' mà cuộc bàn luận hướng tới → chủ đề.", e: "Sai: talk about the topic about health → Đúng: talk about the topic of health. topical (adj) = mang tính thời sự, không phải 'thuộc chủ đề'.", u: "a controversial/hot topic, discuss a topic, off topic. Cực kỳ phổ biến trong IELTS Speaking Part 2 và Writing.", f: "topical (adj), topically (adv)" },
  "transmit": { m: "trans- (qua) + mit (gửi, như submit, emit) → gửi qua → truyền.", e: "Sai: transmit diseases for humans → Đúng: transmit diseases to humans. Nhấn âm 2: trans-MIT.", u: "transmit data/signals/a disease, sexually transmitted. Dùng trong bài về công nghệ, y tế, dịch bệnh.", f: "transmission (n), transmitter (n), transmissible (adj)" },
  "ultimate": { m: "ultim (cuối cùng, như ultimatum) + -ate → ở điểm cuối, xa nhất → cuối cùng, tối thượng.", e: "Đừng nhầm ultimate (cuối cùng, tối thượng) với latest (mới nhất). Sai: the ultimate news → Đúng: the latest news.", u: "the ultimate goal/aim/responsibility, ultimately (rốt cuộc). 'Ultimately,…' rất hay để kết đoạn trong IELTS Writing.", f: "ultimately (adv), ultimatum (n)" },
  "unique": { m: "uni- (một, như uniform, unit) + -que → chỉ có một → độc nhất.", e: "Sai: a very unique design (nhiều giáo viên coi là thừa) → Đúng: a unique design / a truly unique design. Nhấn âm 2: u-NIQUE.", u: "unique opportunity/feature/culture, unique to sb/sth. Phổ biến trong IELTS Speaking khi mô tả địa điểm, truyền thống.", f: "uniquely (adv), uniqueness (n)" },
  "visible": { m: "vis (nhìn, như vision, visit) + -ible (có thể) → có thể nhìn thấy; ngược lại là invisible.", e: "Lỗi chính tả: visable → Đúng: visible (đuôi -ible, không phải -able).", u: "clearly/highly visible, visible to the naked eye, a visible improvement. Dùng ẩn dụ: 'visible results' trong IELTS Writing.", f: "visibility (n), visibly (adv), invisible (adj), vision (n)" },
  "voluntary": { m: "volunt (ý muốn, như volunteer) + -ary → làm theo ý muốn của mình → tự nguyện.", e: "Sai: She works voluntary at the hospital → Đúng: She works voluntarily / volunteers at the hospital. Nhấn âm 1: VOL-un-tar-y.", u: "voluntary work, on a voluntary basis, voluntary organisations. Đối lập compulsory; hay dùng trong IELTS về giáo dục, cộng đồng.", f: "volunteer (n, v), voluntarily (adv)" },
  "abandon": { m: "Gốc Pháp 'à bandon' (giao cho người khác định đoạt) → buông tay, bỏ mặc hoàn toàn.", e: "Sai: abandon to smoke → Đúng: give up smoking (abandon thường đi với danh từ: abandon a plan/an idea).", u: "Dùng cho kế hoạch, ý tưởng, nơi chốn: abandon a project, abandon hope, abandoned buildings. Sắc thái mạnh, trang trọng hơn give up.", f: "abandon (v), abandonment (n), abandoned (adj)" },
  "accompany": { m: "ac- (đến) + company (bạn đồng hành) → làm bạn đồng hành, đi cùng.", e: "Sai: accompany with her → Đúng: accompany her (ngoại động từ, không cần with). Bị động: be accompanied by.", u: "Trang trọng: children must be accompanied by an adult; the report is accompanied by charts. Hay dùng mô tả tài liệu đi kèm trong TOEIC.", f: "accompany (v), accompaniment (n), accompanying (adj)" },
  "accumulate": { m: "ac- (thêm vào) + cumulus (đống) → chất thêm thành đống, tích lũy dần (như mây cumulus chồng chất).", e: "Sai: accumulate (đánh vần accummulate) → Đúng: accumulate, một chữ m. Nhấn âm 2: ac-CU-mu-late.", u: "accumulate wealth/data/debt/experience; dust accumulates. Dùng cho quá trình tăng dần theo thời gian, hợp văn viết học thuật.", f: "accumulate (v), accumulation (n), accumulative (adj), cumulative (adj)" },
  "ambiguous": { m: "ambi- (cả hai, như ambidextrous) + agere (dẫn) → dẫn về hai hướng, hiểu nhiều cách.", e: "Sai: ambigous → Đúng: ambiguous (có u sau g). Danh từ là ambiguity, không phải ambiguousness trong văn học thuật.", u: "ambiguous wording/answer/result; highly ambiguous. Trong Writing dùng để phê phán định nghĩa không rõ: the term remains ambiguous.", f: "ambiguous (adj), ambiguity (n), ambiguously (adv), unambiguous (adj)" },
  "append": { m: "ap- (vào) + pendere (treo) → treo thêm vào cuối; liên hệ appendix (phụ lục).", e: "Sai: append the file in the email → Đúng: append the file to the email (append ... to).", u: "Trang trọng, văn bản: append a note/signature to a document. Trong TOEIC hay gặp appendix (phụ lục). Giao tiếp thường dùng attach, add.", f: "append (v), appendix (n), appendage (n)" },
  "appreciate": { m: "ap- (hướng tới) + pretium (giá, như price) → định giá cao: trân trọng hoặc tăng giá trị.", e: "Sai: I appreciate for your help → Đúng: I appreciate your help (không dùng for; chủ ngữ là người, tân ngữ là việc).", u: "Lịch sự trong email TOEIC: I would appreciate it if you could...; nghĩa kinh tế: the currency/property appreciated in value.", f: "appreciate (v), appreciation (n), appreciative (adj), appreciable (adj)" },
  "arbitrary": { m: "arbiter (trọng tài) → do một người tự ý quyết định, không theo quy tắc → tùy tiện.", e: "Sai: nhấn âm 2 ar-BI-tra-ry → Đúng: nhấn âm 1 AR-bi-tra-ry. Không nhầm với arbitration (trọng tài phân xử).", u: "Sắc thái tiêu cực: arbitrary decision/rules/arrest; an arbitrary choice. Hữu ích khi phê phán chính sách trong IELTS Writing.", f: "arbitrary (adj), arbitrarily (adv), arbitrator (n), arbitration (n)" },
  "automate": { m: "auto- (tự) + -mate (giống automatic) → làm cho máy tự chạy.", e: "Sai: automatic the process → Đúng: automate the process (automatic là tính từ, automate là động từ).", u: "automate tasks/production; highly automated factories. Chủ đề công nghệ, việc làm trong IELTS: jobs at risk of automation.", f: "automate (v), automation (n), automatic (adj), automatically (adv)" },
  "bias": { m: "Liên tưởng đường cắt 'chéo' vải (on the bias) → nghiêng lệch một phía → thiên vị.", e: "Sai: bias with women → Đúng: bias against women / bias towards something (dùng against hoặc towards).", u: "gender/racial bias, media bias, be biased against; trong nghiên cứu: sampling bias. Văn học thuật, khách quan.", f: "bias (n, v), biased (adj), unbiased (adj)" },
  "chart": { m: "Từ Latin charta (giấy, như card) → tờ giấy vẽ số liệu thành hình.", e: "Sai: the chart shows about the sales → Đúng: the chart shows the sales (shows không đi với about).", u: "IELTS Task 1: bar/pie chart, the chart illustrates/compares; động từ chart progress (theo dõi). Còn có nghĩa bảng xếp hạng nhạc: top the charts.", f: "chart (n, v), charter (n, v)" },
  "clarify": { m: "clar- (sáng, như clear) + -ify (làm cho) → làm cho sáng rõ.", e: "Sai: clarify about the rules → Đúng: clarify the rules (ngoại động từ, không cần about).", u: "clarify a point/position/issue; could you clarify...? Lịch sự trong email, họp hành; trong Speaking dùng khi muốn hỏi lại.", f: "clarify (v), clarification (n), clarity (n), clear (adj)" },
  "commodity": { m: "Gốc commodus (tiện lợi) → thứ hữu ích đem ra mua bán → hàng hóa.", e: "Sai: nhấn com-mo-DI-ty → Đúng: nhấn âm 2 com-MO-di-ty. Nghĩa là hàng hóa thô, không phải tiện nghi (amenities).", u: "Kinh tế: commodity prices, basic commodities như dầu, gạo, cà phê. Nghĩa bóng: time is a precious commodity.", f: "commodity (n), commodities (n, số nhiều), commodify (v)" },
  "complement": { m: "complete (đầy đủ) → complement làm cho trọn vẹn. Phân biệt compliment có 'i' như I (tôi) khen bạn.", e: "Sai: compliment each other (bổ sung) → Đúng: complement each other. Compliment là khen ngợi, chính tả dễ nhầm.", u: "complement each other perfectly; X complements Y. Dùng mô tả hai yếu tố bổ trợ: theory and practice complement each other.", f: "complement (v, n), complementary (adj)" },
  "conform": { m: "con- (cùng) + form (hình dạng) → cùng một khuôn → tuân theo chuẩn chung.", e: "Sai: conform the rules → Đúng: conform to the rules (luôn cần to hoặc with).", u: "conform to standards/regulations/expectations; pressure to conform. Chủ đề xã hội IELTS: teenagers feel pressure to conform.", f: "conform (v), conformity (n), conformist (n, adj), nonconformist (n)" },
  "contemporary": { m: "con- (cùng) + tempus (thời gian, như temporary) → cùng thời đại → đương đại.", e: "Sai: contemporary of Mozart nghĩa 'hiện đại' → Đúng: contemporary còn là 'người cùng thời': a contemporary of Mozart. Nhấn âm 2: con-TEM-po-ra-ry.", u: "contemporary art/music/society; dùng trang trọng hơn modern. Danh từ: his contemporaries (người cùng thời).", f: "contemporary (adj, n), contemporaneous (adj)" },
  "contradict": { m: "contra- (ngược lại) + dict (nói, như dictionary) → nói ngược lại.", e: "Sai: contradict with the evidence → Đúng: contradict the evidence (không cần with); be in contradiction with.", u: "findings contradict earlier research; contradict oneself. Dùng phân tích lập luận trong IELTS Writing: this contradicts the claim that...", f: "contradict (v), contradiction (n), contradictory (adj)" },
  "crucial": { m: "crux (chữ thập, điểm giao) → điểm mấu chốt nơi mọi thứ giao nhau → then chốt.", e: "Sai: crucial for to succeed → Đúng: crucial for success / crucial to success; it is crucial that we act.", u: "play a crucial role, crucial factor/decision. Thay cho very important để tăng điểm Lexical Resource.", f: "crucial (adj), crucially (adv)" },
  "currency": { m: "curr- (chạy, như current) → tiền chảy lưu thông trong xã hội.", e: "Sai: exchange money to dollar currency → Đúng: exchange money into US dollars. Currency đếm được khi nói các loại tiền: two currencies.", u: "foreign/local/digital currency, currency exchange. Nghĩa bóng: the idea gained currency (được chấp nhận rộng rãi).", f: "currency (n), current (adj), currently (adv)" },
  "denote": { m: "de- (hoàn toàn) + note (ghi dấu) → đánh dấu để chỉ ra ý nghĩa.", e: "Sai: denote nghĩa 'tố cáo' (nhầm denounce) → Đúng: the symbol X denotes speed (biểu thị).", u: "Học thuật, kỹ thuật: the red line denotes...; dùng mô tả ký hiệu trong biểu đồ IELTS Task 1. Phân biệt connote (hàm ý).", f: "denote (v), denotation (n)" },
  "detect": { m: "de- (gỡ ra) + tegere (che) → gỡ lớp che → phát hiện; liên hệ detective (thám tử).", e: "Sai: detect about the problem → Đúng: detect the problem. Lưu ý: detector là máy dò, detective là thám tử.", u: "detect cancer/changes/errors early; hard to detect. Hay dùng trong y học, khoa học, an ninh.", f: "detect (v), detection (n), detector (n), detective (n), detectable (adj)" },
  "deviate": { m: "de- (rời khỏi) + via (đường) → rời khỏi con đường → đi chệch.", e: "Sai: deviate the plan → Đúng: deviate from the plan (luôn đi với from).", u: "deviate from the norm/standard/plan. Trang trọng; standard deviation (độ lệch chuẩn) trong thống kê.", f: "deviate (v), deviation (n), deviant (adj, n)" },
  "displace": { m: "dis- (rời đi) + place (chỗ) → đẩy khỏi chỗ cũ → di dời, thay thế.", e: "Sai: displace nghĩa 'đặt sai chỗ' → Đúng: misplace my keys (để lạc). Displace là buộc di dời: displaced by war.", u: "displaced people/workers; robots displace human workers. Chủ đề di cư, chiến tranh, tự động hóa trong IELTS.", f: "displace (v), displacement (n), displaced (adj)" },
  "drama": { m: "Gốc Hy Lạp dran (hành động) → hành động trên sân khấu → kịch.", e: "Sai: a drama increase → Đúng: a dramatic increase (dùng tính từ dramatic trước danh từ). Nhấn âm 1: DRA-ma.", u: "TV drama, drama series; nghĩa đời thường: a lot of drama. IELTS: a dramatic increase (tăng mạnh) rất hữu dụng cho Task 1.", f: "drama (n), dramatic (adj), dramatically (adv), dramatize (v), dramatist (n)" },
  "eventual": { m: "event (sự kiện) + -ual → sự kiện xảy ra sau cùng → cuối cùng.", e: "Sai: eventual nghĩa 'có thể xảy ra' (false friend tiếng Pháp) → Đúng: eventual là 'cuối cùng': the eventual winner.", u: "the eventual outcome/winner/cost; trạng từ eventually rất phổ biến khi kể chuyện trong Speaking.", f: "eventual (adj), eventually (adv), eventuality (n)" },
  "exhibit": { m: "ex- (ra ngoài) + habere (giữ) → đem ra ngoài cho xem → trưng bày.", e: "Sai: phát âm chữ h /eks-hi-bit/ → Đúng: h câm, /ɪɡ'zɪb.ɪt/, nhấn âm 2. Danh từ triển lãm: exhibition.", u: "exhibit paintings; nghĩa trang trọng: exhibit symptoms/behaviour (biểu hiện). TOEIC hay gặp exhibition hall, trade exhibition.", f: "exhibit (v, n), exhibition (n), exhibitor (n)" },
  "exploit": { m: "ex- (ra) + plicare (gấp) → mở ra, tận dụng hết → khai thác, có khi đến mức bóc lột.", e: "Sai: exploit nghĩa luôn tốt → Đúng: exploit workers mang nghĩa xấu; exploit resources trung tính. Nhấn âm 2 khi là động từ: ex-PLOIT.", u: "exploit natural resources/opportunities; exploit cheap labour. Chủ đề môi trường, lao động trong IELTS Writing.", f: "exploit (v, n), exploitation (n), exploitative (adj)" },
  "fluctuate": { m: "fluctus (sóng), cùng gốc fluid → lên xuống như sóng → dao động.", e: "Sai: the price fluctuated 10% → Đúng: fluctuated between 10 and 15 / fluctuated around 10 (dùng between, around).", u: "IELTS Task 1: fluctuate wildly/slightly; a period of fluctuation. Dùng cho giá cả, nhiệt độ, số liệu lên xuống thất thường.", f: "fluctuate (v), fluctuation (n), fluctuating (adj)" },
  "guideline": { m: "guide (dẫn đường) + line (đường kẻ) → đường kẻ chỉ lối → hướng dẫn.", e: "Sai: follow the guideline (khi nói bộ quy định chung) → Đúng: follow the guidelines (thường dùng số nhiều).", u: "follow/issue/strict guidelines; government guidelines on... Trang trọng, gặp nhiều trong TOEIC về quy định công ty.", f: "guideline (n), guide (n, v), guidance (n)" },
  "highlight": { m: "high (cao) + light (ánh sáng) → chiếu đèn lên chỗ nổi bật; giống bút dạ quang highlighter.", e: "Sai: highlight about the risks → Đúng: highlight the risks (không dùng about).", u: "highlight the importance/need for; the report highlights... Danh từ: the highlight of the trip (điểm nhấn) trong Speaking.", f: "highlight (v, n), highlighter (n)" },
  "implicit": { m: "im- (vào trong) + plicare (gấp) → gấp vào bên trong, không nói ra → ngầm. Trái nghĩa explicit.", e: "Sai: implicit nghĩa 'phức tạp' (nhầm complicated) → Đúng: implicit là ngầm định: an implicit agreement.", u: "implicit criticism/assumption/trust; implicit in something. Văn học thuật, đối lập với explicit (rõ ràng).", f: "implicit (adj), implicitly (adv), imply (v), implication (n)" },
  "induce": { m: "in- (vào) + ducere (dẫn, như introduce) → dẫn dắt vào trạng thái nào đó → gây ra, thuyết phục.", e: "Sai: induce him buy it → Đúng: induce him to buy it (induce sb to do sth).", u: "Trang trọng: drug-induced sleep, stress-induced illness; induce labour (y học). Dùng mô tả nguyên nhân trong Writing.", f: "induce (v), inducement (n), induction (n)" },
  "inevitable": { m: "in- (không) + evitare (tránh) → không thể tránh được.", e: "Sai: nhấn in-e-VI-ta-ble → Đúng: nhấn âm 2 in-EV-i-ta-ble.", u: "It is inevitable that...; an inevitable consequence. Cụm hay cho Writing: change is inevitable; inevitably, costs will rise.", f: "inevitable (adj), inevitably (adv), inevitability (n)" },
  "infrastructure": { m: "infra- (bên dưới) + structure (cấu trúc) → cấu trúc nằm dưới nâng đỡ xã hội → hạ tầng.", e: "Sai: infrastructures (dùng tùy tiện số nhiều) → Đúng: infrastructure thường không đếm được: invest in infrastructure.", u: "transport/digital infrastructure; invest in, upgrade infrastructure. Chủ đề đô thị, chính phủ trong IELTS Writing Task 2.", f: "infrastructure (n), infrastructural (adj)" },
  "inspect": { m: "in- (vào) + spect (nhìn, như spectator) → nhìn kỹ vào bên trong → kiểm tra.", e: "Sai: inspect about the building → Đúng: inspect the building. Không dùng inspect cho kiểm tra bài thi (dùng mark, check).", u: "inspect goods/premises/equipment; carefully inspect. TOEIC: safety inspection, inspector. Trang trọng hơn check.", f: "inspect (v), inspection (n), inspector (n)" },
  "intense": { m: "in- (vào) + tendere (căng) → căng hết mức → mãnh liệt.", e: "Sai: intense (nhầm intensive) course → Đúng: intensive course (khóa học cấp tốc). Intense chỉ mức độ cảm xúc, nhiệt.", u: "intense heat/pressure/competition/debate. Dùng nhấn mạnh mức độ trong Writing: intense competition among firms.", f: "intense (adj), intensity (n), intensify (v), intensive (adj), intensely (adv)" },
  "manipulate": { m: "manus (tay, như manual) → manipulus (nắm tay) → dùng tay điều khiển khéo léo → thao tác, thao túng.", e: "Sai: nhấn MA-ni-pu-late → Đúng: nhấn âm 2 ma-NIP-u-late.", u: "Nghĩa xấu: manipulate people/public opinion/data; trung tính: manipulate images. Chủ đề truyền thông, quảng cáo trong IELTS.", f: "manipulate (v), manipulation (n), manipulative (adj), manipulator (n)" },
  "minimise": { m: "minimum (tối thiểu) + -ise (làm cho) → đưa về mức tối thiểu.", e: "Chính tả: minimise (Anh) / minimize (Mỹ), viết thống nhất một kiểu. Sai: minimise to the risk → Đúng: minimise the risk.", u: "minimise risk/cost/damage/impact. Rất hữu dụng cho đề giải pháp IELTS Writing: measures to minimise pollution.", f: "minimise (v), minimum (n, adj), minimal (adj), minimisation (n)" },
  "nuclear": { m: "nucleus (hạt nhân, nhân tế bào) → thuộc về hạt nhân.", e: "Sai: đọc 'nu-cu-lar' → Đúng: /'njuː.kli.ər/ NU-cle-ar. Lỗi phát âm phổ biến cả với người bản xứ.", u: "nuclear power/energy/weapons/family. Nuclear family (gia đình hạt nhân) hay gặp trong chủ đề gia đình IELTS.", f: "nuclear (adj), nucleus (n), nuclei (n, số nhiều)" },
  "offset": { m: "off (tách ra) + set (đặt) → đặt một thứ bên kia cán cân để cân bằng → bù đắp.", e: "Sai: offset with the losses → Đúng: offset the losses; X is offset by Y. Quá khứ vẫn là offset.", u: "offset costs/losses/carbon emissions; carbon offset. Writing: the benefits offset the drawbacks.", f: "offset (v, n)" },
  "paragraph": { m: "para- (bên cạnh) + graph (viết) → dấu viết bên lề đánh dấu đoạn mới.", e: "Sai: on paragraph 2 → Đúng: in paragraph 2 (dùng in). Viết tắt para. chỉ dùng trong ghi chú.", u: "body/opening paragraph; topic sentence of a paragraph. IELTS Writing chấm Coherence: mỗi đoạn một ý chính.", f: "paragraph (n, v)" },
  "plus": { m: "Latin plus (nhiều hơn), giống dấu cộng (+) → cộng thêm.", e: "Sai: Plus, we also have... (lặp ý) → Đúng: Plus, we have... hoặc In addition, we also have. Plus đầu câu khá thân mật.", u: "Toán: two plus two; thân mật: plus, it's cheap. Danh từ: a big plus (ưu điểm). Văn trang trọng nên dùng moreover.", f: "plus (prep, conj, n, adj)" },
  "practitioner": { m: "practice (thực hành) + -ioner (người) → người hành nghề chuyên môn.", e: "Sai: practicer → Đúng: practitioner. Nhấn âm 2: prac-TI-tion-er.", u: "medical practitioner, general practitioner (GP: bác sĩ đa khoa), legal practitioners. Văn trang trọng, chuyên ngành.", f: "practitioner (n), practice (n), practise (v, Anh), practical (adj)" },
  "predominant": { m: "pre- (trước, trên) + dominant (chiếm ưu thế) → đứng trên hết, nổi trội nhất.", e: "Sai: predominate language (nhầm từ loại) → Đúng: predominant language. Predominate là động từ.", u: "the predominant view/language/colour; predominantly young. IELTS Task 1: the predominant source of energy.", f: "predominant (adj), predominantly (adv), predominate (v), predominance (n)" },
  "prospect": { m: "pro- (phía trước) + spect (nhìn) → nhìn về phía trước → triển vọng.", e: "Sai: job prospect is good → Đúng: job prospects are good (nghĩa cơ hội tương lai thường số nhiều).", u: "career/job prospects, the prospect of doing; TOEIC: prospective clients (khách hàng tiềm năng).", f: "prospect (n, v), prospective (adj), prospector (n)" },
  "radical": { m: "radix (rễ, như radish) → thay đổi tận gốc rễ → triệt để, cấp tiến.", e: "Sai: radical nghĩa 'cực đoan' trong mọi ngữ cảnh → Đúng: radical change là thay đổi căn bản, không nhất thiết xấu.", u: "radical reform/change/approach; radical views (cấp tiến). Dùng đề xuất giải pháp mạnh trong IELTS Writing.", f: "radical (adj, n), radically (adv), radicalism (n)" },
  "random": { m: "Gốc Pháp randon (chạy vội, bừa) → không theo trật tự → ngẫu nhiên.", e: "Sai: randomly selection → Đúng: random selection / selected at random (tính từ trước danh từ, at random cố định).", u: "random sample/selection; chosen at random. Văn nói: that's so random (kỳ quặc). Nghiên cứu: randomly assigned.", f: "random (adj), randomly (adv), randomness (n), randomise (v)" },
  "reinforce": { m: "re- (lại) + in- + force (sức mạnh) → tăng thêm sức mạnh → củng cố.", e: "Sai: reinforce for the idea → Đúng: reinforce the idea (không dùng for).", u: "reinforce a message/stereotype/belief; reinforced concrete (bê tông cốt thép). Writing: media reinforce gender stereotypes.", f: "reinforce (v), reinforcement (n), reinforced (adj)" },
  "restore": { m: "re- (lại) + store (dựng, gốc staurare) → dựng lại như cũ → khôi phục.", e: "Sai: restore the old temple to new → Đúng: restore the old temple (to its original state). Không nhầm với restaurant hay rest.", u: "restore order/confidence/trust/a building. IELTS chủ đề di sản: restore historic buildings; TOEIC: restore service.", f: "restore (v), restoration (n), restorative (adj)" },
  "revise": { m: "re- (lại) + vise (nhìn, như vision) → nhìn lại để sửa → sửa đổi, ôn tập.", e: "Sai: revise (Mỹ) nghĩa ôn bài → Đúng: Anh dùng revise for an exam; Mỹ dùng review. Revise for, không revise about.", u: "revise a plan/estimate/policy; revised version, revise for exams (Anh). TOEIC: revised schedule.", f: "revise (v), revision (n), revised (adj)" },
  "schedule": { m: "Latin schedula (tờ giấy nhỏ) → tờ giấy ghi kế hoạch thời gian → lịch trình.", e: "Phát âm: Anh /'ʃedʒ.uːl/, Mỹ /'skedʒ.uːl/. Sai: on the schedule → Đúng: on schedule (đúng tiến độ), behind schedule.", u: "TOEIC rất hay gặp: ahead of/behind/on schedule; tight schedule; be scheduled for Monday; reschedule a meeting.", f: "schedule (n, v), scheduled (adj), reschedule (v), scheduling (n)" },
  "tension": { m: "tendere (căng), cùng gốc tense, tend → trạng thái căng → căng thẳng.", e: "Sai: I have tension about the exam → Đúng: I feel stressed / nervous. Tension dùng cho quan hệ, cơ, dây: tension between groups.", u: "rising/racial/political tension; tensions between countries; ease tension. Chủ đề xã hội, quốc tế IELTS.", f: "tension (n), tense (adj, v), tensely (adv)" },
  "terminate": { m: "terminus (điểm cuối, như terminal) → đưa đến điểm cuối → chấm dứt.", e: "Sai: terminate with the contract → Đúng: terminate the contract (ngoại động từ).", u: "Trang trọng: terminate a contract/agreement/employment. TOEIC hay gặp; đời thường dùng end.", f: "terminate (v), termination (n), terminal (adj, n)" },
  "theme": { m: "Gốc Hy Lạp thema (điều được đặt ra) → đề tài đặt ra cho bài → chủ đề.", e: "Sai: phát âm /tem/ → Đúng: /θiːm/ với âm th. Không nhầm topic (đề bài cụ thể) với theme (ý xuyên suốt).", u: "main/central/recurring theme; theme park; a common theme in literature. Dùng phân tích tác phẩm, sự kiện.", f: "theme (n), thematic (adj), themed (adj)" },
  "thereby": { m: "there (điều đó) + by (bằng) → bằng cách đó → qua đó, nhờ đó.", e: "Sai: thereby he improved (dùng như mệnh đề riêng) → Đúng: ..., thereby improving efficiency (thereby + V-ing).", u: "Rất trang trọng, văn học thuật: reduce costs, thereby increasing profits. Ghi điểm liên kết trong IELTS Writing nếu dùng đúng.", f: "thereby (adv)" },
  "uniform": { m: "uni- (một) + form (hình dạng) → một hình dạng duy nhất → đồng nhất; đồng phục.", e: "Sai: uniform with each other → Đúng: uniform in size / uniform throughout. Tính từ nghĩa 'đồng nhất', danh từ là 'đồng phục'.", u: "uniform standards/rate/distribution. IELTS chủ đề trường học: school uniform; tính từ hay dùng trong khoa học.", f: "uniform (adj, n), uniformity (n), uniformly (adv)" },
  "vehicle": { m: "Latin vehere (chở) → thứ dùng để chở → phương tiện.", e: "Sai: phát âm chữ h /ve-hi-cle/ → Đúng: /'viː.ɪ.kəl/, h câm, nhấn âm 1.", u: "motor/electric vehicles; nghĩa bóng: a vehicle for change/communication (công cụ). Chủ đề giao thông IELTS.", f: "vehicle (n), vehicular (adj)" },
  "via": { m: "Latin via (con đường) → đi theo con đường → thông qua.", e: "Sai: via by email → Đúng: via email (không thêm by). Không dùng via cho người khi có thể dùng through.", u: "Trang trọng hơn by/through: send via email; fly to London via Dubai (quá cảnh). TOEIC hay gặp.", f: "via (prep)" },
  "virtual": { m: "virtus (sức mạnh, như virtue) → có tác dụng thật nhưng không hiện hữu vật lý → ảo; gần như.", e: "Sai: virtual nghĩa luôn là 'ảo' → Đúng: a virtual certainty là 'gần như chắc chắn'. Virtually = almost.", u: "virtual reality/meeting/classroom; virtually impossible. Chủ đề công nghệ, giáo dục trực tuyến IELTS.", f: "virtual (adj), virtually (adv), virtuality (n)" },
  "visual": { m: "vis- (nhìn, như vision, visit) → thuộc về nhìn → thị giác.", e: "Sai: visual aids nhầm visible (nhìn thấy được) → Đúng: visual = liên quan đến thị giác; visible = có thể thấy.", u: "visual aids/arts/effects/learner. Writing, Speaking về giáo dục: visual learners benefit from diagrams.", f: "visual (adj, n), visually (adv), visualise (v), visualisation (n)" },
  "widespread": { m: "wide (rộng) + spread (lan) → lan ra rộng khắp → phổ biến.", e: "Sai: widely spread (dùng như tính từ trước danh từ) → Đúng: widespread use (tính từ ghép viết liền).", u: "widespread use/support/concern/belief. Dùng mở bài IELTS: there is widespread concern about...", f: "widespread (adj), widely (adv), spread (v, n)" },
  "accommodate": { m: "ac- (hướng tới) + commodus (vừa vặn, tiện lợi) → làm cho vừa, chứa đủ chỗ; giống 'commodity' (hàng tiện dụng).", e: "Sai: acommodate / accomodate → Đúng: accommodate (hai chữ c, hai chữ m). Nhấn âm 2: ac-COM-mo-date.", u: "accommodate guests/students/needs; accommodate changes. Danh từ accommodation (UK, không đếm được) hay gặp trong TOEIC du lịch, khách sạn. Văn phong trang trọng.", f: "accommodation (n), accommodating (adj), accommodate (v)" },
  "analogy": { m: "ana- (theo) + logos (lý lẽ) → lập luận theo sự giống nhau; cùng gốc với 'logic'.", e: "Sai: an analogy with two things → Đúng: an analogy between two things (draw an analogy between A and B). Nhấn âm 2: a-NA-lo-gy.", u: "draw/make an analogy between A and B; by analogy with. Dùng khi giải thích ý khó trong IELTS Writing/Speaking bằng ví dụ quen thuộc.", f: "analogy (n), analogous (adj), analogue/analog (n)" },
  "anticipate": { m: "anti- (trước, như 'ante') + capere (nắm lấy) → nắm lấy trước, lường trước điều sắp xảy ra.", e: "Sai: We anticipate to finish soon → Đúng: We anticipate finishing soon (anticipate + V-ing hoặc + that-clause, không + to V).", u: "anticipate problems/demand/a rise; eagerly anticipated. Trang trọng hơn expect, hay dùng trong báo cáo kinh doanh TOEIC và IELTS Task 1 dự báo.", f: "anticipation (n), anticipated (adj), anticipatory (adj)" },
  "assure": { m: "as- (hướng tới) + sure (chắc chắn) → làm cho ai đó cảm thấy chắc chắn, cam đoan.", e: "Sai: I assure that it works → Đúng: I assure you that it works (assure cần tân ngữ chỉ người). Đừng nhầm với ensure, insure.", u: "assure somebody of something / that...; rest assured. Dùng để trấn an khách hàng trong email TOEIC; ensure là đảm bảo việc xảy ra.", f: "assurance (n), assured (adj), reassure (v), reassurance (n)" },
  "attain": { m: "at- (tới) + tangere (chạm) → chạm tới mục tiêu, đạt được; cùng gốc với 'tangible' (sờ được).", e: "Sai: attain to a high level → Đúng: attain a high level (attain là ngoại động từ, không cần to).", u: "attain a goal/a degree/a standard/success. Trang trọng hơn achieve, thường nói về mục tiêu khó đạt sau nhiều nỗ lực.", f: "attainment (n), attainable (adj), unattainable (adj)" },
  "behalf": { m: "be- (bởi) + half (phía, bên) → đứng về phía ai, thay mặt cho bên đó.", e: "Sai: on behalf of me, I thank you → Đúng: on my behalf / on behalf of the team (thường dùng on behalf of + tổ chức).", u: "on behalf of the company/staff; on somebody's behalf. Rất phổ biến trong thư từ TOEIC: 'On behalf of the board, I would like to...'.", f: "behalf (n) – chỉ dùng trong cụm on/in behalf of" },
  "bulk": { m: "Gần âm 'búc' một khối lớn: bulk là khối to, số lượng lớn; 'buy in bulk' = mua sỉ.", e: "Sai: buy in bulks → Đúng: buy in bulk (bulk trong cụm này không có số nhiều).", u: "the bulk of (phần lớn) + danh từ; buy/sell in bulk; bulk orders. TOEIC hay gặp trong mua hàng, giảm giá khi đặt số lượng lớn.", f: "bulky (adj), bulk (n, adj)" },
  "cease": { m: "Từ Latin cessare (dừng lại); cùng họ với 'cessation'. Đọc giống 'xít': ngắt, dừng hẳn.", e: "Sai: cease /siːz/ (đọc như seize = chiếm giữ) → Đúng: cease /siːs/. Cách dùng: cease to exist / cease operations.", u: "cease operations/production; cease to exist; cease-fire. Trang trọng hơn stop, hợp văn viết học thuật và thông báo chính thức.", f: "cessation (n), ceaseless (adj), ceaselessly (adv), unceasing (adj)" },
  "coherent": { m: "co- (cùng nhau) + haerere (dính) → các ý dính vào nhau, mạch lạc; cùng gốc 'adhere'.", e: "Sai: coherence essay → Đúng: coherent essay (coherent là tính từ, coherence là danh từ). Nhấn âm 2: co-HE-rent.", u: "a coherent argument/plan/strategy. 'Coherence and Cohesion' là một tiêu chí chấm IELTS Writing; dùng coherent để khen lập luận chặt chẽ.", f: "coherence (n), coherently (adv), incoherent (adj)" },
  "coincide": { m: "co- (cùng) + in (vào) + cadere (rơi) → cùng rơi vào một thời điểm, trùng nhau; 'coincidence' là sự trùng hợp.", e: "Sai: The event coincides to my birthday → Đúng: The event coincides with my birthday (coincide with).", u: "coincide with something; coincide in time. Dùng trong IELTS Task 1 khi hai xu hướng xảy ra cùng lúc. Nhấn âm 3: co-in-CIDE.", f: "coincidence (n), coincidental (adj), coincidentally (adv)" },
  "commence": { m: "com- (hoàn toàn) + initiare (bắt đầu) → bắt đầu chính thức; 'commencement' là lễ tốt nghiệp ở Mỹ.", e: "Sai: commence to work → Đúng: commence work / commence working (thường + danh từ hoặc V-ing). Chính tả: hai chữ m.", u: "commence operations/construction; the meeting will commence at 9 a.m. Rất trang trọng, hay gặp trong thông báo TOEIC; văn nói dùng start.", f: "commencement (n), commence (v)" },
  "compatible": { m: "com- (cùng) + pati (chịu đựng) → có thể chịu đựng, sống chung được với nhau; giống 'patient'.", e: "Sai: compatible to Windows → Đúng: compatible with Windows (compatible with). Chính tả: -ible, không phải -able.", u: "compatible with software/devices; fully compatible. Phổ biến trong TOEIC công nghệ; cũng dùng cho quan hệ con người, mục tiêu phù hợp nhau.", f: "compatibility (n), incompatible (adj), incompatibility (n)" },
  "concurrent": { m: "con- (cùng) + currere (chạy) → cùng chạy song song, đồng thời; cùng gốc 'current'.", e: "Sai: two courses run concurrent → Đúng: two courses run concurrently (bổ nghĩa cho động từ phải dùng trạng từ). Nhấn âm 2: con-CUR-rent.", u: "concurrent events/sessions/sentences. Văn phong trang trọng, kỹ thuật; dùng concurrently để mô tả việc diễn ra cùng lúc.", f: "concurrently (adv), concurrence (n), concur (v)" },
  "confine": { m: "con- (cùng) + finis (giới hạn, biên) → khoanh trong biên giới; giống 'finish', 'finite'.", e: "Sai: confine in a small area → Đúng: confine to a small area (confine somebody/something to).", u: "be confined to + nơi chốn/phạm vi; confine discussion to. Trong IELTS dùng để giới hạn phạm vi bài: 'This essay is confined to...'.", f: "confinement (n), confined (adj), confines (n)" },
  "controversy": { m: "contra- (chống lại) + vertere (quay) → quay sang chống nhau, gây tranh cãi; giống 'reverse'.", e: "Lỗi nhấn âm: UK thường CON-tro-ver-sy hoặc con-TRO-ver-sy; nhiều người nhấn âm 3 là sai. Sai: controversy about → Đúng: controversy over/about.", u: "spark/cause controversy; a controversy over something; controversial issue. Rất hữu ích cho IELTS Writing khi bàn vấn đề gây tranh cãi.", f: "controversial (adj), controversially (adv), uncontroversial (adj)" },
  "converse": { m: "con- (cùng) + vertere (quay) → quay ngược lại: the converse là điều ngược lại. Động từ converse là trò chuyện.", e: "Lỗi nhấn âm: danh từ CON-verse (điều ngược lại), động từ con-VERSE (trò chuyện). Đừng nhầm với conversation.", u: "the converse is also true; conversely (ngược lại) là từ nối tốt trong IELTS Writing để đối lập hai ý.", f: "conversely (adv), converse (v, adj), conversation (n)" },
  "device": { m: "Từ tiếng Pháp devis (sự sắp đặt, kế hoạch) → vật được thiết kế cho mục đích; liên quan 'devise' (nghĩ ra).", e: "Sai: I will device a plan → Đúng: I will devise a plan (device là danh từ /s/, devise là động từ /z/).", u: "electronic/mobile devices; a safety device; a literary device. Đếm được: many devices. Rất thường gặp trong TOEIC công nghệ.", f: "devise (v), device (n)" },
  "devote": { m: "de- (hoàn toàn) + vovere (thề nguyện) → thề hiến dâng trọn vẹn; giống 'vow' (lời thề).", e: "Sai: devote to study → Đúng: devote time to studying (to là giới từ nên + V-ing).", u: "devote time/effort/resources to something; be devoted to. Dùng trong IELTS khi nói chính phủ nên dành ngân sách cho lĩnh vực nào.", f: "devotion (n), devoted (adj), devotee (n)" },
  "diminish": { m: "di- (giảm) + minuere (làm nhỏ) → làm nhỏ đi; cùng gốc 'minus', 'minimum', 'mini'.", e: "Sai: diminish down → Đúng: diminish (đã có nghĩa giảm, không thêm down). Nhấn âm 2: di-MI-nish.", u: "diminish the value/importance/risk; diminishing returns. Trang trọng hơn reduce, hay dùng trong IELTS Writing để tránh lặp từ.", f: "diminution (n), diminished (adj), diminishing (adj)" },
  "distort": { m: "dis- (lệch) + torquere (vặn xoắn) → vặn lệch đi, bóp méo; cùng gốc 'torture', 'torque'.", e: "Sai: The media distortion the facts → Đúng: The media distort the facts (distortion là danh từ, distort là động từ).", u: "distort the truth/facts/image/results. Mang sắc thái tiêu cực, thường nói về truyền thông đưa tin sai lệch trong IELTS Writing.", f: "distortion (n), distorted (adj)" },
  "duration": { m: "durare (kéo dài) → khoảng thời gian kéo dài; cùng gốc 'during', 'durable' (bền).", e: "Sai: a duration of three hours long → Đúng: a duration of three hours (tránh lặp long). Hay dùng for the duration of.", u: "for the duration of the course/contract; short/long duration. Trang trọng, hợp văn bản hợp đồng, thông báo TOEIC.", f: "duration (n), durable (adj), endure (v)" },
  "erode": { m: "e- (ra ngoài) + rodere (gặm) → gặm mòn dần; cùng gốc 'rodent' (loài gặm nhấm).", e: "Sai: The trust was eroding by scandals → Đúng: Trust was eroded by scandals (bị động với tân ngữ).", u: "erode confidence/trust/support; coastal erosion. Dùng nghĩa bóng trong IELTS: niềm tin, giá trị truyền thống bị xói mòn dần.", f: "erosion (n), erosive (adj), eroded (adj)" },
  "ethic": { m: "Hy Lạp ethos (thói quen, tính cách) → nguyên tắc ứng xử. Đừng nhầm với ethnic (thuộc dân tộc).", e: "Sai: medical ethic (khi nói chung) → Đúng: medical ethics (ethics số nhiều chỉ đạo đức học). Đừng nhầm ethical với ethnic.", u: "work ethic (tinh thần làm việc); professional/business ethics; ethical issues. Rất hữu ích cho IELTS chủ đề công nghệ, y học.", f: "ethics (n), ethical (adj), ethically (adv), unethical (adj)" },
  "format": { m: "forma (hình dạng) → cách sắp xếp hình thức; cùng gốc 'form', 'formal'.", e: "Lỗi nhấn âm: nhấn âm 1 FOR-mat. Sai: in format of → Đúng: in the format of / in PDF format.", u: "in electronic/digital format; change the format; format a document. Hay gặp trong email TOEIC về tài liệu, báo cáo.", f: "format (n, v), formatting (n), formatted (adj)" },
  "found": { m: "fundus (đáy, nền) → đặt nền móng, thành lập; cùng gốc 'foundation', 'fundamental'.", e: "Sai: He founded in 1990 / nhầm với find → Đúng: The company was founded in 1990 (found – founded – founded, khác find – found).", u: "found a company/school/organisation; be founded on principles. Dùng khi giới thiệu lịch sử công ty trong TOEIC.", f: "foundation (n), founder (n), founding (adj), unfounded (adj)" },
  "inherent": { m: "in- (trong) + haerere (dính) → dính sẵn bên trong, vốn có; cùng gốc 'adhere', 'coherent'.", e: "Sai: inherent of the system → Đúng: inherent in the system (inherent in). Nhấn âm 2: in-HE-rent.", u: "inherent risks/problems/weaknesses; be inherent in. Dùng trong IELTS để nói rủi ro vốn có của một giải pháp, nghe học thuật.", f: "inherently (adv), inhere (v)" },
  "insight": { m: "in (vào trong) + sight (nhìn) → nhìn thấu vào bên trong, hiểu sâu sắc.", e: "Sai: insight about the market → Đúng: insight into the market (insight into). Đếm được: valuable insights.", u: "gain/provide/offer insight into something; valuable insights. Rất hay trong IELTS Writing và báo cáo kinh doanh TOEIC.", f: "insightful (adj), insight (n)" },
  "integral": { m: "integer (nguyên vẹn) → không thể tách ra khỏi tổng thể; cùng gốc 'integrate', 'integrity'.", e: "Sai: integral for success → Đúng: integral to success (integral to). Nhấn âm 1 (UK): IN-te-gral.", u: "an integral part of; integral to the process. Trang trọng, dùng để nhấn mạnh vai trò thiết yếu trong IELTS Writing.", f: "integrate (v), integration (n), integrally (adv)" },
  "intermediate": { m: "inter- (ở giữa) + medius (giữa) → ở giữa hai mức, trung cấp; cùng gốc 'medium', 'middle'.", e: "Sai: intermedium level → Đúng: intermediate level. Nhấn âm 3: in-ter-ME-di-ate.", u: "intermediate level/stage/course; intermediate goods. Hay dùng để mô tả trình độ học viên hoặc giai đoạn giữa của quy trình.", f: "intermediary (n, adj), intermediate (adj, n)" },
  "manual": { m: "manus (bàn tay) → làm bằng tay; cùng gốc 'manufacture', 'manicure'.", e: "Sai: manual worker = nhân viên văn phòng → Đúng: manual worker là lao động chân tay. Manual (n) còn là sách hướng dẫn.", u: "manual labour/work; manual mode; a user manual. Đối lập automatic; hay gặp trong TOEIC sản xuất và hướng dẫn sử dụng.", f: "manually (adv), manual (n)" },
  "mature": { m: "Latin maturus (chín, đúng lúc) → chín chắn, trưởng thành; 'premature' là sớm quá, chưa chín.", e: "Sai: He is very maturity → Đúng: He is very mature (mature là tính từ, maturity là danh từ).", u: "mature student/market/attitude; reach maturity. Dùng trong IELTS khi bàn về trẻ em, thanh thiếu niên và trách nhiệm.", f: "maturity (n), maturely (adv), immature (adj), mature (v)" },
  "mediate": { m: "medius (ở giữa) → đứng ở giữa để hòa giải; cùng gốc 'media', 'middle'.", e: "Sai: mediate the conflict between with them → Đúng: mediate between the two sides / mediate a dispute. Đừng nhầm với meditate (thiền).", u: "mediate a dispute/conflict; mediate between parties. Trang trọng, dùng trong chủ đề pháp lý, lao động, quan hệ quốc tế.", f: "mediation (n), mediator (n)" },
  "medium": { m: "medius (giữa) → vật trung gian truyền tải thông tin; cùng gốc 'media', 'mediate'.", e: "Sai: social medias → Đúng: social media (media đã là số nhiều của medium). Số nhiều mediums chỉ dùng cho nghĩa khác.", u: "a medium of communication/instruction; medium-sized. TOEIC hay gặp medium-sized companies; IELTS dùng medium of instruction khi bàn giáo dục.", f: "media (n, plural), medium (adj)" },
  "military": { m: "miles, militis (người lính) → thuộc về lính, quân sự; cùng gốc 'militant', 'militia'.", e: "Lỗi nhấn âm: nhấn âm 1 MI-li-ta-ry. Sai: militarial → Đúng: military (bản thân đã là tính từ).", u: "military service/forces/action; the military. IELTS chủ đề nghĩa vụ quân sự bắt buộc; văn phong trung tính.", f: "militarism (n), militarize (v), militant (adj, n), militarily (adv)" },
  "minimal": { m: "minimus (nhỏ nhất) → ở mức nhỏ nhất; cùng gốc 'minimum', 'minimize'.", e: "Sai: minimum effect (khi muốn tính từ mô tả) → Đúng: minimal effect. Minimal nghĩa là rất nhỏ, không phải 'tối giản' trong mọi ngữ cảnh.", u: "minimal cost/effort/impact/risk. Dùng trong IELTS để nói tác động không đáng kể; trang trọng hơn very small.", f: "minimum (n, adj), minimize (v), minimally (adv)" },
  "mutual": { m: "Latin mutuus (trao đổi qua lại) → có qua có lại, lẫn nhau; cùng gốc 'mutate' (thay đổi).", e: "Sai: mutual each other → Đúng: mutual respect (mutual đã mang nghĩa lẫn nhau, không thêm each other).", u: "mutual respect/trust/benefit/understanding; a mutual friend. Rất tự nhiên trong IELTS khi bàn hợp tác quốc tế, các mối quan hệ.", f: "mutually (adv), mutuality (n)" },
  "norm": { m: "norma (thước vuông của thợ mộc) → thước chuẩn để đo; cùng gốc 'normal'.", e: "Sai: It is a norm to → Đúng: It is the norm to (dùng the norm khi nói điều phổ biến, bình thường).", u: "social/cultural norms; the norm; deviate from the norm. Rất hữu ích cho IELTS chủ đề văn hóa, xã hội.", f: "normal (adj), normative (adj), normally (adv), normalize (v)" },
  "overlap": { m: "over (lên trên) + lap (vạt, phủ) → phủ chồng lên nhau một phần.", e: "Lỗi nhấn âm: động từ o-ver-LAP, danh từ O-ver-lap. Sai: overlap each other with → Đúng: overlap with each other.", u: "overlap with something; a degree of overlap. Dùng khi hai môn học, trách nhiệm hay khái niệm trùng nhau một phần.", f: "overlap (n), overlapping (adj)" },
  "passive": { m: "pati (chịu đựng) → chịu tác động, không chủ động; cùng gốc 'patient', 'passion'.", e: "Sai: passive smoke → Đúng: passive smoking (hút thuốc thụ động). Đừng nhầm passive với positive.", u: "passive role/learning/voice/smoking. IELTS hay so sánh passive learning với active learning; passive voice là câu bị động.", f: "passively (adv), passivity (n)" },
  "portion": { m: "Latin portio (phần chia); gần với 'part', 'proportion' → một phần được chia ra.", e: "Sai: a large portion of student → Đúng: a large portion of students (sau of dùng danh từ số nhiều hoặc không đếm được).", u: "a large/significant portion of; a portion of food. IELTS Task 1 dùng để mô tả tỉ lệ thay cho part, proportion.", f: "portion (n, v), proportion (n), proportional (adj)" },
  "preliminary": { m: "pre- (trước) + limen (ngưỡng cửa) → trước khi bước qua ngưỡng cửa, bước sơ bộ; giống 'limit'.", e: "Lỗi nhấn âm: nhấn âm 2 pre-LI-mi-na-ry. Sai: preliminary results shows → Đúng: preliminary results show.", u: "preliminary findings/results/research/stage. Hay gặp trong báo cáo khoa học và thông báo TOEIC về kết quả ban đầu.", f: "preliminary (n), preliminaries (n)" },
  "protocol": { m: "Hy Lạp protos (đầu tiên) + kolla (keo dán) → trang đầu dán vào văn bản, ghi quy tắc; giống 'prototype'.", e: "Lỗi nhấn âm: nhấn âm 1 PRO-to-col. Sai: follow protocol rules strictly → Đúng: follow the protocol strictly (protocol đã là quy tắc).", u: "follow/break protocol; safety protocol; diplomatic protocol. Trang trọng, dùng trong y tế, ngoại giao, công nghệ thông tin.", f: "protocol (n) – ít biến thể, protocols (số nhiều)" },
  "qualitative": { m: "qualis (thuộc loại nào) → nói về chất lượng, đặc tính; cùng gốc 'quality'. Đối lập 'quantitative' (số lượng).", e: "Sai: qualitive / qualitive research → Đúng: qualitative research (đủ âm -ta-). Nhấn âm 1: QUA-li-ta-tive.", u: "qualitative research/data/analysis; qualitative difference. Thuật ngữ học thuật, thường đi cặp với quantitative trong báo cáo nghiên cứu.", f: "qualitatively (adv), quality (n), quantitative (adj)" },
  "refine": { m: "re- (lại) + fine (tinh, mịn) → làm cho tinh hơn lần nữa; lọc tạp chất, chỉnh sửa cho hoàn hảo.", e: "Sai: refine the oil to purity → Đúng: refine oil / refine a method. Sai: refinement (v) → Đúng: refine (v), refinement (n).", u: "refine a technique/method/process/skill; refined sugar; oil refinery. Hợp IELTS khi nói cải tiến dần một phương pháp.", f: "refinement (n), refinery (n), refined (adj)" },
  "relax": { m: "re- (trở lại) + laxare (nới ra) → nới lỏng trở lại; giống 'laxative', 'lax' (lỏng lẻo).", e: "Sai: I feel relax → Đúng: I feel relaxed (cảm giác dùng -ed). Nghĩa học thuật: relax rules = nới lỏng quy định.", u: "relax rules/restrictions/controls; relax regulations. Trong IELTS dùng nghĩa nới lỏng luật lệ; văn nói là thư giãn.", f: "relaxation (n), relaxed (adj), relaxing (adj)" },
  "restrain": { m: "re- (lùi lại) + stringere (thắt chặt) → kéo chặt lại, kìm giữ; cùng gốc 'strict', 'restrict'.", e: "Sai: restrain him to do it → Đúng: restrain him from doing it (restrain somebody from + V-ing). Đừng nhầm với restrict.", u: "restrain oneself; restrain from; restrain spending/inflation. Dùng trong chủ đề kinh tế (kiềm chế lạm phát) và hành vi.", f: "restraint (n), restrained (adj), unrestrained (adj)" },
  "revolution": { m: "re- (lại) + volvere (xoay, lăn) → xoay chuyển hoàn toàn; cùng gốc 'revolve', 'evolve'.", e: "Sai: revolution of technology → Đúng: technological revolution / revolution in technology. Nhấn âm 3: re-vo-LU-tion.", u: "industrial/digital/technological revolution; spark a revolution. Phổ biến trong IELTS chủ đề công nghệ, lịch sử.", f: "revolutionary (adj, n), revolutionize (v), revolve (v)" },
  "rigid": { m: "Latin rigere (cứng đờ) → cứng, không uốn được; cùng gốc 'rigour' (sự nghiêm ngặt).", e: "Sai: rigid rules are always good (hiểu như nghiêm túc) → Đúng: rigid mang nghĩa tiêu cực, cứng nhắc; nghiêm ngặt tích cực dùng strict.", u: "rigid rules/structure/schedule/thinking. Dùng trong IELTS khi phê phán hệ thống giáo dục hay quy định thiếu linh hoạt.", f: "rigidity (n), rigidly (adv)" },
  "route": { m: "Tiếng Pháp route (đường đi), từ Latin rupta via (đường xẻ ra); liên quan 'routine'.", e: "Lỗi phát âm: route đọc /ruːt/ (UK) hoặc /raʊt/ (US). Sai: route to go → Đúng: the route to the station.", u: "bus/delivery/shipping route; en route to. TOEIC hay gặp trong giao thông, vận chuyển hàng hóa.", f: "route (n, v), routing (n), routine (n)" },
  "scenario": { m: "Tiếng Ý scena (cảnh) → bản phác các cảnh; giống 'scene'. Kịch bản tình huống có thể xảy ra.", e: "Sai: in the worse scenario → Đúng: in the worst-case scenario. Số nhiều: scenarios. Nhấn âm 2: sce-NA-ri-o.", u: "worst-case/best-case scenario; a likely scenario; in this scenario. Hữu ích khi phân tích giả định trong IELTS Writing.", f: "scenario (n), scenarios (pl)" },
  "sphere": { m: "Hy Lạp sphaira (quả bóng) → hình cầu; nghĩa bóng là phạm vi, lĩnh vực; giống 'atmosphere', 'hemisphere'.", e: "Lỗi phát âm: ph đọc /f/, sphere /sfɪə/. Sai: in politic sphere → Đúng: in the political sphere.", u: "public/private/political sphere; sphere of influence. Học thuật, trang trọng; thay cho field hoặc area trong IELTS Writing.", f: "spherical (adj), hemisphere (n), atmosphere (n)" },
  "subordinate": { m: "sub- (dưới) + ordinare (sắp xếp) → được xếp ở hàng dưới; cùng gốc 'order', 'ordinary'.", e: "Sai: subordinate with the manager → Đúng: subordinate to the manager (subordinate to). Nhấn âm 2: su-BOR-di-nate.", u: "subordinate staff/role/position; be subordinate to. Dùng trong TOEIC về quản lý nhân sự; subordinate clause là mệnh đề phụ.", f: "subordination (n), subordinate (n, v), insubordinate (adj)" },
  "supplement": { m: "sub- (từ dưới) + plere (làm đầy) → làm đầy thêm phần thiếu; cùng gốc 'supply', 'complement'.", e: "Sai: supplement with the diet → Đúng: supplement the diet with vitamins (supplement A with B). Đừng nhầm supplement (bổ sung phần thiếu) với complement (bổ trợ cho hoàn chỉnh).", u: "supplement income/diet with something; vitamin supplements. TOEIC dùng supplement income; IELTS dùng khi bàn sức khỏe, dinh dưỡng.", f: "supplementary (adj), supplemental (adj), supplement (n)" },
  "suspend": { m: "sus- (dưới) + pendere (treo) → treo lên, tạm hoãn lại; cùng gốc 'pendant', 'depend'.", e: "Sai: He was suspended from school for one week ago → Đúng: He was suspended from school for one week (suspend from).", u: "suspend operations/payment/service; be suspended from work. TOEIC hay gặp trong thông báo tạm ngừng dịch vụ.", f: "suspension (n), suspended (adj), suspense (n)" },
  "team": { m: "Tiếng Anh cổ team (đàn gia súc cùng kéo xe) → nhóm cùng làm việc chung.", e: "Sai: Our team have good teamworks → Đúng: Our team has good teamwork (teamwork không đếm được; Anh-Anh vẫn chấp nhận team are).", u: "team member/leader/spirit; work as a team; team up with. TOEIC và IELTS Speaking rất hay dùng khi nói về công việc.", f: "teamwork (n), teammate (n), team (v)" },
  "temporary": { m: "tempus (thời gian) → chỉ kéo dài một thời gian; cùng gốc 'tempo', 'contemporary'.", e: "Sai: temporary là trạng từ trong 'He works temporary' → Đúng: He works temporarily. Nhấn âm 1: TEM-po-ra-ry.", u: "temporary job/staff/solution/closure. TOEIC rất hay gặp temporary closure, temporary workers; đối lập permanent.", f: "temporarily (adv), temporariness (n)" },
  "trigger": { m: "Gốc Hà Lan trekken (kéo) → cái cò súng được kéo; nghĩa bóng là kích hoạt, gây ra.", e: "Sai: trigger to a crisis → Đúng: trigger a crisis (trigger là ngoại động từ). Danh từ: a trigger for something.", u: "trigger a reaction/debate/crisis/alarm. Trung tính, hơi mạnh hơn cause; dùng trong IELTS để mô tả nguyên nhân trực tiếp.", f: "trigger (n), triggered (adj)" },
  "unify": { m: "uni- (một) + facere (làm) → làm thành một khối; cùng gốc 'unit', 'union', 'uniform'.", e: "Sai: unify with together → Đúng: unify the country (unify đã có nghĩa gộp lại). Nhấn âm 1: U-ni-fy.", u: "unify the country/team/system; a unified approach. Dùng trong IELTS chủ đề chính trị, văn hóa và hợp nhất tiêu chuẩn.", f: "unification (n), unified (adj), unity (n)" },
  "violate": { m: "violare (đối xử thô bạo) → xâm phạm luật lệ; liên quan 'violent' (bạo lực).", e: "Sai: violate to the law → Đúng: violate the law (không có to). Nhấn âm 1: VI-o-late.", u: "violate rules/rights/a contract/privacy. Trang trọng, hay gặp trong TOEIC hợp đồng và IELTS chủ đề quyền riêng tư.", f: "violation (n), violator (n)" },
  "vision": { m: "videre, visum (nhìn) → khả năng nhìn, tầm nhìn; cùng gốc 'visible', 'video', 'visit'.", e: "Sai: The company has a clear view about future → Đúng: The company has a clear vision for the future (vision for).", u: "a vision for the future; share a vision; vision statement; poor vision. TOEIC hay dùng trong lãnh đạo, chiến lược công ty.", f: "visionary (adj, n), visual (adj), visible (adj), visualize (v)" },
  "adjacent": { m: "ad- (sát bên) + jacent (nằm, từ Latin jacere) → nằm sát bên, liền kề.", e: "Sai: adjacent with the station → Đúng: adjacent to the station (adjacent đi với giới từ to).", u: "Trang trọng hơn 'next to': adjacent rooms, adjacent land, adjacent countries, adjacent to the city centre. Hay gặp trong bài mô tả bản đồ IELTS Task 1.", f: "adjacent (adj), adjacency (n), adjacently (adv)" },
  "albeit": { m: "Ghép từ all + be + it ('dù cho nó là vậy') → mặc dù, tuy là.", e: "Sai: Albeit it was raining, we went out → Đúng: Although it was raining... (albeit chỉ đi với cụm từ ngắn, không đi với mệnh đề đầy đủ).", u: "Rất trang trọng, dùng trước tính từ/cụm từ: a significant, albeit slow, improvement; albeit briefly. Phù hợp văn viết IELTS.", f: "albeit (conj) – không có dạng từ khác" },
  "assemble": { m: "as- (về phía) + semble (cùng nhau, như 'same', 'together') → đưa về một chỗ: tập hợp, lắp ráp.", e: "Sai: assemble together the furniture → Đúng: assemble the furniture (assemble đã có nghĩa 'cùng nhau', thêm together là thừa).", u: "assemble a team, assemble evidence, assemble parts/products, assembly line (dây chuyền lắp ráp). TOEIC hay gặp trong ngữ cảnh nhà máy, sản xuất.", f: "assembly (n), assembler (n), reassemble (v), disassemble (v)" },
  "collapse": { m: "col- (cùng nhau) + lapse (trượt, ngã) → mọi thứ cùng trượt xuống: sụp đổ.", e: "Sai: The building was collapsed → Đúng: The building collapsed (collapse là nội động từ, không dùng bị động).", u: "Nghĩa đen và bóng: the economy collapsed, the bridge collapsed, talks collapsed, the collapse of the company. Có thể dùng như danh từ: a sudden collapse.", f: "collapse (v/n), collapsible (adj)" },
  "colleague": { m: "col- (cùng) + league (liên minh, như 'league' bóng đá) → người cùng 'đội' ở nơi làm việc: đồng nghiệp.", e: "Sai: colleage, collegue → Đúng: colleague. Nhấn âm 1: COL-league; đừng nhầm với college (trường cao đẳng).", u: "Lịch sự, trang trọng hơn 'coworker': a close colleague, a former colleague, colleagues at work. Dùng nhiều trong email TOEIC.", f: "colleague (n), collegial (adj), collegiality (n)" },
  "compile": { m: "com- (cùng nhau) + pile (chất đống, như 'pile') → gom lại thành một chồng: biên soạn, tổng hợp.", e: "Sai: compile a new song (sáng tác) → Đúng: compose a new song. Compile là gom tài liệu có sẵn, không phải sáng tạo mới.", u: "compile a list/report/data/statistics, compiled by researchers. Trong IT: compile code (biên dịch). Trung tính, dùng nhiều trong văn học thuật.", f: "compilation (n), compiler (n), compile (v)" },
  "conceive": { m: "con- (hoàn toàn) + ceive (nắm, lấy, như receive) → 'nắm' được ý trong đầu: hình thành ý tưởng; cũng là thụ thai.", e: "Sai: conceive about a plan, viết conceve → Đúng: conceive a plan / conceive of an idea (dùng of, không dùng about; nhớ ei sau c).", u: "conceive an idea/a plan, conceive of something as..., hard to conceive (khó tưởng tượng). Trang trọng, hợp văn viết IELTS.", f: "concept (n), conception (n), conceivable (adj), inconceivable (adj), conceivably (adv)" },
  "convince": { m: "con- (hoàn toàn) + vince (chiến thắng, như victory) → thắng hoàn toàn trong tranh luận: thuyết phục.", e: "Sai: I am convinced him → Đúng: I convinced him / I am convinced that... Phân biệt: convince (làm ai tin) và persuade (làm ai hành động).", u: "convince somebody of something, convince somebody that..., be convinced that..., a convincing argument. Hay dùng trong IELTS Writing để nêu quan điểm.", f: "conviction (n), convincing (adj), convinced (adj), convincingly (adv), unconvincing (adj)" },
  "depress": { m: "de- (xuống) + press (ấn, nhấn) → ấn xuống: làm giảm (giá, nhu cầu) hoặc làm tinh thần chùng xuống.", e: "Sai: I am very depressing today → Đúng: I am very depressed today (-ed chỉ cảm xúc của người, -ing chỉ tính chất của sự việc).", u: "Kinh tế: depress prices/demand/wages, a depressed market. Tâm lý: depressing news. Danh từ depression vừa là trầm cảm vừa là suy thoái kinh tế.", f: "depression (n), depressed (adj), depressing (adj), depressive (adj), depressant (n)" },
  "encounter": { m: "en- (vào trong) + counter (ngược chiều, như 'counter') → đi ngược chiều rồi chạm mặt: gặp phải.", e: "Sai: encounter with many problems (động từ) → Đúng: encounter many problems (động từ encounter không cần with; danh từ mới dùng: an encounter with).", u: "Thường đi với điều khó khăn: encounter problems/difficulties/resistance/obstacles. Trang trọng hơn 'meet' hay 'face'; rất hợp IELTS Writing.", f: "encounter (v/n)" },
  "enormous": { m: "e- (ra ngoài) + norm (chuẩn mực, như 'normal') → vượt ra ngoài mức bình thường: to lớn.", e: "Sai: an enormous small problem, very enormous → Đúng: an enormous problem / absolutely enormous (tính từ cực cấp không đi với very).", u: "enormous amount/number/pressure/impact/potential. Mạnh hơn 'big', 'large'; giúp đa dạng từ vựng IELTS. Nhấn âm 2: e-NOR-mous.", f: "enormity (n), enormously (adv), enormousness (n)" },
  "forthcoming": { m: "forth (tiến ra phía trước) + coming (đang đến) → sắp tới.", e: "Sai: the forthcoming week (dùng sai sắc thái) → Đúng: next week / the forthcoming election. Forthcoming dùng cho sự kiện, ấn phẩm đã lên kế hoạch.", u: "the forthcoming conference/election/book. Nghĩa 2: not forthcoming = không sẵn lòng cung cấp (thông tin, tiền). Trang trọng, hay gặp trong thông báo TOEIC.", f: "forthcoming (adj) – dạng ghép từ forth + come" },
  "incline": { m: "in- (về phía) + cline (nghiêng, như 'decline', 'recline') → nghiêng về phía: có khuynh hướng.", e: "Sai: I am incline to agree → Đúng: I am inclined to agree (dùng tính từ inclined, có -ed). Nhấn: in-CLINE (động từ), IN-cline (danh từ: con dốc).", u: "Thường dùng be inclined to + V: be inclined to believe/think. Danh từ inclination (thiên hướng). Lịch sự khi nêu ý kiến dè dặt trong IELTS Speaking.", f: "inclination (n), inclined (adj), disinclined (adj), incline (n: con dốc)" },
  "integrity": { m: "Cùng gốc integer (số nguyên), integrate: integr- (nguyên vẹn, không bị chạm) → tính toàn vẹn; con người 'nguyên vẹn' về đạo đức: chính trực.", e: "Sai: He has many integrities → Đúng: He has great integrity (danh từ không đếm được). Nhấn âm 2: in-TEG-ri-ty.", u: "personal/professional integrity, a person of integrity, data integrity, structural integrity, territorial integrity. Trang trọng; hợp chủ đề đạo đức, chính trị.", f: "integrity (n), integral (adj), integrate (v), integration (n)" },
  "intrinsic": { m: "intra- (bên trong) + secus (theo) → thuộc về bên trong: nội tại. Trái nghĩa với extrinsic (bên ngoài).", e: "Sai: intrinsic in human nature → Đúng: intrinsic to human nature (đi với to). Đừng nhầm intrinsic (bên trong) với extrinsic (bên ngoài).", u: "intrinsic value, intrinsic motivation (động lực tự thân), intrinsic part of. Học thuật, hợp chủ đề giáo dục, tâm lý trong IELTS.", f: "intrinsic (adj), intrinsically (adv)" },
  "invoke": { m: "in- (vào, hướng tới) + voke (gọi, như 'voice', 'vocal') → gọi đến để dựa vào: viện dẫn (luật, điều khoản).", e: "Sai: invoke (gợi lên ký ức) → Đúng: evoke memories. Invoke là viện dẫn luật, quyền; evoke là gợi lên cảm xúc, hình ảnh.", u: "invoke a law/right/clause/principle, invoke the name of... Trang trọng, dùng trong pháp lý, chính trị; trong IT: invoke a function (gọi hàm).", f: "invocation (n), invoke (v)" },
  "levy": { m: "Gốc Latin levare (nâng lên, như 'lever', 'elevate') → nâng thêm tiền thu: thuế, khoản thu.", e: "Sai: levy a tax to imports → Đúng: levy a tax on imports (levy đi với on).", u: "Vừa là danh từ vừa là động từ: impose a levy, a levy on fuel, levy taxes/fines. Văn phong chính thức, kinh tế, hành chính; gặp trong TOEIC.", f: "levy (n/v)" },
  "likewise": { m: "like (giống) + wise (cách thức, như 'clockwise', 'otherwise') → theo cách giống vậy: tương tự.", e: "Sai: Likewise, but traffic is worse (dùng như từ đối lập) → Đúng: Similarly/Likewise, traffic is also worse. Likewise chỉ nêu ý tương đồng, không đối lập.", u: "Từ nối trang trọng: Likewise, ... đầu câu để thêm ví dụ cùng chiều; do likewise (làm theo). Hội thoại: 'Nice to meet you.' – 'Likewise.'", f: "likewise (adv) – ghép từ like + -wise" },
  "nonetheless": { m: "none + the + less → 'chẳng kém đi chút nào' dù có điều trên: tuy nhiên, dù vậy.", e: "Sai: none the less, nonethless (sai chính tả kiểu Mỹ) → Đúng: nonetheless (viết liền). Sai: Nonetheless it is hard but... (thừa liên từ).", u: "Từ nối trang trọng, tương đương nevertheless: It was expensive; nonetheless, it was worth it. Dùng sau dấu chấm phẩy hoặc đầu câu trong IELTS Writing.", f: "nonetheless (adv) – đồng nghĩa nevertheless" },
  "notwithstanding": { m: "not + withstanding (chống lại, như 'withstand') → không gì chống lại được: bất chấp, mặc dù.", e: "Sai: Notwithstanding the rain was heavy → Đúng: Notwithstanding the heavy rain (giới từ, theo sau là cụm danh từ, không phải mệnh đề).", u: "Rất trang trọng, văn bản pháp lý: notwithstanding the above, these difficulties notwithstanding (có thể đứng sau danh từ). Văn thường nên dùng despite.", f: "notwithstanding (prep/adv)" },
  "odd": { m: "Liên tưởng 'odd one out' (vật lạc loài) → kỳ lạ; số lẻ 1, 3, 5 'lạc' khi chia đôi.", e: "Sai: odds number → Đúng: odd number (số lẻ). Odds (n, số nhiều) là xác suất: the odds are against us.", u: "odd behaviour, it is odd that..., odd numbers, odd jobs (việc vặt), 30-odd people (hơn 30 người). Thân mật đến trung tính; văn trang trọng dùng strange.", f: "oddly (adv), oddity (n), oddness (n), odds (n)" },
  "ongoing": { m: "on (tiếp tục, như 'go on') + going (đang diễn ra) → vẫn còn đang tiếp diễn.", e: "Sai: The project is ongoing yesterday → Đúng: The project was ongoing / is still ongoing (cần chia đúng thì cho động từ be).", u: "ongoing research/debate/process/negotiations/support. Trang trọng hơn 'continuing'; hay dùng trong IELTS Writing và email công việc TOEIC.", f: "ongoing (adj) – ghép từ go on" },
  "panel": { m: "Gốc Latin pannus (mảnh vải) → mảnh, tấm (solar panel); nhóm người ngồi sau một tấm bàn: hội đồng.", e: "Sai: a panel of expert → Đúng: a panel of experts (danh từ sau of phải ở số nhiều). Chính tả: panellist (UK) / panelist (US).", u: "a panel of experts/judges, panel discussion, solar panel, control panel. TOEIC: hội thảo, hội nghị; IELTS: chủ đề năng lượng, công nghệ.", f: "panel (n), panellist UK / panelist US (n), panelling (n)" },
  "persist": { m: "per- (xuyên suốt) + sist (đứng, như 'insist', 'resist') → đứng vững đến cùng: kiên trì, kéo dài.", e: "Sai: persist on doing it → Đúng: persist in doing it (persist đi với in; persist with something cũng được).", u: "problems persist, symptoms persist, persist in + V-ing. Tính từ persistent (dai dẳng, bền bỉ) rất hữu ích trong IELTS Writing.", f: "persistence (n), persistent (adj), persistently (adv)" },
  "pose": { m: "Gốc Latin ponere (đặt, như 'position', 'propose') → đặt ra: pose a question, pose a threat.", e: "Sai: pose a danger for people → Đúng: pose a danger to people (pose a threat/risk đi với to).", u: "pose a threat/risk/challenge/problem/question. Trang trọng, rất phổ biến trong IELTS Writing. Nghĩa khác: tạo dáng chụp ảnh (pose for a photo).", f: "pose (v/n), poser (n)" },
  "reluctance": { m: "re- (ngược lại) + luct (vùng vẫy, chống cự) → vùng vẫy chống lại: miễn cưỡng, không muốn.", e: "Sai: reluctance of changing → Đúng: reluctance to change (đi với to + V). Tính từ: be reluctant to do, không phải reluctant of.", u: "show reluctance, with great reluctance, a reluctance to accept/invest. Tính từ reluctant phổ biến hơn: reluctant to admit. Hợp mọi văn phong.", f: "reluctant (adj), reluctantly (adv), reluctance (n)" },
  "so-called": { m: "so (như vậy) + called (được gọi) → 'được gọi là như vậy' nhưng có thể không đúng: cái gọi là.", e: "Sai: so called (thiếu gạch nối trước danh từ) → Đúng: so-called experts. Lưu ý: so-called thường mang ý nghi ngờ, mỉa mai.", u: "the so-called experts, so-called 'smart' devices. Có thể trung tính (tên thường gọi) hoặc chê bai. Cẩn thận sắc thái trong IELTS Writing.", f: "so-called (adj) – tính từ ghép" },
  "straightforward": { m: "straight (thẳng) + forward (về phía trước) → đi thẳng, không vòng vèo: đơn giản, dễ hiểu; người thẳng thắn.", e: "Sai: straight forward, straightfoward → Đúng: straightforward (viết liền một từ, đủ chữ r trong forward).", u: "a straightforward process/task/answer/question, relatively straightforward. Tả người: thẳng thắn. Hay dùng trong IELTS Speaking thay cho 'easy'.", f: "straightforward (adj), straightforwardly (adv), straightforwardness (n)" },
  "undergo": { m: "under (bên dưới) + go (đi) → đi qua bên dưới, chịu đựng một quá trình: trải qua.", e: "Sai: undergo through changes → Đúng: undergo changes (không thêm through). Chia bất quy tắc: undergo – underwent – undergone.", u: "undergo surgery/treatment/training/changes/a transformation. Trang trọng; chủ thể thường chịu tác động. Hay dùng trong IELTS Task 1 mô tả sự thay đổi.", f: "undergo (v), underwent, undergone" },
  "whereby": { m: "where (nơi đó) + by (nhờ, bằng) → nhờ đó, theo cách đó.", e: "Sai: a system whereby it helps people save → Đúng: a system whereby people save money (whereby thay cho 'by which', theo sau là mệnh đề đầy đủ).", u: "Rất trang trọng: a system/process/agreement whereby... Tương đương 'by which', 'through which'. Hợp văn học thuật, hợp đồng; hiếm dùng khi nói.", f: "whereby (adv) – cùng nhóm whereas, wherein" }
}); })(typeof self !== "undefined" ? self : this);
